        assertThat(new String(delivery,java.nio.charset.StandardCharsets.ISO_8859_1)).doesNotContain(token);
        for(int i=0;i<15;i++) { assertThat(requestReset(UUID.randomUUID()+"@example.com").body()).isEqualTo(expected); }
