        assertThatThrownBy(()->owner.update("UPDATE credential_operation SET state='PREPARED' WHERE id=?",operation)).isInstanceOf(org.springframework.dao.DataAccessException.class);
        assertThatThrownBy(()->owner.update("DELETE FROM credential_operation WHERE id=?",operation)).isInstanceOf(org.springframework.dao.DataAccessException.class);
