    private HttpResponse<String> requestReset(String email) throws Exception { return send("POST","/password-reset-requests",JSON.writeValueAsString(Map.of("email",email))); }
    private HttpResponse<String> reset(String token,String password) throws Exception { return send("POST","/password-resets",resetBody(token,password)); }
    private static String resetBody(String token,String password) { return JSON.writeValueAsString(Map.of("token",token,"newPassword",password)); }
    private static String passwordBody(String password) { return JSON.writeValueAsString(Map.of("newPassword",password)); }
    private HttpResponse<String> loginWithPassword(String email,String password) throws Exception {
        var body=JSON.readTree(loginBody(email,"NATIVE",null));((tools.jackson.databind.node.ObjectNode)body).put("password",password);
        return send("POST","/login",JSON.writeValueAsString(body));
    }
    private static String resetToken(UUID account) {
        var row=owner.queryForMap("SELECT p.id,d.encrypted_token FROM password_reset_proof p JOIN password_reset_delivery d ON d.proof_id=p.id WHERE p.account_id=? AND p.state='ACTIVE'",account);
        return app.getBean(com.narudzbine.identity.application.ResetDeliveryCipher.class).decrypt((UUID)row.get("id"),(byte[])row.get("encrypted_token"));
    }
    private static void assertPasswordNotice(UUID account,String locale) {
        var row=owner.queryForMap("SELECT n.locale,(SELECT count(*) FROM outbox_event e WHERE e.notice_id=n.id) AS emails FROM security_notice n WHERE n.recipient_account_id=? AND n.event_key='PASSWORD_CHANGED'",account);
        assertThat(row.get("locale")).isEqualTo(locale);assertThat(((Number)row.get("emails")).intValue()).isEqualTo(1);
    }
    private static byte[] digest(String token) {
        try { return java.security.MessageDigest.getInstance("SHA-256").digest(token.getBytes(java.nio.charset.StandardCharsets.US_ASCII)); }
        catch(java.security.GeneralSecurityException e) { throw new AssertionError(e); }
    }

    static class FakeMutator implements com.narudzbine.identity.api.PasswordCredentialMutator {
        final AtomicInteger calls=new AtomicInteger();
        final Map<UUID,PasswordCredentialVerifier.Subject> applied=new ConcurrentHashMap<>();
        volatile Outcome outcome=Outcome.APPLIED;
        volatile boolean applyUnknown,allowReconcile;
        volatile java.util.function.Consumer<UUID> before=operation -> {};
        void reset() { calls.set(0);outcome=Outcome.APPLIED;applyUnknown=false;allowReconcile=false;before=operation -> {}; }
        public Outcome change(PasswordCredentialVerifier.Subject subject,UUID operation,String password) {
            assertThat(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive()).isFalse();
            calls.incrementAndGet();before.accept(operation);
            if(outcome==Outcome.APPLIED || applyUnknown) {
                String email=PROVIDER.subjects.entrySet().stream().filter(e -> e.getValue().equals(subject)).findFirst().orElseThrow().getKey();
                PROVIDER.passwords.put(email,password);applied.put(operation,subject);
            }
            return outcome;
        }
        public Outcome reconcile(PasswordCredentialVerifier.Subject subject,UUID operation) {
            assertThat(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive()).isFalse();
            return allowReconcile && subject.equals(applied.get(operation))?Outcome.APPLIED:Outcome.UNKNOWN;
        }
    }

    @Test
    void browserBootstrapLoginStableCsrfAndRepeatLogout() throws Exception {
        var account = account();
        var bootstrap = send("GET", "/bootstrap", null, "Origin", "https://app.example");
        assertThat(bootstrap.statusCode()).isEqualTo(200);
        String preauth = cookie(bootstrap, "__Host-narudzbine_preauth");
        assertThat(bootstrap.headers().firstValue("Set-Cookie").orElseThrow()).contains("Secure", "HttpOnly", "Max-Age=300");
        var logged = send("POST", "/login", loginBody(account, "BROWSER", json(bootstrap).path("nonce").asString()),
                "Origin", "https://app.example", "Cookie", preauth);
        assertThat(logged.statusCode()).isEqualTo(200);
        var body = json(logged);
        assertThat(body.path("bearerToken").isNull()).isTrue();
        assertThat(body.path("account").path("organizationId").isNull()).isTrue();
        assertThat(body.path("account").path("homeLocationId").isNull()).isTrue();
        assertThat(body.path("account").path("revision").asString()).matches("[A-Za-z0-9_-]{43}");
        assertThat(body.path("session").path("createdAt").asString()).matches(".*\\.\\d{3}Z");
        String session = cookie(logged, "__Host-narudzbine_session");
        String csrf = body.path("csrfToken").asString();
        assertThat(logged.body()).doesNotContain(session.substring(session.indexOf('=') + 1));
        for (int index = 0; index < 2; index++) {
            var current = send("GET", "/csrf", null, "Origin", "https://app.example", "Cookie", session);
            assertThat(current.statusCode()).isEqualTo(200);
            assertThat(json(current).path("csrfToken").asString()).isEqualTo(csrf);
        }
        assertProblem(send("POST", "/logout", null, "Origin", "https://app.example", "Cookie", session), 403, "CSRF_REJECTED");
        for (int index = 0; index < 2; index++) {
            var logout = send("POST", "/logout", null, "Origin", "https://app.example", "Cookie", session, "X-CSRF-Token", csrf);
            assertThat(logout.statusCode()).isEqualTo(204);
            assertThat(logout.headers().firstValue("Set-Cookie").orElseThrow()).contains("Max-Age=0");
        }
        assertProblem(send("GET", "/sessions", null, "Cookie", session), 401, "INVALID_SESSION");
    }

