    @Test
    void ownAccountReadAndLanguageChangesRespectRevisionNullAndNoOpSemantics() throws Exception {
        var logged = send("POST", "/login", loginBody(account(), "NATIVE", null));
        String token = json(logged).path("bearerToken").asString();
        var initial = json(logged).path("account");
        String revision = initial.path("revision").asString();
        UUID id = UUID.fromString(initial.path("id").asString());
        CLOCK.advance(60);
        var read = send("GET", "/me", null, "Authorization", "Bearer " + token);
        assertThat(json(read)).isEqualTo(initial);
        assertThat(read.body()).doesNotContain(token);
        var before = owner.queryForObject("SELECT last_qualified_activity_at FROM application_session WHERE account_id = ?",
                java.sql.Timestamp.class, id);
        var changed = send("PATCH", "/me/language", languageBody(revision, "SR-latn-rs"), "Authorization", "Bearer " + token);
        assertThat(changed.statusCode()).isEqualTo(200);
        assertThat(json(changed).path("languageOverride").asString()).isEqualTo("sr-Latn-RS");
        String current = json(changed).path("revision").asString();
        assertThat(current).isNotEqualTo(revision);
        assertThat(owner.queryForObject("SELECT last_qualified_activity_at FROM application_session WHERE account_id = ?",
                java.sql.Timestamp.class, id)).isAfter(before);
        for (String body : java.util.List.of(languageBody(current, "sr-Latn-RS"), JSON.writeValueAsString(Map.of("expectedRevision", current)))) {
            CLOCK.advance(1);
            var unchanged = send("PATCH", "/me/language", body, "Authorization", "Bearer " + token);
            assertThat(unchanged.statusCode()).isEqualTo(200);
            assertThat(json(unchanged)).isEqualTo(json(changed));
        }
        assertProblem(send("PATCH", "/me/language", languageBody(revision, "sr-Latn-RS"), "Authorization", "Bearer " + token),
                409, "REVISION_CONFLICT");
        var reset = send("PATCH", "/me/language", languageBody(current, null), "Authorization", "Bearer " + token);
        assertThat(reset.statusCode()).isEqualTo(200);
        assertThat(json(reset).path("languageOverride").isNull()).isTrue();
        assertThat(json(reset).path("revision").asString()).isNotEqualTo(current);
        assertThat(languageAudits(id)).isEqualTo(2);
        assertThat(owner.queryForObject("SELECT request_id FROM audit_event WHERE actor_id = ? AND action = 'ACCOUNT_LANGUAGE_CHANGED' ORDER BY occurred_at DESC LIMIT 1",
                UUID.class, id).toString()).isEqualTo(reset.headers().firstValue("X-Request-Id").orElseThrow());
        var preferences = inboxPreferences(token);
        assertThat(preferences.path("id").asString()).isEqualTo(id.toString());
        assertThat(preferences.path("languageOverride").isNull()).isTrue();
        assertThat(preferences.path("events").size()).isEqualTo(6);
        assertThat(preferences.path("revision")).isNotEqualTo(json(reset).path("revision"));
        assertThat(send("PUT", "/me", "{}", "Authorization", "Bearer " + token).statusCode()).isEqualTo(422);
    }

    @Test
    void languageUpdateRejectsInvalidBodiesAliasesAndForeignRevisionsWithoutChanges() throws Exception {
        var logged = send("POST", "/login", loginBody(account(), "NATIVE", null));
        var other = send("POST", "/login", loginBody(account(), "NATIVE", null));
        String token = json(logged).path("bearerToken").asString();
        var initial = json(logged).path("account");
        String revision = initial.path("revision").asString();
        for (String language : java.util.List.of("sr", "sr_Latn_RS", "en-US", " en", "en ", "", "fr-FR")) {
            var failed = send("PATCH", "/me/language", languageBody(revision, language), "Authorization", "Bearer " + token);
            assertProblem(failed, 422, "VALIDATION_FAILED");
            assertThat(json(failed).path("errors").get(0).path("path").asString()).isEqualTo("/languageOverride");
        }
        var independent = send("PATCH", "/me/language", "{\"expectedRevision\":null,\"languageOverride\":42}", "Authorization", "Bearer " + token);
        assertProblem(independent, 422, "VALIDATION_FAILED");
        assertThat(json(independent).path("errors").size()).isEqualTo(2);
        assertProblem(send("PATCH", "/me/language", "{\"expectedRevision\":\"a\",\"expectedRevision\":\"b\"}", "Authorization", "Bearer " + token), 400, "MALFORMED_JSON");
        assertProblem(send("PATCH", "/me/language", "{} {}", "Authorization", "Bearer " + token), 400, "MALFORMED_JSON");
        assertProblem(send("PATCH", "/me/language", "x".repeat(16385), "Authorization", "Bearer " + token), 413, "PAYLOAD_TOO_LARGE");
        assertProblem(send("PATCH", "/me/language", JSON.writeValueAsString(Map.of("expectedRevision", revision, "email", "not-allowed@example.test")),
                "Authorization", "Bearer " + token), 422, "VALIDATION_FAILED");
        for (String bad : java.util.List.of("forged", json(other).path("account").path("revision").asString())) {
            assertProblem(send("PATCH", "/me/language", languageBody(bad, "en"), "Authorization", "Bearer " + token), 409, "REVISION_CONFLICT");
        }
        assertProblem(send("GET", "/me?accountId=other", null, "Authorization", "Bearer " + token), 422, "VALIDATION_FAILED");
        assertProblem(send("GET", "/me", "{}", "Authorization", "Bearer " + token), 422, "VALIDATION_FAILED");
        assertThat(json(send("GET", "/me", null, "Authorization", "Bearer " + token))).isEqualTo(initial);
        assertThat(languageAudits(UUID.fromString(initial.path("id").asString()))).isZero();
    }

    @Test
    void languageRequiresBrowserCsrfAndHasScopedCorsAndManagementDenial() throws Exception {
        var boot = send("GET", "/bootstrap", null, "Origin", "https://app.example");
        var logged = send("POST", "/login", loginBody(account(), "BROWSER", json(boot).path("nonce").asString()),
                "Origin", "https://app.example", "Cookie", cookie(boot, "__Host-narudzbine_preauth"));
        String session = cookie(logged, "__Host-narudzbine_session");
        String csrf = json(logged).path("csrfToken").asString();
        String body = languageBody(json(logged).path("account").path("revision").asString(), "bs-Latn-BA");
        assertProblem(send("PATCH", "/me/language", body, "Cookie", session, "X-CSRF-Token", csrf), 403, "CSRF_REJECTED");
        assertProblem(send("PATCH", "/me/language", body, "Origin", "https://app.example", "Cookie", session), 403, "CSRF_REJECTED");
        assertProblem(send("PATCH", "/me/language", body, "Origin", "https://app.example", "Cookie", session, "X-CSRF-Token", "invalid"), 403, "CSRF_REJECTED");
        var preflight = send("OPTIONS", "/me/language", null, "Origin", "https://app.example", "Access-Control-Request-Method", "PATCH",
                "Access-Control-Request-Headers", "Content-Type,X-CSRF-Token");
        assertThat(preflight.statusCode()).isEqualTo(200);
        assertThat(preflight.headers().firstValue("Access-Control-Allow-Origin")).contains("https://app.example");
        var changed = send("PATCH", "/me/language", body, "Origin", "https://app.example", "Cookie", session, "X-CSRF-Token", csrf);
        assertThat(changed.statusCode()).isEqualTo(200);
        assertThat(changed.headers().allValues("Set-Cookie")).isEmpty();
        assertThat(send("GET", "/me", null, "Cookie", session).statusCode()).isEqualTo(200);
        assertProblem(send("GET", "/me", null, "Origin", "https://evil.example", "Cookie", session), 403, "CSRF_REJECTED");
        assertThat(client.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:" + management + "/api/v1/me"))
                .header("Cookie", session).build(), HttpResponse.BodyHandlers.ofString()).statusCode()).isEqualTo(404);
    }

