    @Test
    void allBusinessRolesInBothCountriesCanChangeOnlyTheirOwnLanguage() throws Exception {
        for (String country : java.util.List.of("RS", "BA")) {
            for (String type : java.util.List.of("BUYER", "VENDOR")) {
                for (String role : java.util.List.of("OWNER", "ADMIN", "STAFF")) {
                    var logged = send("POST", "/login", loginBody(businessAccount(country, type, role), "NATIVE", null));
                    assertThat(logged.statusCode()).isEqualTo(200);
                    var original = json(logged).path("account");
                    String token = json(logged).path("bearerToken").asString();
                    var result = send("PATCH", "/me/language", languageBody(original.path("revision").asString(), "EN"),
                            "Authorization", "Bearer " + token);
                    assertThat(result.statusCode()).isEqualTo(200);
                    assertThat(json(result).path("languageOverride").asString()).isEqualTo("en");
                    for (String field : java.util.List.of("id", "email", "organizationId", "role", "kind")) {
                        assertThat(json(result).path(field)).isEqualTo(original.path(field));
                    }
                    UUID id = UUID.fromString(original.path("id").asString());
                    var audit = owner.queryForMap("SELECT country, organization_id FROM audit_event WHERE actor_id = ? AND action = 'ACCOUNT_LANGUAGE_CHANGED'", id);
                    assertThat(audit.get("country")).isEqualTo(country);
                    assertThat(audit.get("organization_id").toString()).isEqualTo(original.path("organizationId").asString());
                    UUID organization = UUID.fromString(original.path("organizationId").asString());
                    assertThat(owner.queryForObject("SELECT currency FROM organization WHERE id = ?", String.class, organization))
                            .isEqualTo(country.equals("RS") ? "RSD" : "BAM");
                    owner.update("UPDATE organization SET state = 'SUSPENDED' WHERE id = ?", organization);
                    assertProblem(send("GET", "/me", null, "Authorization", "Bearer " + token), 401, "INVALID_SESSION");
                }
            }
        }
    }

