    private static String businessAccount(String country, String type, String role) {
        UUID id = app.getBean(com.narudzbine.shared.api.UuidGenerator.class).next();
        UUID organization = app.getBean(com.narudzbine.shared.api.UuidGenerator.class).next();
        UUID ownerId = role.equals("OWNER") ? id : app.getBean(com.narudzbine.shared.api.UuidGenerator.class).next();
        String email = id + "@example.com";
        var subject = new PasswordCredentialVerifier.Subject(UUID.randomUUID(), UUID.randomUUID());
        setup.executeWithoutResult(status -> {
            owner.update("INSERT INTO account_identity(id,kind,email,email_verified,display_name,state) VALUES (?,'BUSINESS',?,true,'Test','ACTIVE')", ownerId, ownerId + "@example.com");
            if (!ownerId.equals(id)) {
                owner.update("INSERT INTO account_identity(id,kind,email,email_verified,display_name,state) VALUES (?,'BUSINESS',?,true,'Test','ACTIVE')", id, email);
            }
            owner.update("""
                    INSERT INTO organization(id,owner_account_id,type,country,currency,display_name,legal_name,registration_identifier,
                        address_line1,address_city,address_postal_code,address_country,default_language,state)
                    VALUES (?,?,?,?,?,'Test','Test',?,'Test','Test','00000',?,'bs-Latn-BA','ACTIVE')
                    """, organization, ownerId, type, country, country.equals("RS") ? "RSD" : "BAM", organization.toString(), country);
            owner.update("INSERT INTO business_account(id,organization_id,role) VALUES (?,?,'OWNER')", ownerId, organization);
            if (!ownerId.equals(id)) { owner.update("INSERT INTO business_account(id,organization_id,role) VALUES (?,?,?)", id, organization, role); }
            owner.update("INSERT INTO managed_password_identity(account_id,tenant_id,provider_user_id) VALUES (?,?,?)", id, subject.tenantId(), subject.userId());
        });
        PROVIDER.subjects.put(email, subject);
        return email;
    }

