    @Test
    void organizationAuditFailureRollsBackSettingsAndActivityAndRoleReductionIsImmediate() throws Exception {
        var login = send("POST", "/login", loginBody(businessAccount("BA", "BUYER", "ADMIN"), "NATIVE", null));
        String token = json(login).path("bearerToken").asString();
        UUID actor = UUID.fromString(json(login).path("account").path("id").asString());
        var original = json(send("GET", "/organization", null, "Authorization", "Bearer " + token));
        UUID org = UUID.fromString(original.path("id").asString());
        var activity = owner.queryForObject("SELECT last_qualified_activity_at FROM application_session WHERE account_id = ?", java.sql.Timestamp.class, actor);
        var values = organizationBody(original); values.put("displayName", "Changed");
        CLOCK.advance(60); owner.execute("REVOKE INSERT ON audit_event FROM http_runtime");
        try {
            assertProblem(send("PUT", "/organization", JSON.writeValueAsString(values), "Authorization", "Bearer " + token), 503, "SERVICE_UNAVAILABLE");
        } finally { owner.execute("GRANT SELECT,INSERT ON audit_event TO http_runtime"); }
        assertThat(owner.queryForObject("SELECT last_qualified_activity_at FROM application_session WHERE account_id = ?", java.sql.Timestamp.class, actor)).isEqualTo(activity);
        assertThat(owner.queryForObject("SELECT display_name FROM organization WHERE id = ?", String.class, org)).isEqualTo("Test");
        assertThat(organizationAudits(org)).isZero();
        owner.update("UPDATE business_account SET role = 'STAFF' WHERE id = ?", actor);
        assertProblem(send("PUT", "/organization", JSON.writeValueAsString(values), "Authorization", "Bearer " + token), 403, "FORBIDDEN");
        assertThat(send("GET", "/organization", null, "Authorization", "Bearer " + token).statusCode()).isEqualTo(200);
        owner.update("UPDATE organization SET state = 'SUSPENDED' WHERE id = ?", org);
        assertProblem(send("GET", "/organization", null, "Authorization", "Bearer " + token), 401, "INVALID_SESSION");
    }

    @Test
    void organizationBrowserUpdateUsesCsrfCorsAndExactDecimalCoordinates() throws Exception {
        var boot = send("GET", "/bootstrap", null, "Origin", "https://app.example");
        var login = send("POST", "/login", loginBody(businessAccount("RS", "VENDOR", "OWNER"), "BROWSER", json(boot).path("nonce").asString()),
                "Origin", "https://app.example", "Cookie", cookie(boot, "__Host-narudzbine_preauth"));
        String session = cookie(login, "__Host-narudzbine_session");
        String csrf = json(login).path("csrfToken").asString();
        var original = json(send("GET", "/organization", null, "Cookie", session));
        var body = organizationBody(original); var address = addressBody(original.path("registeredAddress"));
        address.put("latitude", new java.math.BigDecimal("45.1234567890123456789")); address.put("longitude", new java.math.BigDecimal("20.0000"));
        body.put("registeredAddress", address);
        String payload = JSON.writeValueAsString(body);
        assertProblem(send("PUT", "/organization", payload, "Origin", "https://app.example", "Cookie", session), 403, "CSRF_REJECTED");
        assertProblem(send("PUT", "/organization", payload, "Cookie", session, "X-CSRF-Token", csrf), 403, "CSRF_REJECTED");
        assertThat(send("OPTIONS", "/organization", null, "Origin", "https://app.example", "Access-Control-Request-Method", "PUT",
                "Access-Control-Request-Headers", "Content-Type,X-CSRF-Token").statusCode()).isEqualTo(200);
        var result = send("PUT", "/organization", payload, "Origin", "https://app.example", "Cookie", session, "X-CSRF-Token", csrf);
        assertThat(result.statusCode()).isEqualTo(200);
        assertThat(result.body()).contains("45.1234567890123456789");
        assertThat(result.headers().allValues("Set-Cookie")).isEmpty();
        assertThat(client.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:" + management + "/api/v1/organization"))
                .header("Cookie", session).build(), HttpResponse.BodyHandlers.ofString()).statusCode()).isEqualTo(404);
        assertThat(send("GET", "/organization/locations", null, "Cookie", session).statusCode()).isEqualTo(200);
    }

    @Test
    void updatedBuyerRestrictionAppliesToSubsequentStaffAuthorization() throws Exception {
        var login = send("POST", "/login", loginBody(businessAccount("RS", "BUYER", "OWNER"), "NATIVE", null));
        String token = json(login).path("bearerToken").asString();
        var original = json(send("GET", "/organization", null, "Authorization", "Bearer " + token));
        UUID org = UUID.fromString(original.path("id").asString());
        UUID staff = UUID.randomUUID();
        setup.executeWithoutResult(status -> {
            owner.update("INSERT INTO account_identity(id,kind,email,email_verified,display_name,state) VALUES (?,'BUSINESS',?,true,'Staff','ACTIVE')", staff, staff + "@example.com");
            owner.update("INSERT INTO business_account(id,organization_id,role) VALUES (?,?,'STAFF')", staff, org);
        });
        var boundary = new TransactionTemplate(app.getBean(org.springframework.transaction.PlatformTransactionManager.class));
        var access = app.getBean(com.narudzbine.identity.api.BusinessAuthorization.class);
        assertThat(boundary.<com.narudzbine.identity.api.BusinessScope>execute(status -> access.require(staff, org, com.narudzbine.organizations.api.Country.RS,
                com.narudzbine.identity.api.BusinessCapability.SUBMIT_OR_CANCEL_BUYER_ORDER))).isNotNull();
        var values = organizationBody(original); values.put("staffSubmissionRestricted", true);
        assertThat(send("PUT", "/organization", JSON.writeValueAsString(values), "Authorization", "Bearer " + token).statusCode()).isEqualTo(200);
        assertThatThrownBy(() -> boundary.execute(status -> access.require(staff, org, com.narudzbine.organizations.api.Country.RS,
                com.narudzbine.identity.api.BusinessCapability.SUBMIT_OR_CANCEL_BUYER_ORDER)))
                .isInstanceOf(com.narudzbine.identity.api.BusinessAccessDenied.class);
        assertThat(boundary.<com.narudzbine.identity.api.BusinessScope>execute(status -> access.require(staff, org, com.narudzbine.organizations.api.Country.RS,
                com.narudzbine.identity.api.BusinessCapability.PREPARE_BUYER_ORDER))).isNotNull();
    }

    @Test
    void locationsRespectCountryTypeRoleAndOrganizationBoundaries() throws Exception {
        for (String country : java.util.List.of("RS","BA")) {
            for (String type : java.util.List.of("BUYER","VENDOR")) {
                for (String role : java.util.List.of("OWNER","ADMIN","STAFF")) {
                    String token=nativeToken(businessAccount(country,type,role));
                    var body=locationBody(country,type.equals("BUYER"));
                    var created=send("POST","/organization/locations",JSON.writeValueAsString(body),"Authorization","Bearer "+token);
                    assertThat(created.statusCode()).isEqualTo(role.equals("STAFF")?403:201);
                    var page=json(send("GET","/organization/locations?includeTotal=true",null,"Authorization","Bearer "+token));
                    assertThat(page.path("total").asInt()).isEqualTo(role.equals("STAFF")?0:1);
                    if (!role.equals("STAFF")) {
                        String path="/organization/locations/"+body.get("id");
                        assertThat(json(send("GET",path,null,"Authorization","Bearer "+token))).isEqualTo(json(created));
                        var edits=locationUpdate(json(created)); edits.put("name","Changed");
                        assertThat(send("PUT",path,JSON.writeValueAsString(edits),"Authorization","Bearer "+token).statusCode()).isEqualTo(200);
                        String outsider=nativeToken(businessAccount(country,type,"OWNER"));
                        assertProblem(send("GET",path,null,"Authorization","Bearer "+outsider),404,"NOT_FOUND");
                        assertProblem(send("POST","/organization/locations",JSON.writeValueAsString(body),"Authorization","Bearer "+outsider),404,"NOT_FOUND");
                    }
                }
            }
        }
        String platform=nativeToken(account());
        assertProblem(send("GET","/organization/locations",null,"Authorization","Bearer "+platform),404,"NOT_FOUND");
        assertProblem(send("POST","/organization/locations",JSON.writeValueAsString(locationBody("RS",false)),"Authorization","Bearer "+platform),404,"NOT_FOUND");
    }

    @Test
    void locationCreationReplaysOriginalAfterEditAndArchiveAndExpiresWithoutRecreation() throws Exception {
        String email=businessAccount("RS","BUYER","OWNER"),token=nativeToken(email);
        var body=locationBody("RS",true); body.put("name","  Main  ");
        String payload=JSON.writeValueAsString(body),path="/organization/locations/"+body.get("id");
        var created=send("POST","/organization/locations",payload,"Authorization","Bearer "+token);
        assertThat(created.statusCode()).isEqualTo(201);
        assertThat(created.headers().firstValue("Location")).contains("/api/v1"+path);
        body.put("name","Main");
        var replay=send("POST","/organization/locations",JSON.writeValueAsString(body),"Authorization","Bearer "+token);
        assertThat(replay.statusCode()).isEqualTo(200); assertThat(json(replay)).isEqualTo(json(created));
        var values=locationUpdate(json(created)); values.put("name","Later name");
        var changed=send("PUT",path,JSON.writeValueAsString(values),"Authorization","Bearer "+token);
        assertThat(changed.statusCode()).isEqualTo(200);
        assertThat(send("POST",path+"/archive",revisionBody(json(changed)),"Authorization","Bearer "+token).statusCode()).isEqualTo(200);
        replay=send("POST","/organization/locations",payload,"Authorization","Bearer "+token);
        assertThat(json(replay)).isEqualTo(json(created));
        body.put("name","Other intent");
        assertProblem(send("POST","/organization/locations",JSON.writeValueAsString(body),"Authorization","Bearer "+token),409,"IDEMPOTENCY_MISMATCH");
        assertThat(locationAudits((UUID)body.get("id"))).isEqualTo(3);
        CLOCK.advance(7*86400); token=nativeToken(email);
        var expired=send("POST","/organization/locations",payload,"Authorization","Bearer "+token);
        assertProblem(expired,409,"REPLAY_EXPIRED"); assertThat(json(expired).path("resourceId").asString()).isEqualTo(body.get("id").toString());
        var tx=new TransactionTemplate(app.getBean(org.springframework.transaction.PlatformTransactionManager.class));
        tx.executeWithoutResult(status -> app.getBean(com.narudzbine.organizations.api.Locations.class).compactExpiredReceipts());
        assertThat(owner.queryForObject("SELECT original_snapshot IS NULL FROM location_creation WHERE location_id=?",Boolean.class,body.get("id"))).isTrue();
        assertProblem(send("POST","/organization/locations",payload,"Authorization","Bearer "+token),409,"REPLAY_EXPIRED");
        assertThat(owner.queryForObject("SELECT count(*) FROM organization_location WHERE id=?",Integer.class,body.get("id"))).isEqualTo(1);
    }

    @Test
    void locationNoOpsStaleWritesArchiveAndRestoreClearHomeWithoutReassignment() throws Exception {
        String token=nativeToken(businessAccount("BA","BUYER","OWNER"));
        var me=json(send("GET","/me",null,"Authorization","Bearer "+token)); UUID account=UUID.fromString(me.path("id").asString());
        var body=locationBody("BA",true); String path="/organization/locations/"+body.get("id");
        var created=json(send("POST","/organization/locations",JSON.writeValueAsString(body),"Authorization","Bearer "+token));
        var unchanged=send("PUT",path,JSON.writeValueAsString(locationUpdate(created)),"Authorization","Bearer "+token);
        assertThat(json(unchanged)).isEqualTo(created); assertThat(locationAudits((UUID)body.get("id"))).isEqualTo(1);
        setup.executeWithoutResult(status -> owner.update("UPDATE business_account SET home_location_id=? WHERE id=?",body.get("id"),account));
        assertThat(json(send("GET","/me",null,"Authorization","Bearer "+token)).path("homeLocationId").asString()).isEqualTo(body.get("id").toString());
        var archived=send("POST",path+"/archive",revisionBody(created),"Authorization","Bearer "+token);
        assertThat(json(archived).path("state").asString()).isEqualTo("ARCHIVED");
        var after=json(send("GET","/me",null,"Authorization","Bearer "+token));
        assertThat(after.path("homeLocationId").isNull()).isTrue(); assertThat(after.path("revision")).isNotEqualTo(me.path("revision"));
        var stale=send("POST",path+"/archive",revisionBody(created),"Authorization","Bearer "+token);
        assertProblem(stale,409,"REVISION_CONFLICT"); assertThat(json(stale).path("currentRevision")).isEqualTo(json(archived).path("revision"));
        assertThat(json(send("POST",path+"/archive",revisionBody(json(archived)),"Authorization","Bearer "+token))).isEqualTo(json(archived));
        var restored=send("POST",path+"/restore",revisionBody(json(archived)),"Authorization","Bearer "+token);
        assertThat(json(restored).path("id")).isEqualTo(created.path("id")); assertThat(json(restored).path("state").asString()).isEqualTo("ACTIVE");
        assertThat(json(send("GET","/me",null,"Authorization","Bearer "+token)).path("homeLocationId").isNull()).isTrue();
        assertThat(locationAudits((UUID)body.get("id"))).isEqualTo(3);
        assertThat(send("DELETE",path,null,"Authorization","Bearer "+token).statusCode()).isEqualTo(404);
    }

