    @Test
    void locationPaginationUsesStableIdTieBreaksStrictFiltersAndOptionalTotal() throws Exception {
        String token=nativeToken(businessAccount("RS","VENDOR","OWNER")); var ids=new java.util.ArrayList<String>();
        for(int n=0;n<4;n++) {
            var body=locationBody("RS",false); body.put("name","Warehouse "+n); ids.add(body.get("id").toString());
            assertThat(send("POST","/organization/locations",JSON.writeValueAsString(body),"Authorization","Bearer "+token).statusCode()).isEqualTo(201);
        }
        ids.sort(String::compareTo);
        var first=json(send("GET","/organization/locations?size=2&includeTotal=true",null,"Authorization","Bearer "+token));
        assertThat(first.path("total").asInt()).isEqualTo(4); assertThat(first.path("items").get(0).path("id").asString()).isEqualTo(ids.get(0));
        var second=json(send("GET","/organization/locations?size=2&page=1",null,"Authorization","Bearer "+token));
        assertThat(second.path("total").isNull()).isTrue(); assertThat(second.path("items").get(0).path("id").asString()).isEqualTo(ids.get(2));
        assertThat(json(send("GET","/organization/locations?state=ARCHIVED&includeTotal=true",null,"Authorization","Bearer "+token)).path("total").asInt()).isZero();
        for(String query:java.util.List.of("size=0","size=101","page=10001","page=-1","page=1&page=2","includeTotal=yes","state=UNKNOWN","sort=name","foreignScope=RS")) {
            assertProblem(send("GET","/organization/locations?"+query,null,"Authorization","Bearer "+token),422,"VALIDATION_FAILED");
        }
    }

