    @Test
    void profileAuditFailureRollsBackNameDefaultRevisionAndActivity() throws Exception {
        String token=nativeToken(businessAccount("BA","BUYER","OWNER"));var body=locationBody("BA",true);
        assertThat(send("POST","/organization/locations",JSON.writeValueAsString(body),"Authorization","Bearer "+token).statusCode()).isEqualTo(201);
        var me=json(send("GET","/me",null,"Authorization","Bearer "+token));UUID id=UUID.fromString(me.path("id").asString());
        var activity=owner.queryForObject("SELECT last_qualified_activity_at FROM application_session WHERE account_id=?",java.sql.Timestamp.class,id);CLOCK.advance(5);
        owner.execute("REVOKE INSERT ON audit_event FROM http_runtime");
        try {
            assertProblem(send("PUT","/me",profileBody(me,"Changed",(UUID)body.get("id")),"Authorization","Bearer "+token),503,"SERVICE_UNAVAILABLE");
            assertThat(json(send("GET","/me",null,"Authorization","Bearer "+token))).isEqualTo(me);
            assertThat(owner.queryForObject("SELECT last_qualified_activity_at FROM application_session WHERE account_id=?",java.sql.Timestamp.class,id)).isEqualTo(activity);
            assertThat(profileAudits(id)).isZero();
        } finally { owner.execute("GRANT SELECT,INSERT ON audit_event TO http_runtime"); }
        var saved=send("PUT","/me",profileBody(me,"Changed",(UUID)body.get("id")),"Authorization","Bearer "+token);
        assertThat(saved.statusCode()).isEqualTo(200);
        assertThat(owner.queryForObject("SELECT last_qualified_activity_at FROM application_session WHERE account_id=?",java.sql.Timestamp.class,id)).isAfter(activity);
    }

    @Test
    void profileStrictInputAndBrowserProtectionPreserveSessionCredentials() throws Exception {
        var boot=send("GET","/bootstrap",null,"Origin","https://app.example");
        var login=send("POST","/login",loginBody(account(),"BROWSER",json(boot).path("nonce").asString()),"Origin","https://app.example","Cookie",cookie(boot,"__Host-narudzbine_preauth"));
        String session=cookie(login,"__Host-narudzbine_session"),csrf=json(login).path("csrfToken").asString();var me=json(login).path("account");
        String body=profileBody(me,"Changed",null);
        assertProblem(send("PUT","/me",body,"Origin","https://app.example","Cookie",session),403,"CSRF_REJECTED");
        assertProblem(send("PUT","/me",body,"Cookie",session,"X-CSRF-Token",csrf),403,"CSRF_REJECTED");
        assertThat(send("OPTIONS","/me",null,"Origin","https://app.example","Access-Control-Request-Method","PUT","Access-Control-Request-Headers","Content-Type,X-CSRF-Token").statusCode()).isEqualTo(200);
        for(String invalid:java.util.List.of("{}",profileBody(me," ",null),profileBody(me,"x".repeat(101),null),profileBody(me,"line\nname",null),
                JSON.writeValueAsString(Map.of("expectedRevision",me.path("revision").asString(),"displayName","Valid")),body.replace("null","123"),body.replace("null","null,\"email\":\"not-allowed@example.com\""))) {
            assertProblem(send("PUT","/me",invalid,"Origin","https://app.example","Cookie",session,"X-CSRF-Token",csrf),422,"VALIDATION_FAILED");
        }
        var missing=send("PUT","/me","{}","Origin","https://app.example","Cookie",session,"X-CSRF-Token",csrf);
        assertThat(json(missing).path("errors").size()).isEqualTo(3);
        var result=send("PUT","/me",body,"Origin","https://app.example","Cookie",session,"X-CSRF-Token",csrf);
        assertThat(result.statusCode()).isEqualTo(200);assertThat(result.headers().allValues("Set-Cookie")).isEmpty();
        assertThat(client.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+management+"/api/v1/me")).header("Cookie",session).PUT(HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString()).statusCode()).isEqualTo(404);
    }

    private static String profileBody(JsonNode me,String displayName,UUID home) {
        var values=new java.util.HashMap<String,Object>();values.put("expectedRevision",me.path("revision").asString());values.put("displayName",displayName);values.put("homeLocationId",home);
        return JSON.writeValueAsString(values);
    }
    private static int profileAudits(UUID id) { return owner.queryForObject("SELECT count(*) FROM audit_event WHERE resource_id=? AND action='ACCOUNT_PROFILE_UPDATED'",Integer.class,id); }

    @Test
    void contactsCompleteLifecycleAndRoleCountryTypeMatrix() throws Exception {
        for (String country:java.util.List.of("RS","BA")) {
            for (String type:java.util.List.of("BUYER","VENDOR")) {
                for (String role:java.util.List.of("OWNER","ADMIN","STAFF")) {
                    String token=nativeToken(businessAccount(country,type,role)); var body=contactBody();
                    var created=send("POST","/organization/contacts",JSON.writeValueAsString(body),"Authorization","Bearer "+token);
                    if (role.equals("STAFF")) {
                        assertProblem(created,403,"FORBIDDEN");
                        assertThat(send("GET","/organization/contacts",null,"Authorization","Bearer "+token).statusCode()).isEqualTo(200);
                        continue;
                    }
                    assertThat(created.statusCode()).isEqualTo(201); var original=json(created); String path="/organization/contacts/"+body.get("id");
                    assertThat(created.headers().firstValue("Location")).contains("/api/v1"+path);
                    assertThat(original.propertyNames()).containsExactlyInAnyOrder("id","revision","label","contact","state");
                    assertThat(original.path("contact").path("email").isNull()).isTrue();
                    assertThat(json(send("GET",path,null,"Authorization","Bearer "+token))).isEqualTo(original);
                    var update=contactUpdate(original); update.put("label","Sales");
                    var changed=send("PUT",path,JSON.writeValueAsString(update),"Authorization","Bearer "+token);
                    assertThat(changed.statusCode()).isEqualTo(200); var current=json(changed);
                    assertThat(current.path("revision")).isNotEqualTo(original.path("revision"));
                    var archived=send("POST",path+"/archive",revisionBody(current),"Authorization","Bearer "+token);
                    assertThat(archived.statusCode()).isEqualTo(200); assertThat(json(archived).path("state").asString()).isEqualTo("ARCHIVED");
                    assertThat(json(send("POST",path+"/archive",revisionBody(json(archived)),"Authorization","Bearer "+token))).isEqualTo(json(archived));
                    var restored=send("POST",path+"/restore",revisionBody(json(archived)),"Authorization","Bearer "+token);
                    assertThat(restored.statusCode()).isEqualTo(200); assertThat(json(restored).path("state").asString()).isEqualTo("ACTIVE");
                    assertThat(contactAudits((UUID)body.get("id"))).isEqualTo(4);
                    assertThat(owner.queryForObject("SELECT count(*) FROM organization_location WHERE organization_id=(SELECT organization_id FROM business_contact WHERE id=?)",Integer.class,body.get("id"))).isZero();
                }
            }
        }
    }

