    @Test
    void contactReplayExpiryCompactionAndTombstones() throws Exception {
        String token=nativeToken(businessAccount("BA","BUYER","OWNER")); var body=contactBody();String payload=JSON.writeValueAsString(body);
        assertThat(send("POST","/organization/contacts",payload,"Authorization","Bearer "+token).statusCode()).isEqualTo(201);
        CLOCK.advance(7*86400);
        token=nativeToken(owner.queryForObject("SELECT email FROM account_identity WHERE id=(SELECT creator_id FROM contact_creation WHERE contact_id=?)",String.class,body.get("id")));
        var expired=send("POST","/organization/contacts",payload,"Authorization","Bearer "+token);
        assertProblem(expired,409,"REPLAY_EXPIRED");assertThat(json(expired).path("resourceId").asString()).isEqualTo(body.get("id").toString());
        new TransactionTemplate(app.getBean(org.springframework.transaction.PlatformTransactionManager.class)).executeWithoutResult(status -> app.getBean(com.narudzbine.organizations.api.BusinessContacts.class).compactExpiredReceipts());
        assertThat(owner.queryForObject("SELECT original_snapshot IS NULL FROM contact_creation WHERE contact_id=?",Boolean.class,body.get("id"))).isTrue();
        assertProblem(send("POST","/organization/contacts",payload,"Authorization","Bearer "+token),409,"REPLAY_EXPIRED");
        for(String sql:java.util.List.of("DELETE FROM contact_creation WHERE contact_id=?","UPDATE contact_creation SET payload_hash=decode(repeat('11',32),'hex') WHERE contact_id=?","DELETE FROM business_contact WHERE id=?","UPDATE business_contact SET organization_id=gen_random_uuid() WHERE id=?")) {
            assertThatThrownBy(() -> owner.update(sql,body.get("id"))).isInstanceOf(org.springframework.dao.DataAccessException.class);
        }
    }

