    @Test
    void contactCommandWaitingOnOrganizationGuardRechecksReducedRole() throws Exception {
        String email=businessAccount("RS","VENDOR","ADMIN"),token=nativeToken(email);var body=contactBody();
        UUID actor=owner.queryForObject("SELECT id FROM account_identity WHERE email=?",UUID.class,email);
        UUID org=owner.queryForObject("SELECT organization_id FROM business_account WHERE id=?",UUID.class,actor);
        java.util.concurrent.CompletableFuture<HttpResponse<String>> pending;
        try(var connection=java.sql.DriverManager.getConnection(DATABASE.getJdbcUrl(),DATABASE.getUsername(),DATABASE.getPassword())) {
            connection.setAutoCommit(false);
            try(var guard=connection.prepareStatement("SELECT id FROM organization WHERE id=? FOR UPDATE")) { guard.setObject(1,org);guard.executeQuery().close(); }
            pending=client.sendAsync(request("POST","/organization/contacts",JSON.writeValueAsString(body),"Authorization","Bearer "+token),HttpResponse.BodyHandlers.ofString());
            long deadline=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(5);boolean waiting=false;
            while(System.nanoTime()<deadline) {
                waiting=Boolean.TRUE.equals(owner.queryForObject("SELECT EXISTS(SELECT 1 FROM pg_stat_activity WHERE usename='http_runtime' AND wait_event_type='Lock')",Boolean.class));
                if(waiting) { break; } java.util.concurrent.locks.LockSupport.parkNanos(java.util.concurrent.TimeUnit.MILLISECONDS.toNanos(10));
            }
            assertThat(waiting).as("HTTP command must actually wait on held organization guard").isTrue();
            try(var change=connection.prepareStatement("UPDATE business_account SET role='STAFF' WHERE id=?")) { change.setObject(1,actor);change.executeUpdate(); }
            connection.commit();
        }
        assertProblem(pending.get(),403,"FORBIDDEN");
        assertThat(owner.queryForObject("SELECT count(*) FROM business_contact WHERE id=?",Integer.class,body.get("id"))).isZero();
        assertThat(contactAudits((UUID)body.get("id"))).isZero();
    }

