    @Test
    void memberRoleAndLifecycleMatrixAcrossCountriesAndOrganizationTypes() throws Exception {
        for(String country:java.util.List.of("RS","BA")) {
            for(String type:java.util.List.of("BUYER","VENDOR")) {
                String ownerEmail=businessAccount(country,type,"OWNER"),ownerToken=nativeToken(ownerEmail);UUID org=organizationFor(ownerEmail);
                String adminEmail=addMember(org,"ADMIN"),adminToken=nativeToken(adminEmail);
                String staffEmail=addMember(org,"STAFF"),staffToken=nativeToken(staffEmail);UUID staff=accountFor(staffEmail),admin=accountFor(adminEmail);
                var member=listedMember(ownerToken,staff);String path=memberPath(staff);
                assertThat(member.path("organizationId").asString()).isEqualTo(org.toString());
                assertThat(listedMember(staffToken,admin).path("email").asString()).isEqualTo(adminEmail);
                assertProblem(send("PUT",path+"/role",roleBody(member,"ADMIN"),"Authorization","Bearer "+adminToken),403,"FORBIDDEN");
                assertProblem(send("PUT",path+"/role",roleBody(member,"ADMIN"),"Authorization","Bearer "+staffToken),403,"FORBIDDEN");
                var promoted=send("PUT",path+"/role",roleBody(member,"ADMIN"),"Authorization","Bearer "+ownerToken);
                assertThat(promoted.statusCode()).isEqualTo(200);assertThat(json(promoted).path("role").asString()).isEqualTo("ADMIN");
                assertThat(promoted.body()).doesNotContain("bearerToken","csrfToken","credentialGeneration","securityEpoch");
                assertProblem(send("GET","/me",null,"Authorization","Bearer "+staffToken),401,"INVALID_SESSION");
                staffToken=nativeToken(staffEmail);
                var demoted=send("PUT",path+"/role",roleBody(json(promoted),"STAFF"),"Authorization","Bearer "+ownerToken);
                assertThat(demoted.statusCode()).isEqualTo(200);assertThat(json(demoted).path("role").asString()).isEqualTo("STAFF");
                assertProblem(send("GET","/me",null,"Authorization","Bearer "+staffToken),401,"INVALID_SESSION");
                var deactivated=send("POST",path+"/deactivation",revisionBody(json(demoted)),"Authorization","Bearer "+adminToken);
                assertThat(deactivated.statusCode()).isEqualTo(200);assertThat(json(deactivated).path("state").asString()).isEqualTo("DEACTIVATED");
                var reactivated=send("POST",path+"/reactivation",revisionBody(json(deactivated)),"Authorization","Bearer "+adminToken);
                assertThat(reactivated.statusCode()).isEqualTo(200);assertThat(json(reactivated).path("role").asString()).isEqualTo("STAFF");
                assertThat(json(reactivated).path("id").asString()).isEqualTo(staff.toString());assertThat(json(reactivated).path("organizationId").asString()).isEqualTo(org.toString());
                assertThat(memberAudits(staff)).isEqualTo(4);
                var adminMember=listedMember(ownerToken,admin);
                assertProblem(send("POST",memberPath(admin)+"/deactivation",revisionBody(adminMember),"Authorization","Bearer "+adminToken),403,"FORBIDDEN");
                var inactiveAdmin=send("POST",memberPath(admin)+"/deactivation",revisionBody(adminMember),"Authorization","Bearer "+ownerToken);assertThat(inactiveAdmin.statusCode()).isEqualTo(200);
                String secondAdminToken=nativeToken(addMember(org,"ADMIN"));
                assertProblem(send("POST",memberPath(admin)+"/reactivation",revisionBody(json(inactiveAdmin)),"Authorization","Bearer "+secondAdminToken),403,"FORBIDDEN");
                assertProblem(send("PUT",memberPath(admin)+"/role",roleBody(json(inactiveAdmin),"STAFF"),"Authorization","Bearer "+ownerToken),409,"INVALID_STATE");
                var returned=send("POST",memberPath(admin)+"/reactivation",revisionBody(json(inactiveAdmin)),"Authorization","Bearer "+ownerToken);
                assertThat(returned.statusCode()).isEqualTo(200);assertThat(json(returned).path("role").asString()).isEqualTo("STAFF");
                assertThat(owner.queryForObject("SELECT count(*) FROM business_account WHERE organization_id=? AND role='OWNER'",Integer.class,org)).isEqualTo(1);
            }
        }
    }

