    @Test void reportingSqlUsesLocalSubmissionDateAcrossUtcMidnight()throws Exception{
        Instant before=CLOCK.instant();var today=before.atZone(ZoneOffset.UTC).toLocalDate();Instant target=today.plusDays(1).atTime(23,30).toInstant(ZoneOffset.UTC);CLOCK.advance(java.time.Duration.between(before,target).getSeconds());
        try{var f=reviewFixture("BA");reportDelivered(f);String utc=target.atZone(ZoneOffset.UTC).toLocalDate().toString(),local=target.atZone(ZoneId.of("Europe/Sarajevo")).toLocalDate().toString();assertThat(utc).isNotEqualTo(local);assertThat(reportSaved(f.offer().stock().token(),"summary","from="+utc+"&to="+utc+"&grouping=DAY").path("orderCount").asLong()).isZero();assertThat(reportSaved(f.offer().stock().token(),"summary","from="+local+"&to="+local+"&grouping=DAY").path("orderCount").asLong()).isEqualTo(1);}finally{CLOCK.advance(java.time.Duration.between(CLOCK.instant(),before).getSeconds());}
    }


    private tools.jackson.databind.node.ObjectNode exportBody(String kind){var b=JSON.createObjectNode();b.put("id",taxonomyId().toString());b.put("kind",kind);String date=CLOCK.instant().atZone(ZoneId.of("Europe/Belgrade")).toLocalDate().toString();b.put("from",date);b.put("to",date);return b;}
    private HttpResponse<String> exportCreate(String token,JsonNode body)throws Exception{return send("POST","/exports",JSON.writeValueAsString(body),"Authorization","Bearer "+token);}
    private JsonNode exportSaved(String token,JsonNode body)throws Exception{var r=exportCreate(token,body);assertThat(r.statusCode()).as(r.body()).isEqualTo(202);return json(r);}
    private JsonNode exportGet(String token,String id)throws Exception{var r=send("GET","/exports/"+id,null,"Authorization","Bearer "+token);assertThat(r.statusCode()).as(r.body()).isEqualTo(200);return json(r);}
    private int exportTick(){return app.getBean(com.narudzbine.reporting.application.ExportEngine.class).tick();}
    private void exportDrain(){for(int i=0;i<100;i++)if(exportTick()==0)return;throw new AssertionError("Export fixtures did not drain");}
    private JsonNode exportReady(String token,JsonNode job)throws Exception{for(int i=0;i<100;i++){var r=exportGet(token,job.path("id").asString());if(!r.path("state").asString().equals("QUEUED")){assertThat(r.path("state").asString()).isEqualTo("READY");return r;}exportTick();}throw new AssertionError("Export did not finish");}
    private HttpResponse<String> exportContent(String token,JsonNode job)throws Exception{return send("GET","/exports/"+job.path("id").asString()+"/content",null,"Authorization","Bearer "+token);}
    @Test void exportingEmptyHeaderAndPrivateDownloadAreAudited()throws Exception{
        String email=businessAccount("RS","BUYER","STAFF"),token=nativeToken(email);var job=exportSaved(token,exportBody("ORDERS"));assertThat(job.path("state").asString()).isEqualTo("QUEUED");assertThat(job.path("expiresAt").isNull()).isTrue();var ready=exportReady(token,job);var file=exportContent(token,job);assertThat(file.statusCode()).as(file.body()).isEqualTo(200);assertThat(file.body()).startsWith("\"orderId\",\"number\"").endsWith("\r\n");assertThat(file.body().split("\r\n")).hasSize(1);assertThat(file.headers().firstValue("Cache-Control")).contains("private, no-store");assertThat(file.headers().firstValue("Content-Type").orElseThrow()).contains("text/csv").contains("charset=UTF-8");assertThat(file.headers().firstValue("Content-Disposition").orElseThrow()).contains("export-"+job.path("id").asString()+".csv");assertThat(file.headers().firstValue("X-Content-Type-Options")).contains("nosniff");assertThat(ready.path("revision")).isNotEqualTo(job.path("revision"));
        UUID id=UUID.fromString(job.path("id").asString());assertThat(owner.queryForObject("SELECT count(*) FROM audit_event WHERE resource_id=? AND action='EXPORT_CREATED'",Integer.class,id)).isEqualTo(1);assertThat(owner.queryForObject("SELECT count(*) FROM audit_event WHERE resource_id=? AND action='EXPORT_DOWNLOADED'",Integer.class,id)).isEqualTo(1);assertThat((byte[])owner.queryForMap("SELECT artifact FROM commercial_export WHERE id=?",id).get("artifact")).isNotEqualTo(file.body().getBytes(java.nio.charset.StandardCharsets.UTF_8));
    }
