    @Test void exportingDrainRejectsNewWorkButRetainsOriginalReplayAndReads()throws Exception{
        String email=businessAccount("RS","BUYER","STAFF"),token=nativeToken(email);var body=exportBody("ORDERS");var original=exportSaved(token,body);exportReady(token,original);
        var store=new com.narudzbine.reporting.application.JdbcExports(app.getBean(org.springframework.jdbc.core.JdbcTemplate.class),new com.narudzbine.reporting.application.ExportSettings(true,key(),false),app.getBeanProvider(com.narudzbine.shared.api.ResourceRevisions.class),app.getBean(com.narudzbine.audit.api.ExportAudit.class),CLOCK);
        var tx=new org.springframework.transaction.support.TransactionTemplate(app.getBean(org.springframework.transaction.PlatformTransactionManager.class));tx.executeWithoutResult(status->{var actor=app.getBean(com.narudzbine.identity.application.SessionService.class).authenticateForOrganizationWrite(token,com.narudzbine.identity.api.SessionTransport.NATIVE);var scope=new com.narudzbine.reporting.api.Exports.Scope(actor.accountId(),organizationFor(email),"RS",false);var command=new com.narudzbine.reporting.api.Exports.Command(UUID.fromString(body.path("id").asString()),"ORDERS",java.time.LocalDate.parse(body.path("from").asString()),java.time.LocalDate.parse(body.path("to").asString()));assertThat(store.create(scope,command).state()).isEqualTo("QUEUED");assertThat(store.read(scope,command.id()).state()).isEqualTo("READY");assertThat(store.download(scope,command.id()).failureCode()).isEqualTo("SERVICE_UNAVAILABLE");assertThatThrownBy(()->store.create(scope,new com.narudzbine.reporting.api.Exports.Command(taxonomyId(),command.kind(),command.from(),command.to()))).isInstanceOf(com.narudzbine.reporting.api.ExportFailure.class).extracting(e->((com.narudzbine.reporting.api.ExportFailure)e).code()).isEqualTo("SERVICE_UNAVAILABLE");});
        assertThat(exportContent(token,original).statusCode()).isEqualTo(200);
    }


