    @Test void exportingStorageBudgetRejectsPublicationWithoutPartialContent()throws Exception{
        exportDrain();String token=nativeToken(businessAccount("RS","BUYER","STAFF"));var ids=new java.util.ArrayList<UUID>();byte[] occupied=new byte[16*1024*1024+28];
        try{for(int i=0;i<8;i++){var job=exportSaved(token,exportBody("ORDERS"));UUID id=UUID.fromString(job.path("id").asString());ids.add(id);owner.update("UPDATE commercial_export SET state='READY',revision=revision+1,completed_at=?,expires_at=?,artifact=?,digest=?,byte_count=16777216,row_count=0 WHERE id=?",java.sql.Timestamp.from(CLOCK.instant()),java.sql.Timestamp.from(CLOCK.instant().plusSeconds(86400)),occupied,new byte[32],id);}var denied=exportSaved(token,exportBody("ORDERS"));assertThat(exportTick()).isEqualTo(1);var state=exportGet(token,denied.path("id").asString());assertThat(state.path("state").asString()).isEqualTo("FAILED");assertThat(state.path("failureCode").asString()).isEqualTo("EXPORT_CAPACITY_REACHED");assertProblem(exportContent(token,denied),409,"INVALID_STATE");}
        finally{for(UUID id:ids)owner.update("UPDATE commercial_export SET state='EXPIRED',revision=revision+1,artifact=NULL,digest=NULL WHERE id=?",id);}
    }


    private UUID auditSeed(String email,String action,String resource,String reason,String fields){return auditSeedCountry(email,action,resource,reason,fields,null);}
    private UUID auditSeedCountry(String email,String action,String resource,String reason,String fields,String country){UUID id=taxonomyId();owner.update("INSERT INTO audit_event(id,actor_type,actor_id,organization_id,country,action,resource_type,resource_id,outcome,request_id,occurred_at,changed_fields,reason) SELECT ?,'BUSINESS',a.id,b.organization_id,coalesce(?::varchar,o.country),?,?,?,'SUCCESS',?,?,?::text[],? FROM account_identity a JOIN business_account b ON b.id=a.id JOIN organization o ON o.id=b.organization_id WHERE a.id=?",id,country,action,resource,resource.equals("ORGANIZATION")?organizationFor(email):taxonomyId(),taxonomyId(),java.sql.Timestamp.from(CLOCK.instant()),fields,reason,accountFor(email));return id;}
    private HttpResponse<String> auditRead(String token,boolean admin,String query)throws Exception{return send("GET",(admin?"/admin/audit":"/organization/audit")+(query.isEmpty()?"":"?"+query),null,"Authorization","Bearer "+token);}
    private JsonNode auditSaved(String token,boolean admin,String query)throws Exception{var r=auditRead(token,admin,query);assertThat(r.statusCode()).as(r.body()).isEqualTo(200);return json(r);}
