    private HttpResponse<String> directoryRead(String token,String path)throws Exception{return send("GET","/admin"+path,null,"Authorization","Bearer "+token);}
    private JsonNode directorySaved(String token,String path)throws Exception{var r=directoryRead(token,path);assertThat(r.statusCode()).as(r.body()).isEqualTo(200);return json(r);}
    private JsonNode directoryOrganization(String token,UUID org)throws Exception{return directorySaved(token,"/organizations/"+org);}
    private tools.jackson.databind.node.ObjectNode directoryCorrection(JsonNode org){var b=JSON.createObjectNode();for(String f:java.util.List.of("displayName","legalName","registrationIdentifier","taxIdentifier","registeredAddress"))b.set(f,org.path(f));b.put("expectedRevision",org.path("revision").asString());b.put("reason","Synthetic proven typo review");return b;}
    private HttpResponse<String> directoryCorrect(String token,UUID org,JsonNode body)throws Exception{return send("PUT","/admin/organizations/"+org,body.toString(),"Authorization","Bearer "+token);}
    private JsonNode directoryMember(String token,UUID org,UUID account)throws Exception{var page=directorySaved(token,"/organizations/"+org+"/members?size=100");for(var m:page.path("items"))if(m.path("id").asString().equals(account.toString()))return m;throw new AssertionError("Synthetic administrative member not found");}
    private HttpResponse<String> directoryStaff(String token,UUID org,JsonNode member,boolean active)throws Exception{return send("POST","/admin/organizations/"+org+"/members/"+member.path("id").asString()+(active?"/reactivation":"/deactivation"),JSON.writeValueAsString(Map.of("expectedRevision",member.path("revision").asString(),"reason","Synthetic administrative staff review")),"Authorization","Bearer "+token);}

