    private int stateAudits(UUID org){return owner.queryForObject("SELECT count(*) FROM audit_event WHERE resource_id=? AND action IN('ADMIN_ORGANIZATION_SUSPENDED','ADMIN_ORGANIZATION_REACTIVATED')",Integer.class,org);}
    private String stateBody(JsonNode old)throws Exception{return JSON.writeValueAsString(Map.of("expectedRevision",old.path("revision").asString(),"reason","Synthetic private state review"));}
    private HttpResponse<String> organizationState(String admin,UUID org,JsonNode old,boolean active)throws Exception{return send("POST","/admin/organizations/"+org+(active?"/reactivate":"/suspend"),stateBody(old),"Authorization","Bearer "+admin);}

