    @Test @org.junit.jupiter.api.Timeout(90)
    void reportingRechecksRevokedCredentialsAfterRealSnapshotWithoutActivity() throws Exception {
        for(String country:List.of("RS","BA")){
            String email=businessAccount(country,"BUYER","STAFF"),token=nativeToken(email);
            UUID actor=accountFor(email),organization=organizationFor(email);
            var activity=owner.queryForObject("SELECT last_qualified_activity_at FROM application_session WHERE token_hash=?",Timestamp.class,digest(token));
            CLOCK.advance(1);
            var pause=new ReportSnapshotPause(organization);REPORT_SNAPSHOT_PAUSE.set(pause);
            var response=client.sendAsync(request("GET","/reports/summary?"+reportDates()+"&grouping=DAY",null,"Authorization","Bearer "+token),HttpResponse.BodyHandlers.ofString());
            try{
                assertThat(pause.computed.await(5,java.util.concurrent.TimeUnit.SECONDS)).as("Real report SQL completed").isTrue();
                assertThat(pause.readOnly).isTrue();assertThat(pause.repeatableRead).isTrue();
                try(var revocation=fixtureSource.getConnection()){
                    revocation.setAutoCommit(false);
                    try(var statement=revocation.prepareStatement("SELECT id FROM organization WHERE id=? FOR UPDATE NOWAIT")){statement.setObject(1,organization);statement.executeQuery().close();}
                    try(var statement=revocation.prepareStatement("UPDATE account_identity SET security_epoch=security_epoch+1 WHERE id=?")){statement.setObject(1,actor);assertThat(statement.executeUpdate()).isEqualTo(1);}
                    revocation.commit();
                }
                pause.release.countDown();
                assertProblem(response.get(10,java.util.concurrent.TimeUnit.SECONDS),401,"INVALID_SESSION");
                assertThat(owner.queryForObject("SELECT last_qualified_activity_at FROM application_session WHERE token_hash=?",Timestamp.class,digest(token))).isEqualTo(activity);
            }finally{pause.release.countDown();REPORT_SNAPSHOT_PAUSE.set(null);}
            assertThat(report(nativeToken(email),"summary",reportDates()+"&grouping=DAY").statusCode()).as("Report slot released after denied publication").isEqualTo(200);
        }
    }

