    @Test void reportingSnapshotRemainsStableAcrossConcurrentDelivery()throws Exception{
        var f=reviewFixture("RS");var dispatched=progressed(f.offer().stock().token(),requestAccepted(f),false);var template=new org.springframework.transaction.support.TransactionTemplate(app.getBean(org.springframework.transaction.PlatformTransactionManager.class));template.setReadOnly(true);template.setIsolationLevel(org.springframework.transaction.TransactionDefinition.ISOLATION_REPEATABLE_READ);
        template.executeWithoutResult(status->{var jdbc=app.getBean(org.springframework.jdbc.core.JdbcTemplate.class);assertThat(jdbc.queryForObject("SHOW transaction_read_only",String.class)).isEqualTo("on");assertThat(jdbc.queryForObject("SHOW transaction_isolation",String.class)).isEqualTo("repeatable read");var api=app.getBean(com.narudzbine.reporting.api.BusinessReports.class);var scope=new com.narudzbine.reporting.api.BusinessReports.Scope(f.offer().stock().vendor(),"RS",true);var date=CLOCK.instant().atZone(ZoneId.of("Europe/Belgrade")).toLocalDate();var range=new com.narudzbine.reporting.api.BusinessReports.Range(date,date,ZoneId.of("Europe/Belgrade"),date.atStartOfDay(ZoneId.of("Europe/Belgrade")).toInstant(),date.plusDays(1).atStartOfDay(ZoneId.of("Europe/Belgrade")).toInstant(),CLOCK.instant());assertThat(api.summary(scope,range,"DAY").orderCount()).isZero();try{progressed(f.offer().stock().token(),dispatched,true);}catch(Exception e){throw new RuntimeException(e);}assertThat(api.products(scope,range,0,25,true).total()).isZero();assertThat(api.summary(scope,range,"DAY").orderCount()).isZero();});
        assertThat(reportSaved(f.offer().stock().token(),"summary",reportDates()+"&grouping=DAY").path("orderCount").asLong()).isEqualTo(1);
    }

    private HttpResponse<String> send(String method,String path,String body,String... headers)throws Exception {
        long started=System.nanoTime();String phase=loadPhase;var outgoing=request(method,path,body,headers);
        boolean submission=phase!=null&&method.equals("POST")&&path.equals("/orders");
        if(phase!=null)loadIssued.computeIfAbsent(phase,k->new java.util.concurrent.atomic.LongAdder()).increment();
        if(submission){int active=loadSubmissionActive.incrementAndGet();loadSubmissionPeak.accumulateAndGet(active,Math::max);}
        try{
            var response=client.send(outgoing,HttpResponse.BodyHandlers.ofString());
            if(phase!=null){loadStatuses.computeIfAbsent(response.statusCode(),k->new java.util.concurrent.atomic.LongAdder()).increment();if(response.statusCode()>=400){String code="UNCLASSIFIED",requestId="UNKNOWN";try{var error=JSON.readTree(response.body());String candidate=error.path("code").asString(),id=error.path("requestId").asString();if(candidate.matches("[A-Z][A-Z0-9_]{0,79}"))code=candidate;if(id.matches("[0-9a-f-]{36}"))requestId=id;}catch(RuntimeException ignored){}System.out.println("load-http-error method="+method+" route="+path.replaceAll("[?].*","")+" status="+response.statusCode()+" code="+code+" requestId="+requestId);}}
            return response;
        }catch(java.io.IOException|InterruptedException failure){if(phase!=null)loadStatuses.computeIfAbsent(0,k->new java.util.concurrent.atomic.LongAdder()).increment();throw failure;}
        finally{
            if(submission)loadSubmissionActive.decrementAndGet();
            if(phase!=null){String kind=path.startsWith("/reports/")?"report":method.equals("GET")?"read":path.equals("/orders")?"submission":"write";long elapsed=System.nanoTime()-started;loadTimings.computeIfAbsent(phase+":"+kind,k->new java.util.concurrent.ConcurrentLinkedQueue<>()).add(elapsed);String route=method+" "+path.replaceAll("[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}","{}").replaceAll("[?].*","");loadRoutes.computeIfAbsent(phase+" "+route,k->new java.util.concurrent.ConcurrentLinkedQueue<>()).add(elapsed);}
        }
    }

    @Test void localeRosterIsPublicCanonicalOrderedAndStrict() throws Exception {
        var result=send("GET","/locales",null);assertThat(result.statusCode()).as(result.body()).isEqualTo(200);
        assertThat(json(result)).isEqualTo(JSON.readTree("[\"en\",\"sr-Latn-RS\",\"bs-Latn-BA\"]"));
        assertProblem(send("GET","/locales?country=RS",null),422,"VALIDATION_FAILED");
        assertProblem(send("GET","/locales","{}"),422,"VALIDATION_FAILED");
        assertThat(send("POST","/locales",null).statusCode()).isEqualTo(404);
        var cors=send("OPTIONS","/locales",null,"Origin","https://app.example","Access-Control-Request-Method","GET");
        assertThat(cors.statusCode()).isEqualTo(200);assertThat(cors.headers().firstValue("Access-Control-Allow-Origin")).contains("https://app.example");
        assertProblem(send("GET","/locales",null,"Origin","https://evil.example"),403,"CSRF_REJECTED");
    }
    @Test void everyBrowserRouteAnswersAllowedOriginPreflight() throws Exception {
        var missing=new java.util.TreeSet<String>();int checked=0;
        for(var mapping:app.getBeansOfType(org.springframework.web.servlet.mvc.method.annotation.RequestMappingHandlerMapping.class).values())
            for(var route:mapping.getHandlerMethods().keySet())
                for(String pattern:route.getPatternValues()){
                    if(!pattern.startsWith("/api/v1/")||pattern.startsWith("/api/v1/provider-callbacks/")||pattern.startsWith("/api/v1/auth/external/{"))continue;
                    // Constrained variables take their first alternative; request() maps unprefixed paths under /auth.
                    String path=pattern.substring("/api/v1".length()).replaceAll("\\{[^}:]+:([A-Za-z0-9_-]+)(?:\\|[^}]*)?\\}","$1").replaceAll("\\{[^}]+\\}","01a16edc-2237-7b29-833d-e7d033343ec6");
                    if(path.startsWith("/auth/"))path=path.substring("/auth".length());
                    for(var method:route.getMethodsCondition().getMethods()){
                        var preflight=send("OPTIONS",path,null,"Origin","https://app.example","Access-Control-Request-Method",method.name(),"Access-Control-Request-Headers","Content-Type,X-CSRF-Token");checked++;
                        if(preflight.statusCode()!=200||!preflight.headers().firstValue("Access-Control-Allow-Origin").orElse("").equals("https://app.example"))missing.add(method.name()+" "+pattern);
                    }
                }
        assertThat(checked).isGreaterThan(200);
        assertThat(missing).as("Browser routes without CORS for the allowed origin").isEmpty();
    }
