    private static final class NamesStore implements com.narudzbine.audit.api.IndependentObjects{
        final java.util.concurrent.ConcurrentHashMap<Key,byte[]> values=new java.util.concurrent.ConcurrentHashMap<>();Runnable afterIntent;boolean failCompletion;
        public boolean create(Key key,byte[] bytes){com.narudzbine.audit.api.IndependentEvidence.outside();if(failCompletion&&key.family()==Family.DELETION_COMPLETION)throw new com.narudzbine.audit.api.EvidenceFailure("EVIDENCE_UNAVAILABLE");boolean created=values.putIfAbsent(key,bytes.clone())==null;if(key.family()==Family.DELETION_INTENT&&afterIntent!=null){var callback=afterIntent;afterIntent=null;callback.run();}return created;}
        public java.util.Optional<byte[]> read(Key key){return java.util.Optional.ofNullable(values.get(key)).map(byte[]::clone);}public Page list(Family f,int count,Key after){throw new UnsupportedOperationException();}
    }
