    private Map<String,java.util.List<String>> nameRows(UUID order,boolean withoutNames){var rows=new java.util.LinkedHashMap<String,java.util.List<String>>();var queries=Map.of("purchase_order",new String[]{"id","id","(to_jsonb(r)-'snapshot')||jsonb_build_object('snapshot',r.snapshot-'submittedByDisplayName')"},"purchase_order_event",new String[]{"order_id","id","(to_jsonb(r)-'actor_display_name'-'result')||jsonb_build_object('result',r.result-'submittedByDisplayName')"},"order_submission_replay",new String[]{"order_id","order_id","(to_jsonb(r)-'original_result')||jsonb_build_object('original_result',r.original_result-'submittedByDisplayName')"},"order_stage_assignment",new String[]{"order_id","expected_revision,payload::text","(to_jsonb(r)-'result')||jsonb_build_object('result',r.result-'submittedByDisplayName')"},"order_message",new String[]{"order_id","id","to_jsonb(r)-'author_display_name'"},"message_replay",new String[]{"order_id","message_id","(to_jsonb(r)-'original_result')||jsonb_build_object('original_result',r.original_result-'authorDisplayName')"});queries.forEach((table,q)->rows.put(table,owner.queryForList("SELECT ("+(withoutNames?q[2]:"to_jsonb(r)")+")::text FROM "+table+" r WHERE "+q[0]+"=? ORDER BY "+q[1],String.class,order)));return rows;}
