    @Test void redactionPreviewBothCountriesTypesAndOriginalMetadataNoRawValues()throws Exception{
        String operator=nativeToken(privateOperator());for(String country:java.util.List.of("RS","BA"))for(String type:java.util.List.of("BUYER","VENDOR")){var f=redactionRequest(country,type,"OWNER");var r=redactionPreview(operator,f.id());assertThat(r.statusCode()).as(r.body()).isEqualTo(200);var value=json(r);assertThat(value.size()).isEqualTo(11);assertThat(value.path("country").asString()).isEqualTo(country);assertThat(value.path("subjectAccountId").asString()).isEqualTo(accountFor(f.email()).toString());assertThat(value.path("fieldActions").size()).isEqualTo(5);assertThat(value.path("retainedFamilies").size()).isEqualTo(10);assertThat(value.path("retainedFamilies").get(7).has("relatedRecords")).isTrue();assertThat(value.path("retainedFamilies").get(7).path("relatedRecords").isNull()).isTrue();assertThat(value.path("blockers").toString()).contains("OWNER_TRANSFER_OR_REVIEW_REQUIRED","AUTHENTICATION_CONTAINMENT_REQUIRED","EXECUTION_NOT_AVAILABLE");assertThat(value.path("executionAvailable").asBoolean()).isFalse();assertThat(r.headers().firstValue("Cache-Control")).contains("no-store");assertThat(r.body()).doesNotContain(f.reason(),f.email(),"nonce","session_token_hash","Synthetic operator assessment");assertThat(json(privacyRead(operator,f.id(),true))).isEqualTo(f.metadata());assertThat(privateAuditCount(f.id(),"PRIVACY_REDACTION_PREVIEWED")).isEqualTo(1);assertThat(privateAuditCount(f.id(),"PRIVACY_REVIEW_AUTHORIZED")).isEqualTo(1);}
    }
