    private UUID privacyId(){return app.getBean(com.narudzbine.shared.api.UuidGenerator.class).next();}
    private String privacyBody(UUID id,String kind,String reason){return JSON.writeValueAsString(Map.of("id",id,"kind",kind,"reason",reason));}
    private HttpResponse<String> privacyCreate(String token,String body)throws Exception{return send("POST","/organization/privacy-cases",body,"Authorization","Bearer "+token);}
    private HttpResponse<String> privacyRead(String token,UUID id,boolean admin)throws Exception{return send("GET",(admin?"/admin":"/organization")+"/privacy-cases/"+id,null,"Authorization","Bearer "+token);}
    private record PrivateRequestFixture(UUID id,String email,String reason,JsonNode metadata){}
    private PrivateRequestFixture privateRequest(String country)throws Exception{String email=businessAccount(country,"BUYER","OWNER"),reason="Original private request "+UUID.randomUUID();UUID id=privacyId();var r=privacyCreate(nativeToken(email),privacyBody(id,"EXPORT",reason));assertThat(r.statusCode()).as(r.body()).isEqualTo(201);return new PrivateRequestFixture(id,email,reason,json(r));}
    private String privateOperator(){String email=account();owner.update("INSERT INTO privacy_operator(account_id,created_at) VALUES(?,?)",accountFor(email),java.sql.Timestamp.from(CLOCK.instant()));return email;}
    private String privateReviewBody(){return JSON.writeValueAsString(Map.of("reason","Synthetic operator assessment","caseReference","SYN-PRIVATE-REVIEW"));}
    private HttpResponse<String> privateReview(String token,UUID id)throws Exception{return send("POST","/admin/privacy-cases/"+id+"/review",privateReviewBody(),"Authorization","Bearer "+token);}
    private int privateAuditCount(UUID id,String action){return owner.queryForObject("SELECT count(*) FROM audit_event WHERE resource_id=? AND action=?",Integer.class,id,action);}
    private String holdBase(UUID source){return "/admin/privacy-cases/"+source+"/holds";}
    private String holdBody(UUID id){return JSON.writeValueAsString(Map.of("id",id,"reason","Synthetic retention assessment","caseReference","SYN-LOCAL-HOLD"));}
    private HttpResponse<String> holdCreate(String token,UUID source,UUID id)throws Exception{return send("POST",holdBase(source),holdBody(id),"Authorization","Bearer "+token);}
    private HttpResponse<String> holdRelease(String token,UUID source,UUID id,String revision)throws Exception{return send("POST",holdBase(source)+"/"+id+"/release",JSON.writeValueAsString(Map.of("expectedRevision",revision,"reason","Synthetic retention assessment","caseReference","SYN-LOCAL-HOLD")),"Authorization","Bearer "+token);}
    private void cleanupSyntheticHold(String operator,UUID source,UUID id)throws Exception{
        if(owner.queryForObject("SELECT EXISTS(SELECT 1 FROM retention_hold WHERE id=? AND state='ACTIVE')",Boolean.class,id)){
            owner.update("UPDATE privacy_operator SET enabled=true,revision=revision+1 WHERE account_id=? AND NOT enabled",accountFor(operator));
            String revision=app.getBean(com.narudzbine.shared.api.ResourceRevisions.class).encode("hold/v1",id,1);
            var response=holdRelease(nativeToken(operator),source,id,revision);assertThat(response.statusCode()).as(response.body()).isEqualTo(200);
        }
    }
    @Test void retentionHoldsBothCountriesReturnSafeMetadataAndOriginalReplay()throws Exception{
        String email=privateOperator(),token=nativeToken(email);
        for(String country:java.util.List.of("RS","BA")){var source=privateRequest(country);UUID id=privacyId();try{
            var created=holdCreate(token,source.id(),id);assertThat(created.statusCode()).as(created.body()).isEqualTo(201);assertThat(created.headers().firstValue("Location")).contains("/api/v1"+holdBase(source.id())+"/"+id);var value=json(created);assertThat(value.size()).isEqualTo(9);assertThat(value.path("state").asString()).isEqualTo("ACTIVE");assertThat(value.path("country").asString()).isEqualTo(country);assertThat(value.path("releasedAt").isNull()).isTrue();assertThat(created.headers().firstValue("Cache-Control")).contains("no-store");assertThat(created.body()).doesNotContain(source.reason(),"SYN-LOCAL-HOLD","Synthetic retention assessment");
            var read=send("GET",holdBase(source.id())+"/"+id,null,"Authorization","Bearer "+token);assertThat(read.statusCode()).as(read.body()).isEqualTo(200);assertThat(json(read)).isEqualTo(value);
            var released=holdRelease(token,source.id(),id,value.path("revision").asString());assertThat(released.statusCode()).as(released.body()).isEqualTo(200);assertThat(json(released).path("state").asString()).isEqualTo("RELEASED");assertThat(json(holdCreate(token,source.id(),id))).isEqualTo(value);assertThat(json(holdRelease(token,source.id(),id,value.path("revision").asString()))).isEqualTo(json(released));assertThat(json(privacyRead(token,source.id(),true))).isEqualTo(source.metadata());
        }finally{cleanupSyntheticHold(email,source.id(),id);}}
    }
    @Test void retentionHoldsExpireCsvAccessWithoutDiscardingHeldArtifact()throws Exception{
        String buyer=businessAccount("RS","BUYER","OWNER"),token=nativeToken(buyer);var job=exportSaved(token,exportBody("ORDERS"));exportReady(token,job);UUID export=UUID.fromString(job.path("id").asString());byte[] artifact=owner.queryForObject("SELECT artifact FROM commercial_export WHERE id=?",byte[].class,export);
        var source=privateRequest("RS");String operator=privateOperator();UUID hold=privacyId();
        try{var activated=holdCreate(nativeToken(operator),source.id(),hold);assertThat(activated.statusCode()).as(activated.body()).isEqualTo(201);CLOCK.advance(86400);
            assertProblem(exportContent(nativeToken(buyer),job),409,"EXPORT_EXPIRED");assertThat(owner.queryForObject("SELECT artifact_held AND state='EXPIRED' FROM commercial_export WHERE id=?",Boolean.class,export)).isTrue();assertThat(owner.queryForObject("SELECT artifact FROM commercial_export WHERE id=?",byte[].class,export)).isEqualTo(artifact);
            cleanupSyntheticHold(operator,source.id(),hold);exportTick();assertThat(owner.queryForObject("SELECT NOT artifact_held AND artifact IS NULL AND digest IS NULL FROM commercial_export WHERE id=?",Boolean.class,export)).isTrue();assertProblem(exportContent(nativeToken(buyer),job),409,"EXPORT_EXPIRED");
        }finally{cleanupSyntheticHold(operator,source.id(),hold);}
    }
