    @Test void privacyCasesNormalizedNaturalReplayOriginalSnapshotAndKeyRotation()throws Exception{
        String email=businessAccount("RS","VENDOR","ADMIN"),token=nativeToken(email);UUID id=privacyId();String body=privacyBody(id,"REDACTION","  Cafe"+(char)0x301+"  ");var original=privacyCreate(token,body);assertThat(original.statusCode()).as(original.body()).isEqualTo(201);
        String normalized=privacyBody(id,"REDACTION","Caf"+(char)0xe9);assertThat(json(privacyCreate(token,normalized))).isEqualTo(json(original));
        assertProblem(privacyCreate(token,privacyBody(id,"EXPORT","Caf"+(char)0xe9)),409,"IDEMPOTENCY_MISMATCH");assertProblem(privacyCreate(token,privacyBody(id,"REDACTION","Changed reason")),409,"IDEMPOTENCY_MISMATCH");
        byte[] key=new byte[32];java.util.Arrays.fill(key,(byte)91);var beans=new org.springframework.beans.factory.support.StaticListableBeanFactory(Map.of("revision",new com.narudzbine.shared.api.ResourceRevisions(key)));
        var rotated=new com.narudzbine.audit.infrastructure.JdbcPrivacyCases(app.getBean(JdbcTemplate.class),beans.getBeanProvider(com.narudzbine.shared.api.ResourceRevisions.class),CLOCK,app.getBean(com.narudzbine.shared.api.UuidGenerator.class));
        var tx=new TransactionTemplate(app.getBean(org.springframework.transaction.PlatformTransactionManager.class));var scope=new com.narudzbine.audit.api.PrivacyCases.Scope(accountFor(email),organizationFor(email),"RS");
        var replay=tx.execute(status->rotated.create(scope,new com.narudzbine.audit.api.PrivacyCases.Command(id,"REDACTION","Caf"+(char)0xe9)));
        assertThat(JSON.readTree(JSON.writeValueAsString(replay))).isEqualTo(json(original));
        assertThat(tx.execute(status->rotated.read(scope,id)).revision()).isNotEqualTo(replay.revision());
        assertThat(owner.queryForObject("SELECT count(*) FROM audit_event WHERE resource_id=? AND action='PRIVACY_CASE_REQUESTED'",Integer.class,id)).isEqualTo(1);
    }
