    @Test void privacyCasesCleanupIsBoundedRepeatableAndCannotRevivePayloads()throws Exception{
        String email=businessAccount("RS","BUYER","ADMIN");var tx=new TransactionTemplate(app.getBean(org.springframework.transaction.PlatformTransactionManager.class));var service=app.getBean(com.narudzbine.audit.api.PrivacyCases.class);var scope=new com.narudzbine.audit.api.PrivacyCases.Scope(accountFor(email),organizationFor(email),"RS");
        java.util.List<UUID> ids=new java.util.ArrayList<>();
        tx.executeWithoutResult(status->{for(int i=0;i<101;i++){UUID id=privacyId();ids.add(id);service.create(scope,new com.narudzbine.audit.api.PrivacyCases.Command(id,"EXPORT","Synthetic bounded cleanup"));}});
        var cleanup=app.getBean(com.narudzbine.audit.infrastructure.PrivacyReplayCleanup.class);CLOCK.advance(7*86400);
        int first=cleanup.sweep();assertThat(first).isEqualTo(100);assertThat(owner.queryForObject("SELECT count(*) FROM privacy_case_creation WHERE organization_id=? AND original_response IS NOT NULL",Integer.class,scope.organization())).isGreaterThanOrEqualTo(1);
        for(int i=0;i<20&&cleanup.sweep()>0;i++){}
        assertThat(owner.queryForObject("SELECT count(*) FROM privacy_case_creation WHERE organization_id=? AND original_response IS NOT NULL",Integer.class,scope.organization())).isZero();assertThat(cleanup.sweep()).isZero();
        assertThat(owner.queryForObject("SELECT count(*) FROM privacy_case WHERE organization_id=?",Integer.class,scope.organization())).isEqualTo(101);
        assertThatThrownBy(()->owner.update("UPDATE privacy_case_creation SET original_response='{}' WHERE id=?",ids.getFirst())).isInstanceOf(org.springframework.dao.DataAccessException.class);
    }
