        assertThat(owner.queryForObject("SELECT count(*) FROM stock_replay WHERE product_id=?",Integer.class,f.product())).isEqualTo(1006);assertThat(owner.queryForObject("SELECT available_count FROM stock_balance WHERE product_id=?",Integer.class,f.product())).isEqualTo(2);
