    private record RetiredSecret(String table,String key,UUID id,String kind){}
    private java.util.List<RetiredSecret> secretRetentionSources()throws Exception{
        var sources=new java.util.ArrayList<RetiredSecret>();String email=businessAccount("RS","BUYER","STAFF"),token=nativeToken(email);assertThat(requestReset(email).statusCode()).isEqualTo(202);
        sources.add(new RetiredSecret("password_reset_delivery","proof_id",owner.queryForObject("SELECT id FROM password_reset_proof WHERE account_id=? AND state='ACTIVE'",UUID.class,accountFor(email)),"RESET"));
        var change=json(createEmail(token,UUID.randomUUID()+"@example.com"));for(UUID proof:owner.queryForList("SELECT id FROM email_change_proof WHERE change_id=?",UUID.class,UUID.fromString(change.path("id").asString())))sources.add(new RetiredSecret("email_change_delivery","proof_id",proof,"EMAIL_PROOF"));
        String admin=nativeToken(account());UUID invitation=UUID.fromString(json(setupInvite(admin,UUID.randomUUID()+"@example.com","RS","BUYER")).path("id").asString());sources.add(new RetiredSecret("setup_delivery","id",owner.queryForObject("SELECT id FROM setup_delivery WHERE invitation_id=? AND proof_id IS NULL",UUID.class,invitation),"SETUP"));
        String former=businessAccount("BA","VENDOR","OWNER"),target=addMember(organizationFor(former),"STAFF");var initial=json(recoveryCreate(admin,recoveryBody("OWNER",organizationFor(former),accountFor(target),null)));assertThat(recoveryReview(nativeToken(account()),initial,true).statusCode()).isEqualTo(200);
        sources.add(new RetiredSecret("recovery_delivery","id",owner.queryForObject("SELECT id FROM recovery_delivery WHERE case_id=? AND kind='ACCEPTANCE'",UUID.class,UUID.fromString(initial.path("id").asString())),"RECOVERY"));return sources;
    }
    private boolean secretPresent(RetiredSecret s){return owner.queryForObject("SELECT encrypted_token IS NOT NULL FROM "+s.table()+" WHERE "+s.key()+"=?",Boolean.class,s.id());}
    @Test void secretRetentionActualSourcesKeepIdentityAndRetiredResolversSuppressDelivery()throws Exception{
        var sources=secretRetentionSources();var before=new java.util.HashMap<UUID,String>();for(var source:sources){assertThat(secretPresent(source)).isTrue();before.put(source.id(),owner.queryForObject("SELECT (to_jsonb(d)-'encrypted_token')::text FROM "+source.table()+" d WHERE "+source.key()+"=?",String.class,source.id()));}
        CLOCK.advance(39*86400);var outcome=retentionMaintenance().runOnce();assertThat(outcome.deferredJobs()).isEmpty();assertThat(outcome.completedJobs()).contains("identity-reset-secrets","identity-email-secrets","identity-setup-secrets","identity-recovery-secrets");
        var resolver=app.getBean(com.narudzbine.notifications.api.ProviderDelivery.TechnicalEmails.class);
        for(var source:sources){assertThat(secretPresent(source)).isFalse();assertThat(owner.queryForObject("SELECT (to_jsonb(d)-'encrypted_token')::text FROM "+source.table()+" d WHERE "+source.key()+"=?",String.class,source.id())).isEqualTo(before.get(source.id()));new TransactionTemplate(app.getBean(org.springframework.transaction.PlatformTransactionManager.class)).executeWithoutResult(t->assertThat(resolver.resolve(source.kind(),source.id())).isNull());}
    }
