    private record RetiredProof(String table,String field,UUID id){}
    private record ProofRetirementFixture(java.util.List<RetiredProof> proofs,String deviceToken,UUID installation,String push,JsonNode challenge,String code,HttpResponse<String> oauth){}
    private ProofRetirementFixture proofRetirementFixture()throws Exception{
        var sources=secretRetentionSources();var proofs=new java.util.ArrayList<RetiredProof>();
        for(var source:sources){if(source.kind().equals("RESET"))proofs.add(new RetiredProof("password_reset_proof","token_hash",source.id()));else if(source.kind().equals("EMAIL_PROOF"))proofs.add(new RetiredProof("email_change_proof","token_hash",source.id()));else if(source.kind().equals("SETUP")){UUID invitation=owner.queryForObject("SELECT invitation_id FROM setup_delivery WHERE id=?",UUID.class,source.id());setupProof(setupToken(invitation),invitation);proofs.add(new RetiredProof("setup_email_proof","token_hash",owner.queryForObject("SELECT id FROM setup_email_proof WHERE invitation_id=? AND state='ACTIVE'",UUID.class,invitation)));}}
        String token=nativeToken(businessAccount("RS","VENDOR","STAFF")),push=pushToken();UUID installation=UUID.randomUUID();var provider=new DeliveryPush();deliveryUseVerification(provider);var challenge=json(deviceRegister(token,installation,"WEB",push));String code=provider.data.getFirst().get("verificationCode");assertThat(deliveryCompleteDevice(token,installation,push,challenge,code).statusCode()).isEqualTo(201);proofs.add(new RetiredProof("device_verification","code_hash",UUID.fromString(challenge.path("id").asString())));
        var oauth=externalStart("GOOGLE","LOGIN","NATIVE",null,null,null);assertThat(oauth.statusCode()).isEqualTo(200);proofs.add(new RetiredProof("external_challenge","encrypted_verifier",owner.queryForObject("SELECT id FROM external_challenge WHERE state_hash=?",UUID.class,digest(externalState(oauth)))));return new ProofRetirementFixture(proofs,token,installation,push,challenge,code,oauth);
    }
    private boolean proofSecretPresent(RetiredProof p){return owner.queryForObject("SELECT "+p.field()+" IS NOT NULL FROM "+p.table()+" WHERE id=?",Boolean.class,p.id());}
    @Test void proofRetentionRealMailDeviceAndOAuthSourcesRetireAndStayUnusableAfterClockRollback()throws Exception{
        var fixture=proofRetirementFixture();
        // Preserve the live row through unresolved work to exercise the retired-code reader itself.
        owner.update("INSERT INTO credential_operation(id,account_id,kind,state,security_epoch,credential_generation,current_session_id,created_at,updated_at) SELECT ?,account_id,'CHANGE','UNKNOWN',security_epoch,credential_generation,id,?,? FROM application_session WHERE token_hash=?",taxonomyId(),java.sql.Timestamp.from(CLOCK.instant()),java.sql.Timestamp.from(CLOCK.instant()),digest(fixture.deviceToken()));
        var before=new java.util.HashMap<UUID,String>();for(var p:fixture.proofs()){assertThat(proofSecretPresent(p)).isTrue();before.put(p.id(),owner.queryForObject("SELECT (to_jsonb(p)-?)::text FROM "+p.table()+" p WHERE id=?",String.class,p.field(),p.id()));}
        CLOCK.advance(39*86400);
        // Isolate the original five-field proof reader contract from later binding/session jobs.
        var proofTx=new TransactionTemplate(app.getBean(org.springframework.transaction.PlatformTransactionManager.class));proofTx.executeWithoutResult(t->{var sources=app.getBean(com.narudzbine.identity.application.IdentitySecretRetention.class);sources.reset();sources.email();sources.setup();sources.recovery();var proofs=app.getBean(com.narudzbine.identity.application.ProofSecretRetention.class);proofs.reset();proofs.email();proofs.setup();proofs.device();proofs.oauth();});
        for(var p:fixture.proofs()){assertThat(proofSecretPresent(p)).isFalse();assertThat(owner.queryForObject("SELECT (to_jsonb(p)-?)::text FROM "+p.table()+" p WHERE id=?",String.class,p.field(),p.id())).isEqualTo(before.get(p.id()));}
        CLOCK.advance(-39*86400);assertProblem(deliveryCompleteDevice(fixture.deviceToken(),fixture.installation(),fixture.push(),fixture.challenge(),fixture.code()),409,"DEVICE_VERIFICATION_INVALID");
        EXTERNAL.before=()->{throw new AssertionError("Retired OAuth verifier must never reach provider");};try{assertProblem(externalCallback("GOOGLE",fixture.oauth(),"synthetic"),401,"TOKEN_INVALID");}finally{EXTERNAL.before=()->{};}
    }
    @Test void proofRetentionMissingEmailHashPermissionDefersOnlyItsJobAndRetries()throws Exception{
        var fixture=proofRetirementFixture();CLOCK.advance(39*86400);owner.execute("REVOKE UPDATE ON email_change_proof FROM http_runtime");owner.execute("REVOKE UPDATE(token_hash) ON email_change_proof FROM http_runtime");
        try{var result=retentionMaintenance().runOnce();assertThat(result.deferredJobs()).containsExactly("proof-email-secrets");for(var p:fixture.proofs())assertThat(proofSecretPresent(p)).isEqualTo(p.table().equals("email_change_proof"));}finally{owner.execute("GRANT UPDATE ON email_change_proof TO http_runtime");owner.execute("GRANT UPDATE(token_hash) ON email_change_proof TO http_runtime");}
        assertThat(retentionMaintenance().runOnce().deferredJobs()).isEmpty();for(var p:fixture.proofs())assertThat(proofSecretPresent(p)).isFalse();
    }

    private HttpRequest request(String method, String path, String body, String... headers) {
        var request = HttpRequest.newBuilder(URI.create("http://127.0.0.1:" + port + ((path.startsWith("/locales") || path.startsWith("/suggestions") || path.startsWith("/exports") || path.startsWith("/reports") || path.startsWith("/provider-callbacks") || path.startsWith("/me") || path.startsWith("/organization") || path.startsWith("/admin") || path.startsWith("/recovery-cases") || path.startsWith("/invitations") || path.startsWith("/setup/") || path.startsWith("/relationships") || path.startsWith("/partners") || path.startsWith("/catalogue/") || path.startsWith("/plans") || path.startsWith("/promotions") || path.startsWith("/inventory") || path.startsWith("/vendors") || path.startsWith("/favorites") || path.startsWith("/drafts") || path.startsWith("/order-reviews") || path.startsWith("/orders")) ? "/api/v1" : "/api/v1/auth") + path))
                .timeout(java.time.Duration.ofSeconds(loadFixtureSessions&&path.startsWith("/catalogue/import-previews/")&&path.endsWith("/confirmation")?40:15));
        if (headers.length > 0) { request.headers(headers); }
        if (body != null) { request.header("Content-Type", "application/json"); }
        return request.method(method, body == null ? HttpRequest.BodyPublishers.noBody() : HttpRequest.BodyPublishers.ofString(body)).build();
    }
    private static String loginBody(String email, String transport, String nonce) {
        var fields = new java.util.HashMap<String,Object>(Map.of("email", email, "password", "long synthetic password", "transport", transport, "deviceLabel", "Test device"));
        if (nonce != null) { fields.put("preAuthNonce", nonce); }
        return JSON.writeValueAsString(fields);
    }
    private static JsonNode json(HttpResponse<String> response) { return JSON.readTree(response.body()); }
    private static String cookie(HttpResponse<String> response, String name) {
        return response.headers().allValues("Set-Cookie").stream().filter(value -> value.startsWith(name + "=")).findFirst().orElseThrow().split(";", 2)[0];
    }
    private static void assertProblem(HttpResponse<String> response, int status, String code) {
        assertThat(response.statusCode()).isEqualTo(status);
        var problem = json(response);
        assertThat(problem.path("code").asString()).isEqualTo(code);
        assertThat(problem.path("requestId").asString()).isEqualTo(response.headers().firstValue("X-Request-Id").orElseThrow());
        assertThat(UUID.fromString(problem.path("requestId").asString()).version()).isEqualTo(7);
        assertThat(response.headers().firstValue("Cache-Control")).contains("no-store");
    }
    private static String account() {
        UUID id = UUID.randomUUID();
        String email = id + "@example.com";
        var subject = new PasswordCredentialVerifier.Subject(UUID.randomUUID(), UUID.randomUUID());
        setup.executeWithoutResult(status -> {
            owner.update("INSERT INTO account_identity(id,kind,email,email_verified,display_name,state) VALUES (?,'PLATFORM_ADMIN',?,true,'Test','ACTIVE')", id, email);
            owner.update("INSERT INTO platform_account(id) VALUES (?)", id);
            owner.update("INSERT INTO managed_password_identity(account_id,tenant_id,provider_user_id) VALUES (?,?,?)", id, subject.tenantId(), subject.userId());
        });
        PROVIDER.subjects.put(email, subject);
        return email;
    }

