    @Test void externalNativeProofExpiresWhileWaitingForIdentityGuard() throws Exception {
        String email=account(),token=nativeToken(email),subject=UUID.randomUUID().toString();var callback=externalCallback("GOOGLE",externalStart("GOOGLE","LINK","NATIVE",token,null,null),subject);
        String body=JSON.writeValueAsString(Map.of("code",query(callback.headers().firstValue("Location").orElseThrow()).get("code"),"codeVerifier",VERIFIER));
        java.util.concurrent.CompletableFuture<HttpResponse<String>> pending;
        try(var connection=java.sql.DriverManager.getConnection(DATABASE.getJdbcUrl(),DATABASE.getUsername(),DATABASE.getPassword())) {
            connection.setAutoCommit(false);
            try(var statement=connection.prepareStatement("SELECT pg_advisory_xact_lock(hashtextextended(?,16001))")) {statement.setString(1,"https://google.example\n"+subject);statement.execute();}
            pending=client.sendAsync(request("POST","/external/exchanges",body),HttpResponse.BodyHandlers.ofString());
            long deadline=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(4);boolean blocked=false;
            while(System.nanoTime()<deadline) {blocked=owner.queryForObject("SELECT count(*) FROM pg_stat_activity WHERE usename='http_runtime' AND wait_event_type='Lock' AND query LIKE '%16001%'",Integer.class)>0;if(blocked){break;}java.util.concurrent.locks.LockSupport.parkNanos(1000000);}
            assertThat(blocked).as("exchange waits on the actual issuer/subject guard").isTrue();CLOCK.advance(60);connection.commit();
        }
        assertProblem(pending.get(),401,"TOKEN_INVALID");assertThat(owner.queryForObject("SELECT count(*) FROM external_identity WHERE account_id=?",Integer.class,accountFor(email))).isZero();
        assertThat(send("GET","/sessions",null,"Authorization","Bearer "+token).statusCode()).isEqualTo(200);
    }

    private static final String VERIFIER="s".repeat(43);
    private HttpResponse<String> externalStart(String provider,String purpose,String transport,String token,String browserCookie,String csrf) throws Exception {
        var fields=new java.util.HashMap<String,Object>(Map.of("provider",provider,"purpose",purpose,"transport",transport,"returnTarget",transport.equals("BROWSER")?"WEB":"ANDROID"));fields.put("codeChallenge",transport.equals("BROWSER")?null:com.narudzbine.identity.application.ExternalSecrets.challenge(VERIFIER));
        var headers=new java.util.ArrayList<String>();if(transport.equals("BROWSER")) { headers.addAll(java.util.List.of("Origin","https://app.example"));if(browserCookie!=null) { headers.addAll(java.util.List.of("Cookie",browserCookie,"X-CSRF-Token",csrf)); } }else if(token!=null) {headers.addAll(java.util.List.of("Authorization","Bearer "+token));}
        return send("POST","/external/challenges",JSON.writeValueAsString(fields),headers.toArray(String[]::new));
    }
    private HttpResponse<String> externalCallback(String provider,HttpResponse<String> start,String subject) throws Exception {
        assertThat(start.statusCode()).isEqualTo(200);String state=externalState(start),flow=start.headers().allValues("Set-Cookie").isEmpty()?null:cookie(start,"__Host-narudzbine_oidc");
        String body="state="+state+"&code="+java.net.URLEncoder.encode(subject,java.nio.charset.StandardCharsets.UTF_8);
        var builder=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/v1/auth/external/"+provider+"/callback"+(provider.equals("GOOGLE")?"?"+body:"")));
        if(flow!=null) {builder.header("Cookie",flow);}if(provider.equals("APPLE")) { builder.header("Origin","https://appleid.apple.com").header("Content-Type","application/x-www-form-urlencoded").POST(HttpRequest.BodyPublishers.ofString(body)); }else{builder.GET();}
        return client.send(builder.build(),HttpResponse.BodyHandlers.ofString());
    }
    private HttpResponse<String> externalExchange(HttpResponse<String> callback,String verifier) throws Exception {
        assertThat(callback.statusCode()).isEqualTo(303);return send("POST","/external/exchanges",JSON.writeValueAsString(Map.of("code",query(callback.headers().firstValue("Location").orElseThrow()).get("code"),"codeVerifier",verifier)));
    }
    private static String externalState(HttpResponse<String> start) { return query(json(start).path("authorizationUrl").asString()).get("state"); }
    private static Map<String,String> query(String uri) {var result=new java.util.HashMap<String,String>();for(String part:URI.create(uri).getRawQuery().split("&")) {String[] pair=part.split("=",2);result.put(java.net.URLDecoder.decode(pair[0],java.nio.charset.StandardCharsets.UTF_8),java.net.URLDecoder.decode(pair[1],java.nio.charset.StandardCharsets.UTF_8));}return result;}
    private static UUID seedExternal(String email,String provider,String subject) {UUID id=app.getBean(com.narudzbine.shared.api.UuidGenerator.class).next();owner.update("INSERT INTO external_identity(id,account_id,provider,issuer,subject,created_at,updated_at) VALUES (?,?,?,?,?,?,?)",id,accountFor(email),provider,"https://"+provider.toLowerCase()+".example",subject,java.sql.Timestamp.from(CLOCK.instant()),java.sql.Timestamp.from(CLOCK.instant()));return id;}
    static class FakeExternal implements com.narudzbine.identity.api.ExternalIdentityProvider {
        volatile Runnable before=()->{};
        public String authorization(Provider provider,Purpose purpose,String state,String verifier,String nonce) {return "https://"+provider.name().toLowerCase()+".example/authorize?state="+state;}
        public Subject verify(Provider provider,Purpose purpose,String state,String code,String verifier,String nonce,Instant startedAt) {
            assertThat(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive()).isFalse();before.run();return new Subject("https://"+provider.name().toLowerCase()+".example",code);
        }
    }


