    private static void awaitSetupEmailGuard(){long deadline=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(3);boolean blocked=false;while(System.nanoTime()<deadline){blocked=owner.queryForObject("SELECT count(*) FROM pg_stat_activity WHERE usename='http_runtime' AND wait_event_type='Lock' AND query LIKE '%lock_login_email%'",Integer.class)>0;if(blocked){break;}java.util.concurrent.locks.LockSupport.parkNanos(1000000);}assertThat(blocked).as("setup waits on actual address guard").isTrue();}

    private HttpResponse<String> setupInvite(String admin,String email,String country,String type)throws Exception{return send("POST","/admin/setup-invitations",JSON.writeValueAsString(inviteSetupBody(email,country,type)),"Authorization","Bearer "+admin);}
    private static Map<String,Object> inviteSetupBody(String email,String country,String type){var body=new java.util.HashMap<String,Object>(Map.of("recipientEmail",email,"country",country,"type",type,"reason","Synthetic documentary verification"));body.put("planRevisionId",type.equals("VENDOR")?planId("STARTER"):null);return body;}
    private static UUID planId(String code){return owner.queryForObject("SELECT id FROM plan_revision WHERE code=? AND revision=1",UUID.class,code);}
    private static String setupToken(UUID id){var row=owner.queryForMap("SELECT d.id,d.encrypted_token FROM setup_delivery d JOIN setup_invitation i ON i.id=d.invitation_id AND i.generation=d.generation WHERE d.invitation_id=? AND d.proof_id IS NULL",id);return app.getBean(com.narudzbine.identity.application.SetupDeliveryCipher.class).decrypt((UUID)row.get("id"),(byte[])row.get("encrypted_token"),false);}
    private String setupProof(String token,UUID id)throws Exception{var sent=send("POST","/invitations/email-proofs",JSON.writeValueAsString(Map.of("token",token)));assertThat(sent.statusCode()).isEqualTo(202);return setupDeliveryProof(id);}
    private static String setupDeliveryProof(UUID id){var row=owner.queryForMap("SELECT d.id,d.encrypted_token FROM setup_delivery d JOIN setup_email_proof p ON p.id=d.proof_id WHERE d.invitation_id=? AND p.state='ACTIVE'",id);return app.getBean(com.narudzbine.identity.application.SetupDeliveryCipher.class).decrypt((UUID)row.get("id"),(byte[])row.get("encrypted_token"),true);}
    private static Map<String,Object> setupBody(String token,String proof,String country){var address=new java.util.HashMap<String,Object>(Map.of("line1","Synthetic street","city","Synthetic city","postalCode","11000","country",country));address.put("line2",null);address.put("latitude",null);address.put("longitude",null);var body=new java.util.HashMap<String,Object>(Map.of("token",token,"emailProof",proof,"password","  Synthetic setup password  ","ownerDisplayName","Synthetic owner","displayName","Synthetic organization","legalName","Synthetic legal name","registrationIdentifier",UUID.randomUUID().toString(),"registeredAddress",address,"defaultLanguage",country.equals("RS")?"sr-Latn-RS":"bs-Latn-BA"));body.put("taxIdentifier",null);return body;}
    static class FakeSetupProvider implements com.narudzbine.identity.api.SetupCredentialProvider{
        final UUID tenant=UUID.randomUUID();final AtomicInteger calls=new AtomicInteger();final Map<UUID,PasswordCredentialVerifier.Subject> applied=new ConcurrentHashMap<>();volatile Outcome outcome=Outcome.APPLIED;volatile boolean applyUnknown,allowReconcile;volatile java.util.function.Consumer<UUID> before=op->{};
        void reset(){calls.set(0);outcome=Outcome.APPLIED;applyUnknown=false;allowReconcile=false;before=op->{};}
        public UUID tenant(){return tenant;}
        public Outcome create(PasswordCredentialVerifier.Subject candidate,UUID op,String email,String password){assertThat(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive()).isFalse();calls.incrementAndGet();before.accept(op);if(outcome==Outcome.APPLIED||applyUnknown){applied.put(op,candidate);PROVIDER.subjects.put(email,candidate);PROVIDER.passwords.put(email,password);}return outcome;}
        public Outcome reconcile(PasswordCredentialVerifier.Subject candidate,UUID op,String email){assertThat(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive()).isFalse();return allowReconcile&&candidate.equals(applied.get(op))?Outcome.APPLIED:Outcome.UNKNOWN;}
    }


    @Test void memberSetupCreatesOnlyInvitedMembershipAcrossCountriesTypesAndRoles()throws Exception{
        for(String country:java.util.List.of("RS","BA")){for(String type:java.util.List.of("BUYER","VENDOR")){
            CLOCK.advance(3600);SETUP.reset();String creator=businessAccount(country,type,"OWNER"),admin=nativeToken(creator);UUID org=organizationFor(creator);int organizations=owner.queryForObject("SELECT count(*) FROM organization",Integer.class);
            for(String role:java.util.List.of("ADMIN","STAFF")){
                String email=UUID.randomUUID()+"@example.com";var invited=memberInvite(admin,email,role);assertThat(invited.statusCode()).as(invited.body()).isEqualTo(201);UUID id=UUID.fromString(json(invited).path("id").asString());assertThat(json(invited).path("purpose").asString()).isEqualTo("MEMBER");assertThat(json(invited).path("targetOrganizationId").asString()).isEqualTo(org.toString());String token=setupToken(id),proof=setupProof(token,id);var body=memberBody(token,proof);
                var completed=send("POST","/setup/members",JSON.writeValueAsString(body));assertThat(completed.statusCode()).as(completed.body()).isEqualTo(201);assertThat(completed.headers().allValues("Set-Cookie")).isEmpty();var account=json(completed);assertThat(account.path("organizationId").asString()).isEqualTo(org.toString());assertThat(account.path("role").asString()).isEqualTo(role);assertThat(account.path("languageOverride").isNull()).isTrue();assertThat(account.path("homeLocationId").isNull()).isTrue();
                var login=loginWithPassword(email,"  Synthetic member password  ");assertThat(login.statusCode()).isEqualTo(200);assertThat(send("GET","/organization",null,"Authorization","Bearer "+json(login).path("bearerToken").asString()).statusCode()).isEqualTo(200);
                body.put("password","A different valid password");var replay=send("POST","/setup/members",JSON.writeValueAsString(body));assertThat(replay.statusCode()).isEqualTo(200);assertThat(json(replay)).isEqualTo(account);assertProblem(loginWithPassword(email,"A different valid password"),401,"INVALID_LOGIN");
            }
            assertThat(owner.queryForObject("SELECT count(*) FROM organization",Integer.class)).isEqualTo(organizations);assertThat(owner.queryForObject("SELECT owner_account_id FROM organization WHERE id=?",UUID.class,org)).isEqualTo(accountFor(creator));assertThat(owner.queryForObject("SELECT count(*) FROM setup_registration_claim c JOIN setup_intent i ON i.id=c.intent_id WHERE i.organization_id=?",Integer.class,org)).isZero();assertThat(SETUP.calls).hasValue(2);
        }}
    }
