        assertThat(owner.queryForObject("SELECT state FROM setup_intent WHERE invitation_id=?",String.class,id)).isEqualTo("APPLIED");assertThat(owner.queryForObject("SELECT count(*) FROM account_identity WHERE email=?",Integer.class,email)).isZero();assertThat(activeTradingCount(vendorOrg)).isZero();body.put("emailProof",setupProof(token,id));assertThat(send("POST","/setup/organizations",JSON.writeValueAsString(body)).statusCode()).isEqualTo(201);assertThat(SETUP.calls).hasValue(1);
