    private static void awaitRuntimeBlockedBy(java.sql.Connection blocker,String description)throws java.sql.SQLException{
        int pid;try(var statement=blocker.createStatement();var row=statement.executeQuery("SELECT pg_backend_pid()")){assertThat(row.next()).isTrue();pid=row.getInt(1);}
        long deadline=System.nanoTime()+java.util.concurrent.TimeUnit.MILLISECONDS.toNanos(1500);boolean blocked=false;
        while(System.nanoTime()<deadline){blocked=owner.queryForObject("WITH RECURSIVE blocked(pid) AS (SELECT pid FROM pg_stat_activity WHERE ?=ANY(pg_blocking_pids(pid)) UNION SELECT a.pid FROM pg_stat_activity a JOIN blocked b ON b.pid=ANY(pg_blocking_pids(a.pid))) SELECT count(*) FROM blocked b JOIN pg_stat_activity a ON a.pid=b.pid WHERE a.usename='http_runtime' AND a.wait_event_type='Lock'",Integer.class,pid)>0;if(blocked){break;}java.util.concurrent.locks.LockSupport.parkNanos(1000000);}
        assertThat(blocked).as(description).isTrue();
    }
