        String vendor=tradingVendor("RS"),buyerOne=businessAccount("RS","BUYER","OWNER"),buyerTwo=businessAccount("RS","BUYER","OWNER"),one=nativeToken(account()),two=nativeToken(account());UUID v=organizationFor(vendor);seedTradingConnections(v,4);
