            var first=client.sendAsync(request("POST","/admin/connections",JSON.writeValueAsString(Map.of("vendorId",v,"buyerId",organizationFor(buyerOne),"reason","First")),"Authorization","Bearer "+one),HttpResponse.BodyHandlers.ofString());
            var second=client.sendAsync(request("POST","/admin/connections",JSON.writeValueAsString(Map.of("vendorId",v,"buyerId",organizationFor(buyerTwo),"reason","Second")),"Authorization","Bearer "+two),HttpResponse.BodyHandlers.ofString());
            int pid;try(var q=c.createStatement();var rows=q.executeQuery("SELECT pg_backend_pid()")){rows.next();pid=rows.getInt(1);}boolean bothWaiting=false;long deadline=System.nanoTime()+1_500_000_000L;
            while(System.nanoTime()<deadline){if(owner.queryForObject("WITH RECURSIVE blocked(pid) AS (SELECT pid FROM pg_stat_activity WHERE ?=ANY(pg_blocking_pids(pid)) UNION SELECT a.pid FROM pg_stat_activity a JOIN blocked b ON b.pid=ANY(pg_blocking_pids(a.pid))) SELECT count(*) FROM blocked b JOIN pg_stat_activity a ON a.pid=b.pid WHERE a.usename='http_runtime' AND a.wait_event_type='Lock'",Integer.class,pid)==2){bothWaiting=true;break;}Thread.sleep(10);}
            assertThat(bothWaiting).as("both admin commands wait on the same vendor guard").isTrue();c.commit();var a=first.get();var b=second.get();assertThat(java.util.List.of(a.statusCode(),b.statusCode())).containsExactlyInAnyOrder(201,409);assertProblem(a.statusCode()==409?a:b,409,"PLAN_LIMIT_EXCEEDED");
