        assertThat(disconnect(admin,relationship(bt,id),"Second disconnect",true).statusCode()).isEqualTo(200);assertThat(partner(bt,v).path("displayName").asString()).isEqualTo("Changed vendor");assertThat(owner.queryForObject("SELECT count(*) FROM partner_snapshot WHERE relationship_id=?",Integer.class,id)).isEqualTo(4);assertThat(owner.queryForObject("SELECT display_name FROM partner_snapshot WHERE relationship_id=? AND relationship_revision=2 AND organization_id=?",String.class,id,v)).isEqualTo(original.path("displayName").asString());
