    @Test void partnerConcurrentSelectionAndArchiveNeverSharesArchivedContact()throws Exception{
        String vendor=tradingVendor("RS"),buyer=businessAccount("RS","BUYER","OWNER"),one=nativeToken(vendor),two=nativeToken(addMember(organizationFor(vendor),"ADMIN")),bt=nativeToken(buyer);UUID v=organizationFor(vendor);seedTradingRelationship(v,organizationFor(buyer));var contact=createPartnerContact(one);var body=organizationBody(organization(one));body.put("partnerContactId",contact.path("id").asString());
        try(var c=java.sql.DriverManager.getConnection(DATABASE.getJdbcUrl(),DATABASE.getUsername(),DATABASE.getPassword())){c.setAutoCommit(false);try(var lock=c.prepareStatement("SELECT id FROM organization WHERE id=? FOR UPDATE")){lock.setObject(1,v);lock.execute();}
            var select=client.sendAsync(request("PUT","/organization",JSON.writeValueAsString(body),"Authorization","Bearer "+one),HttpResponse.BodyHandlers.ofString());var archive=client.sendAsync(request("POST","/organization/contacts/"+contact.path("id").asString()+"/archive",revisionBody(contact),"Authorization","Bearer "+two),HttpResponse.BodyHandlers.ofString());
            int pid;try(var q=c.createStatement();var rows=q.executeQuery("SELECT pg_backend_pid()")){rows.next();pid=rows.getInt(1);}boolean waiting=false;long deadline=System.nanoTime()+1_500_000_000L;
            while(System.nanoTime()<deadline){if(owner.queryForObject("WITH RECURSIVE blocked(pid) AS (SELECT pid FROM pg_stat_activity WHERE ?=ANY(pg_blocking_pids(pid)) UNION SELECT a.pid FROM pg_stat_activity a JOIN blocked b ON b.pid=ANY(pg_blocking_pids(a.pid))) SELECT count(*) FROM blocked b JOIN pg_stat_activity a ON a.pid=b.pid WHERE a.usename='http_runtime' AND a.wait_event_type='Lock'",Integer.class,pid)==2){waiting=true;break;}Thread.sleep(10);}assertThat(waiting).as("both contact selection and archive wait on the organization guard").isTrue();c.commit();
            assertThat(archive.get().statusCode()).isEqualTo(200);assertThat(select.get().statusCode()).isIn(200,422);
        }assertThat(organization(one).path("partnerContactId").isNull()).isTrue();assertThat(partner(bt,v).path("businessContact").isNull()).isTrue();assertThat(owner.queryForObject("SELECT state FROM business_contact WHERE id=?",String.class,UUID.fromString(contact.path("id").asString()))).isEqualTo("ARCHIVED");
    }

