    @Test void planAuditFailureRollsBackRequestResolutionAndAssignment()throws Exception{
        String vendor=tradingVendor("BA"),token=nativeToken(vendor),admin=nativeToken(account());UUID v=organizationFor(vendor);owner.execute("REVOKE INSERT ON audit_event FROM http_runtime");try{assertProblem(planRequest(token,planId("GROWTH")),503,"SERVICE_UNAVAILABLE");}finally{owner.execute("GRANT SELECT,INSERT ON audit_event TO http_runtime");}assertThat(owner.queryForObject("SELECT count(*) FROM plan_change_request WHERE vendor_id=?",Integer.class,v)).isZero();var pending=json(planRequest(token,planId("GROWTH")));var before=currentPlan(admin,v,true);
        owner.execute("REVOKE INSERT ON audit_event FROM http_runtime");try{assertProblem(resolvePlan(admin,pending,true,"Rollback"),503,"SERVICE_UNAVAILABLE");assertProblem(assignPlan(admin,v,before,planId("PRO"),"Rollback"),503,"SERVICE_UNAVAILABLE");}finally{owner.execute("GRANT SELECT,INSERT ON audit_event TO http_runtime");}assertThat(currentPlan(admin,v,true)).isEqualTo(before);assertThat(ownPlanRequests(token,"PENDING").path("items").get(0)).isEqualTo(pending);
        owner.execute("REVOKE UPDATE ON plan_change_request FROM http_runtime");try{assertProblem(assignPlan(admin,v,before,planId("PRO"),"Fail after assignment audit"),503,"SERVICE_UNAVAILABLE");}finally{owner.execute("GRANT UPDATE ON plan_change_request TO http_runtime");}assertThat(currentPlan(admin,v,true)).isEqualTo(before);assertThat(ownPlanRequests(token,"PENDING").path("items").get(0)).isEqualTo(pending);assertThat(owner.queryForObject("SELECT count(*) FROM audit_event WHERE resource_id=? AND action='PLAN_ASSIGNED'",Integer.class,v)).isZero();
    }
