    @Test void taxonomyAllKindsNormalizeScopeReplayRenameAndDelete()throws Exception{
        for(String country:java.util.List.of("RS","BA")){
            String email=tradingVendor(country),token=nativeToken(email);UUID vendor=organizationFor(email);
            for(String kind:java.util.List.of("categories","tags","units")){
                UUID id=taxonomyId();String body=JSON.writeValueAsString(Map.of("id",id,"name","  Kilo  "));var created=taxonomySend("POST",kind,"",body,token);assertThat(created.statusCode()).isEqualTo(201);var original=json(created);assertThat(original.path("name").asString()).isEqualTo("Kilo");assertThat(created.headers().firstValue("Location")).contains("/api/v1/catalogue/"+kind+"/"+id);
                assertThat(json(taxonomySend("POST",kind,"",body,token))).isEqualTo(original);assertProblem(taxonomyCreate(kind,"kIlO",token),409,"DUPLICATE_NAME");
                var renamed=json(taxonomyRename(kind,original,"Kilogram",token));assertThat(renamed.path("revision")).isNotEqualTo(original.path("revision"));assertThat(json(taxonomySend("POST",kind,"",body,token))).isEqualTo(original);
                assertProblem(taxonomyRename(kind,original,"Stale",token),409,"REVISION_CONFLICT");assertThat(json(taxonomyRename(kind,renamed,"Kilogram",token))).isEqualTo(renamed);
                assertProblem(taxonomySend("POST",kind,"",JSON.writeValueAsString(Map.of("id",id,"name","Different")),token),409,"IDEMPOTENCY_MISMATCH");
                for(int i=0;i<2;i++){assertThat(taxonomyDelete(kind,renamed,token).statusCode()).isEqualTo(204);}assertProblem(taxonomyRename(kind,renamed,"Restore",token),404,"NOT_FOUND");
                var list=json(taxonomySend("GET",kind,"?includeTotal=true",null,token));assertThat(list.path("total").asInt()).isZero();assertThat(list.path("items").size()).isZero();assertThat(json(taxonomySend("POST",kind,"",body,token))).isEqualTo(original);assertThat(taxonomyCreate(kind,"Kilogram",token).statusCode()).isEqualTo(201);
                assertThat(owner.queryForObject("SELECT count(*) FROM audit_event WHERE resource_id=? AND resource_type=?",Integer.class,id,kind.equals("categories")?"CATEGORY":kind.equals("tags")?"TAG":"UNIT")).isEqualTo(3);
            }
            assertThat(owner.queryForObject("SELECT count(*) FROM catalogue_taxonomy WHERE vendor_id=?",Integer.class,vendor)).isEqualTo(6);
        }
    }
