    private JsonNode reconPrepare(StockFixture f)throws Exception{var r=stockSend(f,"POST","/inventory/reconciliations",null);assertThat(r.statusCode()).as(r.body()).isEqualTo(201);assertThat(r.headers().firstValue("Location")).contains("/api/v1"+reconPath(json(r)));return json(r);}
    private static String reconPath(JsonNode preview){return "/inventory/reconciliations/"+preview.path("id").asString();}
    private JsonNode reconLines(StockFixture f,JsonNode p,String query)throws Exception{var r=stockSend(f,"GET",reconPath(p)+"/lines"+query,null);assertThat(r.statusCode()).as(r.body()).isEqualTo(200);return json(r);}
    private static tools.jackson.databind.node.ObjectNode reconRevisionBody(JsonNode p){var b=JSON.createObjectNode();b.put("expectedRevision",p.path("revision").asString());return b;}
    private static tools.jackson.databind.node.ObjectNode reconConfirm(JsonNode p){var b=reconRevisionBody(p);b.put("confirmAll",true);return b;}
    private static tools.jackson.databind.node.ObjectNode reconBatch(JsonNode p,JsonNode page){var b=reconRevisionBody(p);var a=b.putArray("lines");for(var line:page.path("items")){var n=JSON.createObjectNode();n.put("productId",line.path("productId").asString());n.put("expectedRevision",line.path("expectedRevision").asString());n.put("availableCount",line.path("availableCount").asInt());a.add(n);}return b;}
    private JsonNode reconAcknowledgeAll(StockFixture f,JsonNode p)throws Exception{var response=stockSend(f,"PUT",reconPath(p)+"/lines",reconBatch(p,reconLines(f,p,"")));assertThat(response.statusCode()).as(response.body()).isEqualTo(200);return json(response);}
    private JsonNode reconEnable(StockFixture f,JsonNode p)throws Exception{var response=stockSend(f,"POST",reconPath(p)+"/confirmation",reconConfirm(p));assertThat(response.statusCode()).as(response.body()).isEqualTo(200);return json(response);}
