    private AutoCloseable inventorySigningRotation(){
        var controller=app.getBean(com.narudzbine.identity.infrastructure.web.InventoryController.class);var fields=java.util.List.of("key","revisions","cursors","reconciliationCursors");var old=new java.util.HashMap<String,Object>();for(String field:fields){old.put(field,org.springframework.test.util.ReflectionTestUtils.getField(controller,field));}String name="synthetic-replay-rotation";byte[] rotated=new byte[32];new java.security.SecureRandom().nextBytes(rotated);var props=new java.util.HashMap<String,Object>();props.put("identity.http.revision-key",java.util.Base64.getEncoder().encodeToString(rotated));props.put("identity.http.replay-fingerprint-key",java.util.Base64.getEncoder().encodeToString((byte[])old.get("key")));app.getEnvironment().getPropertySources().addFirst(new org.springframework.core.env.MapPropertySource(name,props));try{var replacement=app.getAutowireCapableBeanFactory().createBean(com.narudzbine.identity.infrastructure.web.InventoryController.class);for(String field:fields){org.springframework.test.util.ReflectionTestUtils.setField(controller,field,org.springframework.test.util.ReflectionTestUtils.getField(replacement,field));}org.springframework.test.util.ReflectionTestUtils.setField(controller,"revisions",new com.narudzbine.shared.api.ResourceRevisions(rotated));}catch(RuntimeException e){app.getEnvironment().getPropertySources().remove(name);for(String field:fields){org.springframework.test.util.ReflectionTestUtils.setField(controller,field,old.get(field));}throw e;}return ()->{app.getEnvironment().getPropertySources().remove(name);for(String field:fields){org.springframework.test.util.ReflectionTestUtils.setField(controller,field,old.get(field));}};
    }
