    private void legacyStockDelta(StockFixture f,String key,int quantity,String reason)throws Exception{
        byte[] secret=(byte[])org.springframework.test.util.ReflectionTestUtils.getField(app.getBean(com.narudzbine.identity.infrastructure.web.InventoryController.class),"key");byte[] identity=legacyStockFingerprint(secret,"key",UUID.fromString(key)),payload=legacyStockFingerprint(secret,"DELTA",f.product(),null,quantity,reason);new TransactionTemplate(app.getBean(org.springframework.transaction.PlatformTransactionManager.class)).executeWithoutResult(status->{var sessions=app.getBean(com.narudzbine.identity.application.SessionService.class);var principal=sessions.authenticateForOrganizationWrite(f.token(),com.narudzbine.identity.api.SessionTransport.NATIVE);app.getBean(com.narudzbine.identity.api.BusinessAuthorization.class).require(principal.accountId(),f.vendor(),com.narudzbine.organizations.api.Country.BA,com.narudzbine.identity.api.BusinessCapability.EDIT_STOCK);var inventory=app.getBean(com.narudzbine.inventory.api.VendorInventory.class);inventory.lockReplay(principal.accountId(),"DELTA",identity);var item=inventory.adjust(principal.accountId(),f.vendor(),f.product(),quantity,reason);inventory.remember(principal.accountId(),"DELTA",identity,payload,item,null);});
    }
    private static byte[] legacyStockFingerprint(byte[] key,String domain,Object... values)throws Exception{var mac=javax.crypto.Mac.getInstance("HmacSHA256");mac.init(new javax.crypto.spec.SecretKeySpec(key,"HmacSHA256"));mac.update(("narudzbine/stock/"+domain+"/v1\0").getBytes(java.nio.charset.StandardCharsets.US_ASCII));return mac.doFinal(JSON.writeValueAsBytes(values));}

    @Test void replayRotationLegacyInvitationResendReconstructsOriginalRevision()throws Exception{
        String admin=nativeToken(account());var initial=json(setupInvite(admin,UUID.randomUUID()+"@example.com","BA","BUYER"));UUID id=UUID.fromString(initial.path("id").asString()),key=UUID.randomUUID();String expected=initial.path("revision").asString();var store=app.getBean(com.narudzbine.identity.application.SetupInvitationStore.class);byte[] random=new byte[32];new java.security.SecureRandom().nextBytes(random);String capability=java.util.Base64.getUrlEncoder().withoutPadding().encodeToString(random);byte[] hash=java.security.MessageDigest.getInstance("SHA-256").digest(capability.getBytes(java.nio.charset.StandardCharsets.US_ASCII));
        // Execute the genuine schema35 resend effects and old receipt format; never update an immutable receipt.
        new TransactionTemplate(app.getBean(org.springframework.transaction.PlatformTransactionManager.class)).executeWithoutResult(status->{var sessions=app.getBean(com.narudzbine.identity.application.SessionService.class);var principal=sessions.authenticate(admin,com.narudzbine.identity.api.SessionTransport.NATIVE);assertThat(principal.platformAdministrator()).isTrue();var jdbc=app.getBean(org.springframework.jdbc.core.JdbcTemplate.class);org.springframework.test.util.ReflectionTestUtils.invokeMethod(store,"lock",id);assertThat(jdbc.queryForObject("SELECT sender_id FROM setup_invitation WHERE id=?",UUID.class,id)).isEqualTo(principal.accountId());var now=CLOCK.instant();jdbc.update("UPDATE setup_invitation SET token_hash=?,generation=generation+1,revision=revision+1,expires_at=?,updated_at=? WHERE id=?",hash,java.sql.Timestamp.from(now.plusSeconds(604800)),java.sql.Timestamp.from(now),id);org.springframework.test.util.ReflectionTestUtils.invokeMethod(store,"invalidateProofs",id);Object changed=org.springframework.test.util.ReflectionTestUtils.invokeMethod(store,"read",id);org.springframework.test.util.ReflectionTestUtils.invokeMethod(store,"deliver",changed,capability,null);jdbc.update("INSERT INTO invitation_resend(sender_id,invitation_id,key,expected_revision,result_revision,result_generation,created_at,expires_at,result_expires_at) SELECT sender_id,id,?,?,revision,generation,?,?,? FROM setup_invitation WHERE id=?",key,expected,java.sql.Timestamp.from(now),java.sql.Timestamp.from(now.plusSeconds(604800)),java.sql.Timestamp.from(now.plusSeconds(604800)),id);app.getBean(com.narudzbine.audit.api.SetupAudit.class).setup(principal.accountId(),id,"SETUP_RESENT","Synthetic legacy resend");sessions.recordSuccessfulActivity(admin,com.narudzbine.identity.api.SessionTransport.NATIVE);});
        var original=json(send("GET","/invitations/"+id,null,"Authorization","Bearer "+admin));Object previous=org.springframework.test.util.ReflectionTestUtils.getField(store,"revisions");byte[] rotated=new byte[32];new java.security.SecureRandom().nextBytes(rotated);try{org.springframework.test.util.ReflectionTestUtils.setField(store,"revisions",new com.narudzbine.shared.api.ResourceRevisions(rotated));var replay=send("POST","/invitations/"+id+"/resends",JSON.writeValueAsString(Map.of("expectedRevision",expected)),"Authorization","Bearer "+admin,"Idempotency-Key",key.toString());assertThat(replay.statusCode()).as(replay.body()).isEqualTo(200);assertThat(json(replay)).isEqualTo(original);assertThat(owner.queryForObject("SELECT count(*) FROM setup_delivery WHERE invitation_id=? AND proof_id IS NULL",Integer.class,id)).isEqualTo(2);}finally{org.springframework.test.util.ReflectionTestUtils.setField(store,"revisions",previous);}
    }

    private JsonNode submissionDraft(ReviewFixture f)throws Exception{var b=draftBody(f.offer(),true);b.set("intent",reviewBody(f).path("intent").deepCopy());var response=draftCreate(f.offer(),b);assertThat(response.statusCode()).as(response.body()).isEqualTo(201);return json(response);}
    private JsonNode submissionReview(ReviewFixture f,JsonNode draft)throws Exception{var b=reviewBody(f);b.set("intent",draft.path("intent").deepCopy());b.put("draftId",draft.path("id").asString());b.put("draftRevision",draft.path("revision").asString());return reviewSaved(f,b);}
    private String submissionBody(JsonNode draft,JsonNode review){return JSON.writeValueAsString(java.util.Map.of("reviewId",review.path("id").asString(),"expectedRevision",draft.path("revision").asString()));}
    private HttpResponse<String> submissionSend(ReviewFixture f,JsonNode draft,JsonNode review)throws Exception{return send("POST","/drafts/"+draft.path("id").asString()+"/submission",submissionBody(draft,review),"Authorization","Bearer "+f.offer().buyerToken());}
