    @Test void draftSubmissionsCommittingEditDiscardRestrictionAndRevocationWinRace()throws Exception{
        for(String change:java.util.List.of("EDIT","DISCARD","RESTRICTION","REMOVAL")){var f=reviewFixture("BA");var d=submissionDraft(f);var r=submissionReview(f,d);String email=addMember(f.offer().buyer(),"STAFF"),token=nativeToken(email);UUID id=UUID.fromString(d.path("id").asString());try(var c=java.sql.DriverManager.getConnection(DATABASE.getJdbcUrl(),DATABASE.getUsername(),DATABASE.getPassword())){c.setAutoCommit(false);try(var q=c.prepareStatement("SELECT id FROM organization WHERE id IN (?,?) ORDER BY id FOR UPDATE")){q.setObject(1,f.offer().buyer());q.setObject(2,f.offer().stock().vendor());q.execute();}var pending=client.sendAsync(request("POST","/drafts/"+id+"/submission",submissionBody(d,r),"Authorization","Bearer "+token),HttpResponse.BodyHandlers.ofString());awaitRuntimeBlockedBy(c,"draft submission waits for committing change");String sql=switch(change){case "EDIT"->"UPDATE buyer_draft SET preparation=jsonb_set(preparation,'{note}','\"committed edit\"'),revision=revision+1 WHERE id=?";case "DISCARD"->"UPDATE buyer_draft SET state='DISCARDED',discarded_from_revision=revision,revision=revision+1 WHERE id=?";case "RESTRICTION"->"UPDATE organization SET staff_submission_restricted=true,revision=revision+1 WHERE id=?";default->"UPDATE account_identity SET state='DEACTIVATED' WHERE id=?";};try(var q=c.prepareStatement(sql)){q.setObject(1,switch(change){case "EDIT","DISCARD"->id;case "RESTRICTION"->f.offer().buyer();default->accountFor(email);});q.execute();}c.commit();assertProblem(pending.get(),change.equals("REMOVAL")?401:change.equals("RESTRICTION")?403:409,change.equals("REMOVAL")?"INVALID_SESSION":change.equals("RESTRICTION")?"FORBIDDEN":"REVISION_CONFLICT");assertThat(orderCount(f)).isZero();}}
    }
