    @Test void orderHistoryBothCountriesDirectDraftSnapshotsAndEventPrivacy()throws Exception{
        for(String country:java.util.List.of("RS","BA")){var f=reviewFixture(country);var one=historyOrder(f);var d=submissionDraft(f);var r=submissionReview(f,d);var two=json(submissionSend(f,d,r));var list=historyList(f.offer().buyerToken(),"");assertThat(list.path("items").size()).isEqualTo(2);assertThat(list.path("nextCursor").isNull()).isTrue();var ids=new java.util.HashSet<String>();for(var item:list.path("items")){ids.add(item.path("id").asString());assertThat(item).isEqualTo(orderRead(f.offer().buyerToken(),UUID.fromString(item.path("id").asString())));}assertThat(ids).containsExactlyInAnyOrder(one.path("id").asString(),two.path("id").asString());var vendor=historyList(f.offer().stock().token(),"");assertThat(vendor.path("items").size()).isEqualTo(2);for(var item:vendor.path("items")){assertThat(item.path("submittedByAccountId").isNull()).isTrue();assertThat(item.path("submittedByDisplayName").isNull()).isTrue();}
        var own=historyEvents(f.offer().buyerToken(),one,"");assertThat(own.statusCode()).as(own.body()).isEqualTo(200);var e=json(own).path("items").get(0);assertThat(json(own).path("items").size()).isEqualTo(1);assertThat(e.path("orderId")).isEqualTo(one.path("id"));assertThat(e.path("state").asString()).isEqualTo("AWAITING_ACCEPTANCE");assertThat(e.path("actorOrganizationId").asString()).isEqualTo(f.offer().buyer().toString());assertThat(e.path("ownActorAccountId")).isEqualTo(one.path("submittedByAccountId"));assertThat(e.path("ownActorDisplayName")).isEqualTo(one.path("submittedByDisplayName"));for(String field:java.util.List.of("stageId","reason","stageName","previousState","previousStageId","previousStageName","stageConfigurationRevision")){assertThat(e.path(field).isNull()).as(field).isTrue();}var other=historyEvents(f.offer().stock().token(),one,"");assertThat(other.statusCode()).isEqualTo(200);assertThat(json(other).path("items").get(0).path("ownActorAccountId").isNull()).isTrue();assertThat(json(other).path("items").get(0).path("ownActorDisplayName").isNull()).isTrue();assertThat(json(other).path("nextCursor").isNull()).isTrue();}
    }
