    @Test void orderHistoryStableEqualTimePaginationSharedCursorAndConcurrentNewOrder()throws Exception{
        var f=reviewFixture("RS");var review=reviewSaved(f,reviewBody(f));var original=new java.util.ArrayList<String>();for(int i=0;i<5;i++){var r=orderSend(f,review,UUID.randomUUID().toString());assertThat(r.statusCode()).as(r.body()).isEqualTo(201);original.add(json(r).path("id").asString());}original.sort(String::compareTo);var first=historyList(f.offer().buyerToken(),"?size=2");assertThat(first.path("items").get(0).path("id").asString()).isEqualTo(original.get(0));assertThat(first.path("items").get(1).path("id").asString()).isEqualTo(original.get(1));String cursor=first.path("nextCursor").asString(),staff=nativeToken(addMember(f.offer().buyer(),"STAFF"));CLOCK.advance(1);var fresh=reviewSaved(f,reviewBody(f));HttpResponse<String> continuation;
        try(var c=java.sql.DriverManager.getConnection(DATABASE.getJdbcUrl(),DATABASE.getUsername(),DATABASE.getPassword())){c.setAutoCommit(false);try(var q=c.prepareStatement("SELECT id FROM organization WHERE id IN (?,?) ORDER BY id FOR UPDATE")){q.setObject(1,f.offer().buyer());q.setObject(2,f.offer().stock().vendor());q.execute();}var a=client.sendAsync(request("GET","/orders?size=2&cursor="+cursor,null,"Authorization","Bearer "+staff),HttpResponse.BodyHandlers.ofString());var b=client.sendAsync(request("POST","/orders",orderBody(fresh),"Authorization","Bearer "+f.offer().buyerToken(),"Idempotency-Key",UUID.randomUUID().toString()),HttpResponse.BodyHandlers.ofString());awaitPlanWaiters(c);c.commit();continuation=a.get();assertThat(continuation.statusCode()).as(continuation.body()).isEqualTo(200);assertThat(b.get().statusCode()).as(b.get().body()).isEqualTo(201);}
        var seen=new java.util.ArrayList<String>();for(var i:first.path("items")){seen.add(i.path("id").asString());}var page=json(continuation);for(;;){for(var item:page.path("items")){seen.add(item.path("id").asString());}if(page.path("nextCursor").isNull()){break;}page=historyList(staff,"?size=2&cursor="+page.path("nextCursor").asString());}assertThat(seen).containsExactlyElementsOf(original);assertThat(historyList(staff,"?size=100").path("items").size()).isEqualTo(6);
    }
