    private HttpResponse<String> reorderSend(String token,JsonNode order)throws Exception{return send("GET","/orders/"+order.path("id").asString()+"/reorder-preview",null,"Authorization","Bearer "+token);}
    private JsonNode reorderPreview(String token,JsonNode order)throws Exception{var r=reorderSend(token,order);assertThat(r.statusCode()).as(r.body()).isEqualTo(200);return json(r);}
    private java.util.Map<String,Object> reorderEffects(ReviewFixture f){var result=new java.util.LinkedHashMap<String,Object>();for(String table:java.util.List.of("purchase_order","purchase_order_line","purchase_order_event","order_stock_obligation","order_submission_replay","draft_order_submission","buyer_draft","buyer_draft_line","draft_event","draft_creation","order_review","order_number_counter","stock_event","audit_event","order_notice","order_delivery")){result.put(table,owner.queryForObject("SELECT count(*) FROM "+table,Long.class));}result.put("balance",owner.queryForMap("SELECT * FROM stock_balance WHERE product_id=?",f.offer().stock().product()));result.put("product",owner.queryForMap("SELECT * FROM catalogue_product WHERE id=?",f.offer().stock().product()));result.put("tracking",owner.queryForMap("SELECT * FROM inventory_control WHERE vendor_id=?",f.offer().stock().vendor()));return result;}
