        for(String change:java.util.List.of("PRICE","DISCONNECT","REMOVAL")){var f=reviewFixture("RS");var order=historyOrder(f);String email=addMember(f.offer().buyer(),"STAFF"),token=nativeToken(email);try(var c=java.sql.DriverManager.getConnection(DATABASE.getJdbcUrl(),DATABASE.getUsername(),DATABASE.getPassword())){c.setAutoCommit(false);try(var q=c.prepareStatement("SELECT id FROM organization WHERE id IN (?,?) ORDER BY id FOR UPDATE")){q.setObject(1,f.offer().buyer());q.setObject(2,f.offer().stock().vendor());q.execute();}var pending=client.sendAsync(request("GET","/orders/"+order.path("id").asString()+"/reorder-preview",null,"Authorization","Bearer "+token),HttpResponse.BodyHandlers.ofString());awaitRuntimeBlockedBy(c,"reorder waits for committing price or authority");String sql=switch(change){case "PRICE"->"UPDATE product_pricing SET base_price=12,revision=revision+1 WHERE product_id=?";case "DISCONNECT"->"UPDATE trading_relationship SET state='DISCONNECTED',disconnected_reason='Synthetic',revision=revision+1 WHERE id=?";default->"UPDATE account_identity SET state='DEACTIVATED' WHERE id=?";};try(var q=c.prepareStatement(sql)){q.setObject(1,switch(change){case "PRICE"->f.offer().stock().product();case "DISCONNECT"->f.offer().relationship();default->accountFor(email);});q.execute();}c.commit();var result=pending.get();if(change.equals("REMOVAL")){assertProblem(result,401,"INVALID_SESSION");}else{assertThat(result.statusCode()).as(result.body()).isEqualTo(200);var l=json(result).path("lines").get(0);if(change.equals("PRICE")){assertThat(l.path("currentOffer").path("effectivePrice").path("finalUnitPrice").asString()).isEqualTo("12.00");}else{assertThat(l.path("currentOffer").isNull()).isTrue();}}assertThat(orderCount(f)).isEqualTo(1);}}
