    private HttpResponse<String> orderResponse(String token,JsonNode order,boolean accepted,JsonNode location,String reason)throws Exception{var b=JSON.createObjectNode();b.put("expectedRevision",order.path("revision").asString());if(accepted){if(location==null){b.putNull("fulfillmentLocationId");}else{b.put("fulfillmentLocationId",location.path("id").asString());}}else{b.put("reason",reason);}return send("POST","/orders/"+order.path("id").asString()+(accepted?"/acceptance":"/rejection"),JSON.writeValueAsString(b),"Authorization","Bearer "+token);}
