    private JsonNode requestAccepted(ReviewFixture f)throws Exception{var r=orderResponse(f.offer().stock().token(),historyOrder(f),true,null,null);assertThat(r.statusCode()).as(r.body()).isEqualTo(200);return json(r);}
    private HttpResponse<String> cancellationRequest(String token,JsonNode order,String reason)throws Exception{return send("POST","/orders/"+order.path("id").asString()+"/cancellation-requests",cancellationBody(order,reason),"Authorization","Bearer "+token);}
    private JsonNode requestSaved(ReviewFixture f,JsonNode order)throws Exception{var r=cancellationRequest(f.offer().buyerToken(),order,"Please cancel");assertThat(r.statusCode()).as(r.body()).isEqualTo(201);assertThat(r.headers().firstValue("Location")).contains("/api/v1/orders/"+order.path("id").asString()+"/cancellation-requests/"+json(r).path("id").asString());return json(r);}
    private String requestPath(JsonNode order,JsonNode request){return "/orders/"+order.path("id").asString()+"/cancellation-requests/"+request.path("id").asString();}
    private String requestResolutionBody(JsonNode request,String reason){var b=JSON.createObjectNode().put("expectedRevision",request.path("revision").asString());if(reason!=null){b.put("reason",reason);}return JSON.writeValueAsString(b);}
    private HttpResponse<String> requestAction(String token,JsonNode order,JsonNode request,String action,String reason)throws Exception{return send("POST",requestPath(order,request)+"/"+action,requestResolutionBody(request,reason),"Authorization","Bearer "+token);}
    private JsonNode requestRead(String token,JsonNode order,JsonNode request)throws Exception{var r=send("GET",requestPath(order,request),null,"Authorization","Bearer "+token);assertThat(r.statusCode()).as(r.body()).isEqualTo(200);return json(r);}
