blem(send("POST",path,requestResolutionBody(request,null),"Cookie",cookie,"Origin","https://app.example"),403,"CSRF_REJECTED");assertThat(send("POST",path,requestResolutionBody(request,null),"Cookie",cookie,"Origin","https://app.example","X-CSRF-Token",csrf).statusCode()).isEqualTo(200);assertProblem(send("POST",path,requestResolutionBody(request,null),"Cookie",cookie,"Origin","https://app.example"),403,"CSRF_REJECTED");
