        var f=reviewFixture("BA");String token=f.offer().stock().token();UUID id=taxonomyId();var created=json(stageCreate(token,id,"Packing"));var renamed=stageChange(token,created,"Preparing",false);assertThat(renamed.statusCode()).isEqualTo(200);var order=requestAccepted(f);var moved=assigned(token,order,json(renamed));var signer=app.getBean(com.narudzbine.shared.api.ResourceRevisions.class);Object original=org.springframework.test.util.ReflectionTestUtils.getField(signer,"key");byte[] key=new byte[32];new java.security.SecureRandom().nextBytes(key);try{org.springframework.test.util.ReflectionTestUtils.setField(signer,"key",key);assertThat(json(stageCreate(token,id,"Packing"))).isEqualTo(created);assertThat(json(stageChange(token,created,"Preparing",false))).isEqualTo(json(renamed));assertThat(assigned(token,order,json(renamed))).isEqualTo(moved);}finally{org.springframework.test.util.ReflectionTestUtils.setField(signer,"key",original);}CLOCK.advance(604801);assertThat(assigned(nativeToken(f.offer().stock().email()),order,json(renamed))).isEqualTo(moved);
