        for(String table:java.util.List.of("order_stage_configuration","order_stage","order_stage_creation","audit_event")){var f=reviewFixture("RS");String token=f.offer().stock().token();var before=stageList(token);UUID id=taxonomyId();owner.execute("REVOKE INSERT ON "+table+" FROM http_runtime");try{assertProblem(stageCreate(token,id,"Packing"),503,"SERVICE_UNAVAILABLE");}finally{owner.execute("GRANT INSERT ON "+table+" TO http_runtime");}assertThat(stageList(token)).isEqualTo(before);assertThat(stageCreate(token,id,"Packing").statusCode()).isEqualTo(201);}var f=reviewFixture("BA");String token=f.offer().stock().token();var stage=stageSaved(token,"Packing");var before=stageList(token);owner.execute("REVOKE INSERT ON order_stage_mutation FROM http_runtime");try{assertProblem(stageChange(token,stage,"Preparing",false),503,"SERVICE_UNAVAILABLE");}finally{owner.execute("GRANT INSERT ON order_stage_mutation TO http_runtime");}assertThat(stageList(token)).isEqualTo(before);
