    @Test void dispatchDuplicateRacesAndCancellationOrRequestContendersSerialize()throws Exception{
        for(String competitor:java.util.List.of("dispatch","cancel","request")){var f=reviewFixture("RS");var stock=f.offer().stock();reconEnable(stock,reconAcknowledgeAll(stock,reconPrepare(stock)));stockSet(stock,stockGet(stock),6,null);var order=requestAccepted(f);String path="/orders/"+order.path("id").asString();var a=client.sendAsync(request("POST",path+"/dispatch",progressBody(order),"Authorization","Bearer "+stock.token()),HttpResponse.BodyHandlers.ofString());var b=client.sendAsync(request("POST",path+(competitor.equals("dispatch")?"/dispatch":competitor.equals("cancel")?"/cancellation":"/cancellation-requests"),competitor.equals("dispatch")?progressBody(order):cancellationBody(order,"Change"),"Authorization","Bearer "+(competitor.equals("request")?f.offer().buyerToken():stock.token())),HttpResponse.BodyHandlers.ofString());var ra=a.get();var rb=b.get();if(competitor.equals("dispatch")){assertThat(ra.statusCode()).as(ra.body()).isEqualTo(200);assertThat(json(rb)).isEqualTo(json(ra));}else{assertThat(java.util.List.of(ra.statusCode(),rb.statusCode())).contains(409);assertThat(java.util.List.of(ra.statusCode(),rb.statusCode())).containsAnyOf(200,201);}UUID id=UUID.fromString(order.path("id").asString());String state=orderRead(stock.token(),id).path("state").asString();if(state.equals("DISPATCHED")){assertThat(stockGet(stock).path("availableCount").asInt()).isEqualTo(4);assertThat(stockGet(stock).path("cancellationCreditQuantity").asInt()).isZero();assertThat(owner.queryForObject("SELECT count(*) FROM order_pending_cancellation WHERE order_id=?",Integer.class,id)).isZero();}else if(state.equals("CANCELLED")){assertThat(stockGet(stock).path("availableCount").asInt()).isEqualTo(6);}else{assertThat(stockGet(stock).path("cancellationCreditQuantity").asInt()).isEqualTo(2);assertThat(owner.queryForObject("SELECT count(*) FROM order_stock_release WHERE order_id=?",Integer.class,id)).isZero();}}
    }
