    private HttpResponse<String> messageSend(String token,JsonNode order,String text,String key)throws Exception{return send("POST","/orders/"+order.path("id").asString()+"/messages",JSON.writeValueAsString(Map.of("text",text)),"Authorization","Bearer "+token,"Idempotency-Key",key);}
    private JsonNode messageSaved(String token,JsonNode order,String text)throws Exception{var r=messageSend(token,order,text,UUID.randomUUID().toString());assertThat(r.statusCode()).as(r.body()).isEqualTo(201);return json(r);}
    private HttpResponse<String> messageList(String token,JsonNode order,String query)throws Exception{return send("GET","/orders/"+order.path("id").asString()+"/messages"+query,null,"Authorization","Bearer "+token);}
