    private JsonNode replacementSource(ReviewFixture f)throws Exception{var order=historyOrder(f);var r=cancelOrder(f.offer().buyerToken(),order,"Replace this order");assertThat(r.statusCode()).as(r.body()).isEqualTo(200);return json(r);}
    private tools.jackson.databind.node.ObjectNode replacementBody(ReviewFixture f,JsonNode source){var b=reviewBody(f);b.path("intent").asObject().put("replacementForOrderId",source.path("id").asString());return b;}
    private JsonNode replacementDraft(ReviewFixture f,JsonNode source)throws Exception{var b=draftBody(f.offer(),true);b.set("intent",replacementBody(f,source).path("intent").deepCopy());var r=draftCreate(f.offer(),b);assertThat(r.statusCode()).as(r.body()).isEqualTo(201);return json(r);}
    private JsonNode replacementSaved(ReviewFixture f,JsonNode source)throws Exception{var r=orderSend(f,reviewSaved(f,replacementBody(f,source)),UUID.randomUUID().toString());assertThat(r.statusCode()).as(r.body()).isEqualTo(201);return json(r);}
    @Test void replacementsBothCountriesDirectSubmissionFreezesExplicitSourceAndDeductsNormally()throws Exception{
        for(String country:java.util.List.of("RS","BA")){var f=reviewFixture(country);var stock=f.offer().stock();reconEnable(stock,reconAcknowledgeAll(stock,reconPrepare(stock)));stockSet(stock,stockGet(stock),10,null);var source=replacementSource(f);assertThat(stockGet(stock).path("availableCount").asInt()).isEqualTo(10);var review=reviewSaved(f,replacementBody(f,source));assertThat(owner.queryForObject("SELECT count(*) FROM order_replacement WHERE predecessor_id=?",Integer.class,UUID.fromString(source.path("id").asString()))).isZero();var r=orderSend(f,review,UUID.randomUUID().toString());assertThat(r.statusCode()).as(r.body()).isEqualTo(201);var child=json(r);assertThat(child.path("replacementForOrderId")).isEqualTo(source.path("id"));assertThat(child.path("state").asString()).isEqualTo("AWAITING_ACCEPTANCE");assertThat(child.path("id")).isNotEqualTo(source.path("id"));assertThat(stockGet(stock).path("availableCount").asInt()).isEqualTo(8);assertThat(stockGet(stock).path("cancellationCreditQuantity").asInt()).isEqualTo(2);assertThat(orderRead(f.offer().buyerToken(),UUID.fromString(source.path("id").asString()))).isEqualTo(source);assertProblem(reviewSend(f,replacementBody(f,source)),409,"INVALID_STATE");}
    }
