        for(boolean draft:java.util.List.of(false,true)){var f=reviewFixture("BA");var source=replacementSource(f);var directReview=reviewSaved(f,replacementBody(f,source));var saved=draft?replacementDraft(f,source):null;var other=draft?submissionReview(f,saved):reviewSaved(f,replacementBody(f,source));var a=client.sendAsync(request("POST","/orders",orderBody(directReview),"Authorization","Bearer "+f.offer().buyerToken(),"Idempotency-Key",UUID.randomUUID().toString()),HttpResponse.BodyHandlers.ofString());var b=client.sendAsync(draft?request("POST","/drafts/"+saved.path("id").asString()+"/submission",submissionBody(saved,other),"Authorization","Bearer "+f.offer().buyerToken()):request("POST","/orders",orderBody(other),"Authorization","Bearer "+f.offer().buyerToken(),"Idempotency-Key",UUID.randomUUID().toString()),HttpResponse.BodyHandlers.ofString());var ra=a.get();var rb=b.get();assertThat(java.util.List.of(ra.statusCode(),rb.statusCode())).contains(409);assertThat(java.util.List.of(ra.statusCode(),rb.statusCode())).containsAnyOf(200,201);var conflict=ra.statusCode()==409?ra:rb;assertProblem(conflict,409,"TERMS_CHANGED");assertThat(json(conflict).path("unavailableLines").get(0).path("productId").isNull()).isTrue();assertThat(orderCount(f)).isEqualTo(2);assertThat(owner.queryForObject("SELECT count(*) FROM order_replacement WHERE predecessor_id=?",Integer.class,UUID.fromString(source.path("id").asString()))).isEqualTo(1);}
