    @Test void replacementsSecondLineFailureRollsBackEarlierDeductionAndSourceClaim()throws Exception{
        var f=reviewFixture("BA");var stock=f.offer().stock();var item=json(productCreate(stock.token(),"replacement-second-line","Second replacement line"));UUID second=UUID.fromString(item.path("id").asString());var values=productBody(item);values.put("unitId",productGet(stock.token(),stock.product()).path("unitId").asString());assertThat(productUpdate(stock.token(),item,values).statusCode()).isEqualTo(200);assertThat(pricingPut(stock.token(),second,pricingBody(pricingGet(stock.token(),second),"12",java.util.List.of())).statusCode()).isEqualTo(200);var other=new StockFixture(stock.email(),stock.token(),stock.vendor(),second);assertThat(publication(other,true,productGet(stock.token(),second)).statusCode()).isEqualTo(200);reconEnable(stock,reconAcknowledgeAll(stock,reconPrepare(stock)));stockSet(stock,stockGet(stock),5,null);stockSet(other,stockGet(other),6,null);var source=replacementSource(f);var body=replacementBody(f,source);body.path("intent").path("lines").asArray().addObject().put("productId",second.toString()).put("quantity",3);var review=reviewSaved(f,body);String key=UUID.randomUUID().toString();var one=stockGet(stock);var two=stockGet(other);owner.execute("CREATE FUNCTION fail_synthetic_replacement_line() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.product_id='"+java.util.stream.Stream.of(stock.product(),second).max(java.util.Comparator.comparing(UUID::toString)).orElseThrow()+"'::uuid THEN RAISE EXCEPTION 'Synthetic second-line replacement failure';END IF;RETURN NEW;END $$");owner.execute("CREATE TRIGGER tr_synthetic_replacement_line BEFORE INSERT ON order_stock_obligation FOR EACH ROW EXECUTE FUNCTION fail_synthetic_replacement_line()");try{assertProblem(orderSend(f,review,key),503,"SERVICE_UNAVAILABLE");}finally{owner.execute("DROP TRIGGER tr_synthetic_replacement_line ON order_stock_obligation");owner.execute("DROP FUNCTION fail_synthetic_replacement_line()");}assertThat(stockGet(stock)).isEqualTo(one);assertThat(stockGet(other)).isEqualTo(two);assertThat(orderCount(f)).isEqualTo(1);assertThat(owner.queryForObject("SELECT count(*) FROM order_replacement WHERE predecessor_id=?",Integer.class,UUID.fromString(source.path("id").asString()))).isZero();assertThat(orderSend(f,review,key).statusCode()).isEqualTo(201);assertThat(stockGet(stock).path("availableCount").asInt()).isEqualTo(3);assertThat(stockGet(other).path("availableCount").asInt()).isEqualTo(3);
    }

    private HttpRequest csvRequest(String token,byte[] body,String type,String... extra){var b=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/v1/catalogue/import-previews")).timeout(java.time.Duration.ofSeconds(30)).header("Authorization","Bearer "+token).header("Content-Type",type);if(extra.length>0){b.headers(extra);}return b.POST(HttpRequest.BodyPublishers.ofByteArray(body)).build();}
    private HttpResponse<String> csvUpload(String token,String text)throws Exception{return client.send(csvRequest(token,text.getBytes(java.nio.charset.StandardCharsets.UTF_8),"text/csv; charset=UTF-8"),HttpResponse.BodyHandlers.ofString());}
    private JsonNode csvSaved(String token,String text)throws Exception{var r=csvUpload(token,text);assertThat(r.statusCode()).as(r.body()).isEqualTo(201);return json(r);}
    private HttpResponse<String> csvConfirm(String token,JsonNode p)throws Exception{return send("POST","/catalogue/import-previews/"+p.path("id").asString()+"/confirmation",revisionBody(p),"Authorization","Bearer "+token);}
    private HttpResponse<String> csvGet(String token,JsonNode p)throws Exception{return send("GET","/catalogue/import-previews/"+p.path("id").asString(),null,"Authorization","Bearer "+token);}
    private long csvProductCount(UUID vendor){return owner.queryForObject("SELECT count(*) FROM catalogue_product_identity WHERE vendor_id=?",Long.class,vendor);}



    /** Complete only this test's synthetic legacy claim using the actual cleanup worker/provider stub. */
    private void drainSyntheticProcessedClaim(UUID id){
        owner.update("INSERT INTO media_cleanup_event(id,asset_id,kind,occurred_at) SELECT ?,id,'CLAIMED',cleanup_claimed_at FROM media_asset WHERE id=? AND cleanup_claimed_at IS NOT NULL ON CONFLICT(asset_id,kind) DO NOTHING",uploadId(),id);
        var drainClock=Clock.fixed(CLOCK.instant().plusSeconds(86400),ZoneOffset.UTC);
        var maintenance=new com.narudzbine.media.application.ProcessedMaintenance(owner,QUARANTINE,drainClock,app.getBean(com.narudzbine.shared.api.UuidGenerator.class),new org.springframework.jdbc.datasource.DataSourceTransactionManager(fixtureSource));
        assertThat(maintenance.clean(id)).isTrue();assertThat(owner.queryForObject("SELECT state FROM media_asset WHERE id=?",String.class,id)).isEqualTo("DELETED");
        assertThat(owner.queryForObject("SELECT completed_at IS NOT NULL FROM media_disposal_claim WHERE asset_id=? AND kind='PROCESSED'",Boolean.class,id)).isTrue();
    }
    private String processedKey(UUID vendor,UUID id){return "processed/"+vendor+"/"+id;}
    private byte[] processedBytes()throws Exception{return java.nio.file.Files.readAllBytes(java.nio.file.Path.of("src/test/resources/media/alpha.png"));}
    private UUID processedAsset(UUID vendor)throws Exception{
        UUID id=uploadId();byte[] body=processedBytes();byte[] sha=java.security.MessageDigest.getInstance("SHA-256").digest(body);var at=java.sql.Timestamp.from(CLOCK.instant());
        owner.update("INSERT INTO media_asset(id,vendor_id,state,media_type,processed_key,processed_sha256,processed_bytes,width,height,created_at,ready_at,unreferenced_at) VALUES (?,?,'READY','image/png',?,?,?,64,32,?,?,?)",id,vendor,processedKey(vendor,id),sha,body.length,at,at,at);
        QUARANTINE.objects.put(processedKey(vendor,id),body);return id;
    }
    private HttpResponse<byte[]> imageGet(String token,UUID id,String... headers)throws Exception{
        return client.send(request("GET","/media/assets/"+id+"/content",null,java.util.stream.Stream.concat(java.util.stream.Stream.of("Authorization","Bearer "+token),java.util.Arrays.stream(headers)).toArray(String[]::new)),HttpResponse.BodyHandlers.ofByteArray());
    }
