        var f=stockFixture("RS");UUID id=processedAsset(f.vendor());var login=browserLogin(f.email());var r=send("GET","/media/assets/"+id+"/content",null,"Cookie",cookie(login,"__Host-narudzbine_session"),"Origin","https://app.example");assertThat(r.statusCode()).isEqualTo(200);
