    @Test void imageDeliveryFourInFlightLimitReleasesAfterCompletion()throws Exception{
        var f=stockFixture("RS");var entered=new java.util.concurrent.CountDownLatch(4);var release=new java.util.concurrent.CountDownLatch(1);var responses=new java.util.ArrayList<java.util.concurrent.CompletableFuture<HttpResponse<byte[]>>>();
        try{for(int i=0;i<4;i++){UUID id=processedAsset(f.vendor());QUARANTINE.hooks.put(processedKey(f.vendor(),id),()->{entered.countDown();try{if(!release.await(10,java.util.concurrent.TimeUnit.SECONDS))throw new AssertionError("download barrier timed out");}catch(InterruptedException e){throw new IllegalStateException(e);}});responses.add(client.sendAsync(request("GET","/media/assets/"+id+"/content",null,"Authorization","Bearer "+f.token()),HttpResponse.BodyHandlers.ofByteArray()));}assertThat(entered.await(10,java.util.concurrent.TimeUnit.SECONDS)).isTrue();UUID extra=processedAsset(f.vendor());assertThat(imageGet(f.token(),extra).statusCode()).isEqualTo(429);}finally{release.countDown();}for(var r:responses){assertThat(r.get().statusCode()).isEqualTo(200);}assertThat(imageGet(f.token(),processedAsset(f.vendor())).statusCode()).isEqualTo(200);
    }

