    private UUID deliveryJob(String kind,UUID resource,String channel,UUID account){return owner.queryForObject("SELECT j.id FROM external_job j JOIN external_delivery_source s ON s.kind=j.source_kind AND s.id=j.source_id WHERE s.kind=? AND s.resource_id=? AND j.channel=? AND s.account_id=? ORDER BY j.created_at,j.id LIMIT 1",UUID.class,kind,resource,channel,account);}
