    private void deliveryEnable(String token)throws Exception{var p=inboxPreferences(token);var b=JSON.createObjectNode().put("expectedRevision",p.path("revision").asString());var events=b.putArray("events");for(var e:com.narudzbine.notifications.api.Inbox.Event.values())events.addObject().put("event",e.name()).put("inApp",true).put("email",true).put("push",true);assertThat(send("PUT","/me/notification-preferences",b.toString(),"Authorization","Bearer "+token).statusCode()).isEqualTo(200);}
    private void deliveryUseVerification(DeliveryPush push){DEVICES.delegate=new com.narudzbine.identity.application.PushDeviceVerification(app.getBean(JdbcTemplate.class),CLOCK,app.getBean(com.narudzbine.shared.api.UuidGenerator.class),app.getBean(com.narudzbine.organizations.api.MembershipAccess.class),push,app.getBean(org.springframework.transaction.PlatformTransactionManager.class));}
    private HttpResponse<String> deliveryCompleteDevice(String token,UUID install,String push,JsonNode challenge,String code)throws Exception{var body=JSON.readTree(deviceBody(install,"WEB",push));((tools.jackson.databind.node.ObjectNode)body).put("verificationId",challenge.path("id").asString()).put("verificationCode",code);return send("POST","/me/devices",body.toString(),"Authorization","Bearer "+token);}
    private HttpResponse<String> deliveryCallback(UUID reference,String event,String id,boolean valid)throws Exception{String body=JSON.writeValueAsString(Map.of("type",event,"created_at",CLOCK.instant().toString(),"data",Map.of("email_id",reference.toString())));String timestamp=Long.toString(CLOCK.instant().getEpochSecond());String key=app.getEnvironment().getProperty("notifications.email-webhook.secret");var mac=javax.crypto.Mac.getInstance("HmacSHA256");mac.init(new javax.crypto.spec.SecretKeySpec(Base64.getDecoder().decode(key.substring(6)),"HmacSHA256"));String signature="v1,"+Base64.getEncoder().encodeToString(mac.doFinal((id+"."+timestamp+"."+body).getBytes(java.nio.charset.StandardCharsets.UTF_8)));return send("POST","/provider-callbacks/email",body,"svix-id",id,"svix-timestamp",timestamp,"svix-signature",valid?signature:"v1,"+Base64.getEncoder().encodeToString(new byte[32]));}
