    static final class DeliveryEmail implements com.narudzbine.notifications.api.ProviderDelivery.Email {
        final java.util.List<UUID> ids=new java.util.concurrent.CopyOnWriteArrayList<>();final java.util.List<com.narudzbine.notifications.api.ProviderDelivery.Mail> mail=new java.util.concurrent.CopyOnWriteArrayList<>();final Map<UUID,UUID> references=new ConcurrentHashMap<>();com.narudzbine.notifications.api.ProviderDelivery.Status result=com.narudzbine.notifications.api.ProviderDelivery.Status.ACCEPTED;Runnable before=()->{};
        public com.narudzbine.notifications.api.ProviderDelivery.Result send(UUID id,com.narudzbine.notifications.api.ProviderDelivery.Mail content){assertThat(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive()).isFalse();ids.add(id);mail.add(content);var outcome=result;before.run();return new com.narudzbine.notifications.api.ProviderDelivery.Result(outcome,outcome==com.narudzbine.notifications.api.ProviderDelivery.Status.ACCEPTED?references.computeIfAbsent(id,k->UUID.randomUUID()).toString():null,0);}
    }
    static final class DeliveryPush implements com.narudzbine.notifications.api.ProviderDelivery.Push {
        final java.util.List<String> tokens=new java.util.concurrent.CopyOnWriteArrayList<>();final java.util.List<Map<String,String>> data=new java.util.concurrent.CopyOnWriteArrayList<>();com.narudzbine.notifications.api.ProviderDelivery.Status result=com.narudzbine.notifications.api.ProviderDelivery.Status.ACCEPTED;Runnable before=()->{};
        public String environment(){return "synthetic";}public String projectId(){return "synthetic-project";}
        public com.narudzbine.notifications.api.ProviderDelivery.Result send(String token,Map<String,String> value){assertThat(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive()).isFalse();tokens.add(token);data.add(value);before.run();return new com.narudzbine.notifications.api.ProviderDelivery.Result(result,result==com.narudzbine.notifications.api.ProviderDelivery.Status.ACCEPTED?"projects/synthetic-project/messages/"+UUID.randomUUID():null,0);}
    }
    private HttpResponse<String> deviceRegister(String bearer,UUID installation,String platform,String push)throws Exception {
        return send("POST","/me/devices",deviceBody(installation,platform,push),"Authorization","Bearer "+bearer);
    }
    private static String deviceBody(UUID installation,String platform,String push){return JSON.writeValueAsString(Map.of("installationId",installation.toString(),"platform",platform,"pushToken",push));}
    private JsonNode devicePage(String token,String query)throws Exception {var r=send("GET","/me/devices"+query,null,"Authorization","Bearer "+token);assertThat(r.statusCode()).as(r.body()).isEqualTo(200);return json(r);}
    private JsonNode deviceSaved(String token,UUID installation,String platform,String push)throws Exception {var r=deviceRegister(token,installation,platform,push);assertThat(r.statusCode()).as(r.body()).isEqualTo(201);assertThat(r.headers().firstValue("Location")).contains("/api/v1/me/devices/"+json(r).path("id").asString());return json(r);}
    private static String pushToken(){return "synthetic-"+UUID.randomUUID();}
    @Test void devicesNaturalRetryPreservesIdRevisionAndDoesNotExposeToken()throws Exception {
        for(String email:java.util.List.of(businessAccount("RS","VENDOR","STAFF"),businessAccount("BA","BUYER","STAFF"),account())){
            String token=nativeToken(email),push=pushToken();UUID installation=UUID.randomUUID();var first=deviceSaved(token,installation,"ANDROID",push);assertThat(deviceSaved(token,installation,"ANDROID",push)).isEqualTo(first);
            var page=devicePage(token,"?includeTotal=true");assertThat(page.path("total").asInt()).isEqualTo(1);assertThat(page.path("items").get(0)).isEqualTo(first);assertThat(page.toString()).doesNotContain(push,"tokenSha256","sessionId","accountId");assertThat(page.path("items").get(0).path("enabled").asBoolean()).isTrue();
            byte[] envelope=owner.queryForObject("SELECT token_envelope FROM push_device WHERE id=?",byte[].class,UUID.fromString(first.path("id").asString()));assertThat(new String(envelope,java.nio.charset.StandardCharsets.ISO_8859_1)).doesNotContain(push);
        }
    }
