    static final class FakeDeviceVerification implements com.narudzbine.identity.api.DeviceVerification {
        String mode="OK";Runnable before=()->{};com.narudzbine.identity.api.DeviceVerification delegate;
        void reset(){mode="OK";before=()->{};delegate=null;}
        public Outcome verifyOrChallenge(Request request,UUID id,String code){return delegate==null?com.narudzbine.identity.api.DeviceVerification.super.verifyOrChallenge(request,id,code):delegate.verifyOrChallenge(request,id,code);}
        public Proof verify(Request r){
            assertThat(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive()).isFalse();before.run();
            if(mode.equals("THROW"))throw new IllegalStateException("sensitive-provider-token");if(mode.equals("NULL"))return null;
            return new Proof(mode.equals("ACCOUNT")?UUID.randomUUID():r.accountId(),mode.equals("SESSION")?UUID.randomUUID():r.sessionId(),mode.equals("INSTALLATION")?UUID.randomUUID():r.installationId(),mode.equals("PLATFORM")?"INVALID":r.platform(),mode.equals("TOKEN")?"0".repeat(64):com.narudzbine.identity.application.DeviceService.hash(r.token()),mode.equals("ENVIRONMENT")?"production":"synthetic",mode.equals("PROJECT")?"production-project":"synthetic-project",mode.equals("EXPIRED")?CLOCK.instant().minusSeconds(60):mode.equals("FUTURE")?CLOCK.instant().plusSeconds(1):CLOCK.instant());
        }
    }
    private JsonNode inboxPreferences(String token)throws Exception{var r=send("GET","/me/notification-preferences",null,"Authorization","Bearer "+token);assertThat(r.statusCode()).as(r.body()).isEqualTo(200);return json(r);}
    private HttpResponse<String> inboxPut(String token,JsonNode current,String event,boolean enabled)throws Exception{var b=JSON.createObjectNode().put("expectedRevision",current.path("revision").asString());var events=b.putArray("events");if(event!=null)events.addObject().put("event",event).put("inApp",enabled).put("email",false).put("push",false);return send("PUT","/me/notification-preferences",b.toString(),"Authorization","Bearer "+token);}
    private JsonNode inboxPage(String token,String query)throws Exception{var r=send("GET","/me/notifications"+query,null,"Authorization","Bearer "+token);assertThat(r.statusCode()).as(r.body()).isEqualTo(200);return json(r);}
    private HttpResponse<String> inboxRead(String token,UUID id)throws Exception{return send("PUT","/me/notifications/"+id+"/read",null,"Authorization","Bearer "+token);}
    private java.util.List<UUID> inboxWork(String email){return owner.query("SELECT id FROM inbox_work WHERE recipient_account_id=? AND state='QUEUED' ORDER BY sequence",(r,n)->r.getObject(1,UUID.class),accountFor(email));}
    private void inboxPublish(String email){for(UUID id:inboxWork(email)){app.getBean(com.narudzbine.notifications.infrastructure.InboxFanout.class).publish(id);}}
