    @Test void notificationRetentionPreservesFinalJobsAndDefersCallbackForUnmappedUncertainty()throws Exception{
        String email=businessAccount("RS","BUYER","STAFF");requestReset(email);UUID proof=owner.queryForObject("SELECT id FROM password_reset_proof WHERE account_id=? AND state='ACTIVE'",UUID.class,accountFor(email));var provider=new DeliveryEmail();
        try(var engine=deliveryEngine(provider,null)){
            deliveryMaterialize(engine);UUID job=deliveryJob("RESET",proof,"EMAIL",accountFor(email));assertThat(engine.process(job)).isTrue();UUID reference=provider.references.get(job);String id="msg_"+UUID.randomUUID();assertThat(deliveryCallback(reference,"email.delivered",id,true).statusCode()).isEqualTo(200);String callbackHash=owner.queryForObject("SELECT payload_hash FROM email_callback WHERE id=?",String.class,id);
            // Explicitly create unresolved work; never assume the shared HTTP database has no other uncertainty.
            String administrator=nativeToken(account());var invitation=json(setupInvite(administrator,UUID.randomUUID()+"@example.com","BA","BUYER"));UUID invitationId=UUID.fromString(invitation.path("id").asString()),issuer=owner.queryForObject("SELECT sender_id FROM setup_invitation WHERE id=?",UUID.class,invitationId);deliveryMaterialize(engine);UUID unresolved=deliveryJob("SETUP",invitationId,"EMAIL",issuer);provider.result=com.narudzbine.notifications.api.ProviderDelivery.Status.UNKNOWN;assertThat(engine.process(unresolved)).isTrue();assertThat(deliveryState(unresolved)).isEqualTo("UNKNOWN");
            CLOCK.advance(90L*86400);engine.compact();assertThat(retentionMaintenance().runOnce().deferredJobs()).isEmpty();assertThat(owner.queryForObject("SELECT metadata_retired AND attempts IS NULL AND provider_reference IS NULL AND rendered_destination IS NULL FROM external_job WHERE id=?",Boolean.class,job)).isTrue();assertThat(owner.queryForObject("SELECT NOT metadata_retired AND provider_reference=? AND event_type='email.delivered' AND received_at IS NOT NULL FROM email_callback WHERE id=?",Boolean.class,reference,id)).isTrue();assertThat(owner.queryForObject("SELECT NOT metadata_retired AND state='UNKNOWN' AND provider_reference IS NULL FROM external_job WHERE id=?",Boolean.class,unresolved)).isTrue();assertThat(owner.queryForObject("SELECT payload_hash FROM email_callback WHERE id=?",String.class,id)).isEqualTo(callbackHash);assertProblem(deliveryCallback(reference,"email.failed",id,true),403,"FORBIDDEN");
            CLOCK.advance(-90L*86400);assertThat(deliveryCallback(reference,"email.delivered",id,true).statusCode()).isEqualTo(200);deliveryMaterialize(engine);assertThat(engine.process(job)).isFalse();assertThat(provider.ids).containsExactly(job,unresolved);assertThat(deliveryState(job)).isEqualTo("DELIVERED");
        }
    }
