    private static final FakeQuarantine QUARANTINE=new FakeQuarantine();
    static class FakeQuarantine implements com.narudzbine.media.api.PrivateQuarantine {
        final java.util.Set<String> markers=ConcurrentHashMap.newKeySet();final Map<String,byte[]> objects=new ConcurrentHashMap<>();final java.util.Set<String> failBefore=ConcurrentHashMap.newKeySet(),loseAfter=ConcurrentHashMap.newKeySet(),failDelete=ConcurrentHashMap.newKeySet();final Map<String,Runnable> hooks=new ConcurrentHashMap<>();final AtomicInteger writes=new AtomicInteger(),calls=new AtomicInteger();
        @Override public void ensure(String key,java.nio.file.Path file,long bytes,String sha,String md5,String type){if(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive()){throw new AssertionError("Storage transaction boundary");}calls.incrementAndGet();if(markers.contains(key)){throw new com.narudzbine.media.api.MediaFailure("SERVICE_UNAVAILABLE");}if(failBefore.remove(key)){throw new com.narudzbine.media.api.MediaFailure("SERVICE_UNAVAILABLE");}try{byte[] body=java.nio.file.Files.readAllBytes(file);assertThat(body.length).isEqualTo(bytes);assertThat(java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(body))).isEqualTo(sha);byte[] old=objects.putIfAbsent(key,body);if(old==null){writes.incrementAndGet();}else{assertThat(old).isEqualTo(body);}Runnable hook=hooks.remove(key);if(hook!=null){hook.run();}if(loseAfter.remove(key)){throw new com.narudzbine.media.api.MediaFailure("SERVICE_UNAVAILABLE");}}catch(java.io.IOException|java.security.GeneralSecurityException e){throw new IllegalStateException(e);}}
        public byte[] content(String key,long bytes,String sha){if(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive()){throw new AssertionError("Download transaction boundary");}calls.incrementAndGet();byte[] body=objects.get(key);Runnable hook=hooks.remove(key);if(hook!=null){hook.run();}if(body==null){throw new com.narudzbine.media.api.MediaFailure("SERVICE_UNAVAILABLE");}return body.clone();}
        @Override public void fenceProcessed(String key){delete(key);}
        @Override public void delete(String key){if(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive()){throw new AssertionError("Delete transaction boundary");}if(failDelete.remove(key)){throw new com.narudzbine.media.api.MediaFailure("SERVICE_UNAVAILABLE");}objects.remove(key);markers.add(key);}
    }
    private static byte[] uploadPng(){return new byte[]{(byte)137,80,78,71,13,10,26,10,0,0,0,0};}
    private UUID uploadId(){return app.getBean(com.narudzbine.shared.api.UuidGenerator.class).next();}
    private static String uploadKey(StockFixture f,UUID id){return "quarantine/"+f.vendor()+"/"+id;}
    private HttpRequest uploadRequest(String token,UUID id,byte[] bytes,String type){return HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/v1/media/assets/"+id+"/upload")).timeout(java.time.Duration.ofSeconds(30)).header("Authorization","Bearer "+token).header("Content-Type",type).PUT(HttpRequest.BodyPublishers.ofByteArray(bytes)).build();}
    private HttpResponse<String> uploadSend(String token,UUID id,byte[] bytes,String type)throws Exception{return client.send(uploadRequest(token,id,bytes,type),HttpResponse.BodyHandlers.ofString());}
    private HttpResponse<String> uploadRead(String token,UUID id)throws Exception{return send("GET","/media/assets/"+id,null,"Authorization","Bearer "+token);}

    @Test void mediaUploadsInitialAndFinalAuditFailuresAreAtomic()throws Exception{
        for(boolean finalWrite:java.util.List.of(false,true)){var f=stockFixture("RS");UUID id=uploadId();String key=uploadKey(f,id);int calls=QUARANTINE.calls.get();if(finalWrite){QUARANTINE.hooks.put(key,()->owner.execute("REVOKE INSERT ON audit_event FROM http_runtime"));}else{owner.execute("REVOKE INSERT ON audit_event FROM http_runtime");}try{assertProblem(uploadSend(f.token(),id,uploadPng(),"image/png"),503,"SERVICE_UNAVAILABLE");}finally{owner.execute("GRANT SELECT,INSERT ON audit_event TO http_runtime");}assertThat(owner.queryForObject("SELECT count(*) FROM media_processing_job WHERE asset_id=?",Integer.class,id)).isZero();if(finalWrite){assertThat(QUARANTINE.objects).containsKey(key);assertThat(owner.queryForObject("SELECT raw_confirmed_at IS NULL FROM media_upload WHERE asset_id=?",Boolean.class,id)).isTrue();CLOCK.advance(120);}else{assertThat(QUARANTINE.calls.get()).isEqualTo(calls);assertProblem(uploadRead(f.token(),id),404,"NOT_FOUND");}assertThat(uploadSend(f.token(),id,uploadPng(),"image/png").statusCode()).isEqualTo(202);assertThat(owner.queryForObject("SELECT count(*) FROM audit_event WHERE resource_id=? AND action='UPLOAD_QUARANTINED'",Integer.class,id)).isEqualTo(1);}
    }
