    private UUID galleryAsset(UUID vendor,String state)throws Exception{
        UUID id=app.getBean(com.narudzbine.shared.api.UuidGenerator.class).next();var at=java.sql.Timestamp.from(CLOCK.instant());
        if(state.equals("READY")){owner.update("INSERT INTO media_asset(id,vendor_id,state,media_type,processed_key,processed_sha256,processed_bytes,width,height,created_at,ready_at,unreferenced_at) VALUES (?,?,'READY','image/png',?,decode(repeat('ab',32),'hex'),100,100,80,?,?,?)",id,vendor,"processed/"+id,at,at,at);}
        else{owner.update("INSERT INTO media_asset(id,vendor_id,state,media_type,created_at) VALUES (?,?,?,'image/png',?)",id,vendor,state,at);}return id;
    }
    private tools.jackson.databind.node.ObjectNode galleryBody(JsonNode current,UUID... ids){var b=JSON.createObjectNode();b.put("expectedRevision",current.path("revision").asString());var array=b.putArray("assetIds");for(UUID id:ids){array.add(id.toString());}return b;}
    private HttpResponse<String> gallerySend(String token,JsonNode product,UUID... ids)throws Exception{return send("PUT","/catalogue/products/"+product.path("id").asString()+"/gallery",galleryBody(product,ids).toString(),"Authorization","Bearer "+token);}
    private Object galleryTimer(UUID id){return owner.queryForObject("SELECT unreferenced_at FROM media_asset WHERE id=?",java.sql.Timestamp.class,id);}

