    private tools.jackson.databind.node.ObjectNode bulkBody(String token,UUID... ids)throws Exception{
        var body=JSON.createObjectNode();var targets=body.putArray("targets");for(UUID id:ids){var p=productGet(token,id);var price=pricingGet(token,id);targets.addObject().put("productId",id.toString()).put("expectedRevision",p.path("revision").asString()).put("expectedPricingRevision",price.path("revision").asString());}return body;
    }
    private HttpResponse<String> bulkSend(String token,JsonNode body)throws Exception{return send("POST","/catalogue/bulk-edits",body.toString(),"Authorization","Bearer "+token);}

