    @Test void cancellationsCompetingDuplicatesAcceptanceAndRejectionHaveOneWinner()throws Exception{
        for(String competing:java.util.List.of("DUPLICATE","ACCEPTANCE","REJECTION")){
            var f=reviewFixture("RS");var stock=f.offer().stock();reconEnable(stock,reconAcknowledgeAll(stock,reconPrepare(stock)));stockSet(stock,stockGet(stock),5,null);var order=historyOrder(f);String id=order.path("id").asString();
            try(var c=java.sql.DriverManager.getConnection(DATABASE.getJdbcUrl(),DATABASE.getUsername(),DATABASE.getPassword())){c.setAutoCommit(false);try(var q=c.prepareStatement("SELECT id FROM organization WHERE id IN (?,?) ORDER BY id FOR UPDATE")){q.setObject(1,f.offer().buyer());q.setObject(2,stock.vendor());q.execute();}var a=client.sendAsync(request("POST","/orders/"+id+"/cancellation",cancellationBody(order,"Cancel"),"Authorization","Bearer "+f.offer().buyerToken()),HttpResponse.BodyHandlers.ofString());String action=competing.equals("DUPLICATE")?"cancellation":competing.equals("ACCEPTANCE")?"acceptance":"rejection";var b=JSON.createObjectNode().put("expectedRevision",order.path("revision").asString());if(action.equals("acceptance")){b.putNull("fulfillmentLocationId");}else{b.put("reason",action.equals("cancellation")?"Cancel":"Reject");}var other=client.sendAsync(request("POST","/orders/"+id+"/"+action,JSON.writeValueAsString(b),"Authorization","Bearer "+(action.equals("cancellation")?f.offer().buyerToken():stock.token())),HttpResponse.BodyHandlers.ofString());awaitRuntimeBlockedBy(c,"cancellation contenders wait for sorted pair guards");c.commit();if(competing.equals("DUPLICATE")){assertThat(a.get().statusCode()).as(a.get().body()).isEqualTo(200);assertThat(other.get().statusCode()).as(other.get().body()).isEqualTo(200);assertThat(json(a.get())).isEqualTo(json(other.get()));}else{assertThat(java.util.List.of(a.get().statusCode(),other.get().statusCode())).containsExactlyInAnyOrder(200,409);}}
            var current=orderRead(f.offer().buyerToken(),UUID.fromString(id));assertThat(stockGet(stock).path("availableCount").asInt()).isEqualTo(current.path("state").asString().equals("ACCEPTED")?3:5);assertThat(owner.queryForObject("SELECT count(*) FROM purchase_order_event WHERE order_id=?",Integer.class,UUID.fromString(id))).isEqualTo(2);
        }
    }
