    @Test void cancellationsMultiLineCreditFailureAfterFirstLineRollsBackAll()throws Exception{
        var f=reviewFixture("BA");var stock=f.offer().stock();var item=json(productCreate(stock.token(),"credit-line-two","Credit line two"));UUID second=UUID.fromString(item.path("id").asString());var values=productBody(item);values.put("unitId",productGet(stock.token(),stock.product()).path("unitId").asString());assertThat(productUpdate(stock.token(),item,values).statusCode()).isEqualTo(200);assertThat(pricingPut(stock.token(),second,pricingBody(pricingGet(stock.token(),second),"12",java.util.List.of())).statusCode()).isEqualTo(200);var other=new StockFixture(stock.email(),stock.token(),stock.vendor(),second);assertThat(publication(other,true,productGet(stock.token(),second)).statusCode()).isEqualTo(200);reconEnable(stock,reconAcknowledgeAll(stock,reconPrepare(stock)));stockSet(stock,stockGet(stock),5,null);stockSet(other,stockGet(other),6,null);var body=reviewBody(f);body.path("intent").path("lines").asArray().addObject().put("productId",second.toString()).put("quantity",3);var response=orderSend(f,reviewSaved(f,body),UUID.randomUUID().toString());assertThat(response.statusCode()).isEqualTo(201);var order=json(response);var balanceOne=stockGet(stock);var balanceTwo=stockGet(other);owner.execute("CREATE FUNCTION fail_synthetic_second_credit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.product_id='"+java.util.stream.Stream.of(stock.product(),second).max(java.util.Comparator.comparing(UUID::toString)).orElseThrow()+"'::uuid THEN RAISE EXCEPTION 'Synthetic second-line failure';END IF;RETURN NEW;END $$");owner.execute("CREATE TRIGGER tr_synthetic_second_credit BEFORE INSERT ON order_stock_credit FOR EACH ROW EXECUTE FUNCTION fail_synthetic_second_credit()");try{assertProblem(cancelOrder(f.offer().buyerToken(),order,"Cannot fulfill all"),503,"SERVICE_UNAVAILABLE");}finally{owner.execute("DROP TRIGGER tr_synthetic_second_credit ON order_stock_credit");owner.execute("DROP FUNCTION fail_synthetic_second_credit()");}assertThat(stockGet(stock)).isEqualTo(balanceOne);assertThat(stockGet(other)).isEqualTo(balanceTwo);assertThat(cancelOrder(f.offer().buyerToken(),order,"Cannot fulfill all").statusCode()).isEqualTo(200);assertThat(stockGet(stock).path("availableCount").asInt()).isEqualTo(5);assertThat(stockGet(other).path("availableCount").asInt()).isEqualTo(6);assertThat(stockGet(stock).path("cancellationCreditQuantity").asInt()).isZero();assertThat(stockGet(other).path("cancellationCreditQuantity").asInt()).isZero();assertThat(owner.queryForObject("SELECT count(*) FROM order_stock_credit WHERE order_id=?",Integer.class,UUID.fromString(order.path("id").asString()))).isEqualTo(2);
    }
    private String orderBody(JsonNode review){return JSON.writeValueAsString(Map.of("reviewId",review.path("id").asString()));}
    private HttpResponse<String> orderSend(ReviewFixture f,JsonNode review,String key)throws Exception{return send("POST","/orders",orderBody(review),"Authorization","Bearer "+f.offer().buyerToken(),"Idempotency-Key",key);}
    private JsonNode orderRead(String token,UUID id)throws Exception{var r=send("GET","/orders/"+id,null,"Authorization","Bearer "+token);assertThat(r.statusCode()).as(r.body()).isEqualTo(200);return json(r);}
    private int orderCount(ReviewFixture f){return owner.queryForObject("SELECT count(*) FROM purchase_order WHERE buyer_id=?",Integer.class,f.offer().buyer());}

    private record ReviewFixture(OfferFixture offer,JsonNode location){}
    private ReviewFixture reviewFixture(String country)throws Exception{var offer=offerFixture(country);var response=send("POST","/organization/locations",JSON.writeValueAsString(locationBody(country,true)),"Authorization","Bearer "+offer.buyerToken());assertThat(response.statusCode()).as(response.body()).isEqualTo(201);return new ReviewFixture(offer,json(response));}
    private tools.jackson.databind.node.ObjectNode reviewBody(ReviewFixture f){var b=JSON.createObjectNode();var intent=draftBody(f.offer(),true).path("intent").deepCopy();intent.asObject().put("deliveryLocationId",f.location().path("id").asString());b.set("intent",intent);b.putNull("draftId");b.putNull("draftRevision");return b;}
    private HttpResponse<String> reviewSend(ReviewFixture f,JsonNode body)throws Exception{return send("POST","/order-reviews",JSON.writeValueAsString(body),"Authorization","Bearer "+f.offer().buyerToken());}
    private JsonNode reviewSaved(ReviewFixture f,JsonNode body)throws Exception{var r=reviewSend(f,body);assertThat(r.statusCode()).as(r.body()).isEqualTo(201);assertThat(r.headers().firstValue("Location")).contains("/api/v1/order-reviews/"+json(r).path("id").asString());return json(r);}
    private int reviewCount(ReviewFixture f){return owner.queryForObject("SELECT count(*) FROM order_review WHERE buyer_id=?",Integer.class,f.offer().buyer());}
    private String reviewHash(JsonNode r){return owner.queryForObject("SELECT encode(terms_hash,'hex') FROM order_review WHERE id=?",String.class,UUID.fromString(r.path("id").asString()));}
