    private static void awaitPlanWaiters(java.sql.Connection c)throws Exception{int pid;try(var q=c.createStatement();var r=q.executeQuery("SELECT pg_backend_pid()")){r.next();pid=r.getInt(1);}long deadline=System.nanoTime()+1_500_000_000L;boolean waiting=false;while(System.nanoTime()<deadline){if(owner.queryForObject("WITH RECURSIVE blocked(pid) AS (SELECT pid FROM pg_stat_activity WHERE ?=ANY(pg_blocking_pids(pid)) UNION SELECT a.pid FROM pg_stat_activity a JOIN blocked b ON b.pid=ANY(pg_blocking_pids(a.pid))) SELECT count(*) FROM blocked b JOIN pg_stat_activity a ON a.pid=b.pid WHERE a.usename='http_runtime' AND a.wait_event_type='Lock'",Integer.class,pid)==2){waiting=true;break;}Thread.sleep(10);}assertThat(waiting).as("both plan commands wait on vendor guard").isTrue();}
