    private static final java.util.concurrent.atomic.AtomicReference<ReportSnapshotPause> REPORT_SNAPSHOT_PAUSE=new java.util.concurrent.atomic.AtomicReference<>();
    private static final class ReportSnapshotPause {
        final UUID organization;
        final java.util.concurrent.CountDownLatch computed=new java.util.concurrent.CountDownLatch(1),release=new java.util.concurrent.CountDownLatch(1);
        final java.util.concurrent.atomic.AtomicBoolean claimed=new java.util.concurrent.atomic.AtomicBoolean();
        volatile boolean readOnly,repeatableRead;
        ReportSnapshotPause(UUID organization){this.organization=organization;}
    }
    private static final class ControlledReports implements com.narudzbine.reporting.api.BusinessReports {
        private final com.narudzbine.reporting.api.BusinessReports delegate;
        ControlledReports(com.narudzbine.reporting.api.BusinessReports delegate){this.delegate=delegate;}
        public Summary summary(Scope scope,Range range,String grouping){return after(scope,delegate.summary(scope,range,grouping));}
        public Page<Product> products(Scope scope,Range range,int page,int size,boolean total){return after(scope,delegate.products(scope,range,page,size,total));}
        public Page<Buyer> buyers(Scope scope,Range range,int page,int size,boolean total){return after(scope,delegate.buyers(scope,range,page,size,total));}
        private <T>T after(Scope scope,T result){
            var pause=REPORT_SNAPSHOT_PAUSE.get();
            if(pause!=null&&pause.organization.equals(scope.organizationId())&&pause.claimed.compareAndSet(false,true)){
                var jdbc=app.getBean(JdbcTemplate.class);
                pause.readOnly="on".equals(jdbc.queryForObject("SHOW transaction_read_only",String.class));
                pause.repeatableRead="repeatable read".equals(jdbc.queryForObject("SHOW transaction_isolation",String.class));
                pause.computed.countDown();
                try{if(!pause.release.await(10,java.util.concurrent.TimeUnit.SECONDS))throw new IllegalStateException("Synthetic report pause expired.");}
                catch(InterruptedException interrupted){Thread.currentThread().interrupt();throw new IllegalStateException("Synthetic report pause interrupted.",interrupted);}
            }
            return result;
        }
    }

