    static class TestClock extends Clock {
        private volatile Instant now = Instant.parse("2026-10-17T12:00:00Z");
        void advance(long seconds) { now = now.plusSeconds(seconds); }
        public ZoneId getZone() { return ZoneOffset.UTC; }
        public Clock withZone(ZoneId zone) { return this; }
        private volatile long liveStarted;private volatile Instant liveBase;
        void live(){liveBase=now;liveStarted=System.nanoTime();}
        public Instant instant() { return liveBase==null?now:liveBase.plusNanos(System.nanoTime()-liveStarted).truncatedTo(java.time.temporal.ChronoUnit.MILLIS); }
    }
