    private static final java.util.List<String> RECOVERY_TABLES=java.util.List.of("organization","business_account","account_identity","application_session","credential_operation","purchase_order","purchase_order_line","order_number_counter","stock_balance","stock_event","trading_relationship","outbox_event","external_job","inbox_work","order_notice","order_delivery","external_fanout");
    private static Map<String,String> recoveryFingerprints(java.sql.Connection connection)throws Exception{
        var result=new java.util.TreeMap<String,String>();
        for(String table:RECOVERY_TABLES){
            String sql="SELECT count(*) AS records,encode(sha256(convert_to(coalesce(string_agg(row_digest,',' ORDER BY row_digest),''),'UTF8')),'hex') AS digest FROM(SELECT encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex') AS row_digest FROM public."+table+" t) s";
            try(var statement=connection.createStatement()){statement.setQueryTimeout(20);try(var rows=statement.executeQuery(sql)){rows.next();result.put(table,rows.getLong("records")+":"+rows.getString("digest"));}}
        }
        return result;
    }
    private static byte[] recoveryLogicalDump(String snapshot,java.nio.file.Path errors)throws Exception{
        String application="synthetic-recovery-dump-"+UUID.randomUUID();
        var process=new ProcessBuilder("docker","exec","-e","PGAPPNAME="+application,DATABASE.getContainerId(),"pg_dump","-U",DATABASE.getUsername(),"-d",DATABASE.getDatabaseName(),"--format=custom","--no-owner","--no-privileges","--snapshot="+snapshot).redirectError(errors.toFile()).start();
        var reader=java.util.concurrent.Executors.newSingleThreadExecutor();
        try{
            byte[] bytes=reader.submit(()->process.getInputStream().readNBytes(com.narudzbine.shared.infrastructure.recovery.BackupEnvelope.MAX_PLAINTEXT+1)).get(90,java.util.concurrent.TimeUnit.SECONDS);
            assertThat(bytes.length).as("compressed synthetic dump within the supported bound").isBetween(5,com.narudzbine.shared.infrastructure.recovery.BackupEnvelope.MAX_PLAINTEXT);
            assertThat(process.waitFor(10,java.util.concurrent.TimeUnit.SECONDS)).as("logical dump exited").isTrue();assertThat(process.exitValue()).as("logical dump completed successfully").isZero();
            assertThat(java.util.Arrays.copyOf(bytes,5)).containsExactly((byte)'P',(byte)'G',(byte)'D',(byte)'M',(byte)'P');return bytes;
        }finally{
            if(process.isAlive())owner.queryForList("SELECT pg_cancel_backend(pid) FROM pg_stat_activity WHERE application_name=? AND datname=current_database()",application);
            process.destroyForcibly();process.getInputStream().close();reader.shutdownNow();reader.awaitTermination(5,java.util.concurrent.TimeUnit.SECONDS);
        }
    }
    private static void recoveryRestoreDump(PostgreSQLContainer target,byte[] dump,java.nio.file.Path errors)throws Exception{
        var process=new ProcessBuilder("docker","exec","-i",target.getContainerId(),"pg_restore","-U",target.getUsername(),"-d",target.getDatabaseName(),"--single-transaction","--exit-on-error","--no-owner","--no-privileges").redirectError(errors.toFile()).redirectOutput(ProcessBuilder.Redirect.DISCARD).start();
        var writer=java.util.concurrent.Executors.newSingleThreadExecutor();
        try{
            writer.submit(()->{try(var output=process.getOutputStream()){output.write(dump);}return true;}).get(90,java.util.concurrent.TimeUnit.SECONDS);
            assertThat(process.waitFor(30,java.util.concurrent.TimeUnit.SECONDS)).as("isolated restore exited").isTrue();assertThat(process.exitValue()).as("isolated transactional restore completed").isZero();
        }finally{process.destroyForcibly();writer.shutdownNow();writer.awaitTermination(5,java.util.concurrent.TimeUnit.SECONDS);}
    }
    private static JdbcTemplate recoveryArchivePrincipal(String role){
        var base=new org.springframework.jdbc.datasource.DriverManagerDataSource(DATABASE.getJdbcUrl(),DATABASE.getUsername(),DATABASE.getPassword());
        return new JdbcTemplate(new org.springframework.jdbc.datasource.DelegatingDataSource(base){@Override public java.sql.Connection getConnection()throws java.sql.SQLException{var c=super.getConnection();try(var q=c.createStatement()){q.execute("SET ROLE "+role);q.execute("SET TIME ZONE 'UTC'");q.execute("SET statement_timeout='10s'");q.execute("SET lock_timeout='2s'");}return c;}});
    }
