            var targeted=promotionBody(country);targeted.set("endsAt",JSON.valueToTree(promotionLocal(CLOCK.instant().plusSeconds(3600),country)));targeted.put("name","Batch selected");targeted.put("kind","FIXED_UNIT_PRICE");targeted.put("value","50.00");targeted.put("productMode","SELECTED");targeted.set("productIds",JSON.valueToTree(java.util.List.of(agreedProduct)));targeted.put("buyerMode","SELECTED");targeted.set("buyerIds",JSON.valueToTree(java.util.List.of(offer.buyer())));assertThat(promotionSend(seller.token(),"POST","",targeted).statusCode()).isEqualTo(201);
