            var body=reviewBody(fixture);var requested=body.path("intent").asObject().putArray("lines");var quantities=new java.util.LinkedHashMap<UUID,Integer>();
            for(UUID id:ids){int quantity=id.equals(tierProduct)?5:id.equals(agreedProduct)?2:1;requested.addObject().put("productId",id.toString()).put("quantity",quantity);quantities.put(id,quantity);}
