    private List<UUID> fanoutMembers(UUID organization,int active){
        var ids=app.getBean(com.narudzbine.shared.api.UuidGenerator.class);var members=new java.util.ArrayList<UUID>();
        var accounts=new java.util.ArrayList<Object[]>();var memberships=new java.util.ArrayList<Object[]>();
        for(int index=0;index<active+2;index++){
            UUID id=ids.next();members.add(id);
            accounts.add(new Object[]{id,id+"@example.test",index!=active+1,index==active?"DEACTIVATED":index==active+1?"PENDING":"ACTIVE"});
            memberships.add(new Object[]{id,organization});
        }
        setup.executeWithoutResult(status->{
            owner.batchUpdate("INSERT INTO account_identity(id,kind,email,email_verified,display_name,state) VALUES(?,'BUSINESS',?,?,'Synthetic fanout member',?)",accounts);
            owner.batchUpdate("INSERT INTO business_account(id,organization_id,role) VALUES(?,?,'STAFF')",memberships);
            owner.update("UPDATE account_identity SET language_override='en' WHERE id=?",members.getFirst());
        });
        return List.copyOf(members);
    }

    @Test @org.junit.jupiter.api.Timeout(90)
    void submittedNoticeFanoutCrossesBatchBoundaryWithExactRecipientsLocalesAndReplay() throws Exception {
        for(String country:List.of("RS","BA")){
            var fixture=reviewFixture(country);UUID vendor=fixture.offer().stock().vendor();
            var members=fanoutMembers(vendor,250);var review=reviewSaved(fixture,reviewBody(fixture));String key=UUID.randomUUID().toString();
            var submitted=orderSend(fixture,review,key);assertThat(submitted.statusCode()).isEqualTo(201);
            UUID order=UUID.fromString(json(submitted).path("id").asString());
            assertThat(owner.queryForObject("SELECT count(*) FROM order_notice WHERE order_id=? AND event_id IS NULL",Long.class,order)).isEqualTo(251);
            assertThat(owner.queryForObject("SELECT count(*) FROM order_delivery d JOIN order_notice n ON n.id=d.notice_id WHERE n.order_id=?",Long.class,order)).isEqualTo(753);
            assertThat(owner.queryForObject("SELECT count(*) FROM order_notice n JOIN account_identity a ON a.id=n.recipient_account_id JOIN organization o ON o.id=n.organization_id WHERE n.order_id=? AND n.locale IS DISTINCT FROM COALESCE(a.language_override,o.default_language)",Long.class,order)).isZero();
            assertThat(owner.queryForObject("SELECT count(*) FROM order_notice WHERE order_id=? AND recipient_account_id IN (?,?)",Long.class,order,members.get(250),members.get(251))).isZero();
            for(String channel:List.of("IN_APP","EMAIL","PUSH"))assertThat(owner.queryForObject("SELECT count(*) FROM order_delivery d JOIN order_notice n ON n.id=d.notice_id WHERE n.order_id=? AND d.channel=? AND d.state='QUEUED' AND d.expires_at=d.created_at+interval '24 hours'",Long.class,order,channel)).isEqualTo(251);
            var replay=orderSend(fixture,review,key);assertThat(replay.statusCode()).isEqualTo(201);assertThat(json(replay).path("id").asString()).isEqualTo(order.toString());
            assertThat(owner.queryForObject("SELECT count(*) FROM order_notice WHERE order_id=?",Long.class,order)).isEqualTo(251);
            assertThat(owner.queryForObject("SELECT count(*) FROM order_delivery d JOIN order_notice n ON n.id=d.notice_id WHERE n.order_id=?",Long.class,order)).isEqualTo(753);
        }
    }

    @Test @org.junit.jupiter.api.Timeout(90)
    void lateFanoutBatchFailureRollsBackOrderReplayAndEveryOutboxChunk() throws Exception {
        var fixture=reviewFixture("RS");UUID vendor=fixture.offer().stock().vendor(),buyer=fixture.offer().buyer();
        fanoutMembers(vendor,250);
        UUID last=owner.queryForObject("SELECT a.id FROM account_identity a JOIN business_account b ON b.id=a.id WHERE b.organization_id=? AND a.state='ACTIVE' AND a.email_verified ORDER BY a.id DESC LIMIT 1",UUID.class,vendor);
        var review=reviewSaved(fixture,reviewBody(fixture));String key=UUID.randomUUID().toString();
        owner.execute("CREATE SEQUENCE synthetic_fanout_progress");
        owner.execute("GRANT USAGE ON SEQUENCE synthetic_fanout_progress TO http_runtime");
        owner.execute("CREATE FUNCTION synthetic_fanout_late_failure() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN PERFORM nextval('synthetic_fanout_progress');IF EXISTS(SELECT 1 FROM order_notice WHERE id=NEW.notice_id AND recipient_account_id='"+last+"'::uuid) THEN RAISE EXCEPTION 'Synthetic late fanout failure' USING ERRCODE='55000';END IF;RETURN NEW;END $$");
        owner.execute("CREATE TRIGGER zz_synthetic_fanout_late_failure BEFORE INSERT ON order_delivery FOR EACH ROW EXECUTE FUNCTION synthetic_fanout_late_failure()");
        try{
            assertProblem(orderSend(fixture,review,key),503,"SERVICE_UNAVAILABLE");
            assertThat(owner.queryForObject("SELECT last_value FROM synthetic_fanout_progress",Long.class)).as("First750 delivery inserts ran before second-chunk failure").isEqualTo(751);
            assertThat(owner.queryForObject("SELECT count(*) FROM purchase_order WHERE buyer_id=?",Long.class,buyer)).isZero();
            assertThat(owner.queryForObject("SELECT count(*) FROM order_submission_replay WHERE buyer_id=?",Long.class,buyer)).isZero();
            assertThat(owner.queryForObject("SELECT count(*) FROM order_notice WHERE organization_id=?",Long.class,vendor)).isZero();
        }finally{
            owner.execute("DROP TRIGGER IF EXISTS zz_synthetic_fanout_late_failure ON order_delivery");
            owner.execute("DROP FUNCTION IF EXISTS synthetic_fanout_late_failure()");
            owner.execute("DROP SEQUENCE IF EXISTS synthetic_fanout_progress");
        }
        var retry=orderSend(fixture,review,key);assertThat(retry.statusCode()).as("Explicit retry uses the same unconsumed review/key after definite rollback").isEqualTo(201);
        UUID order=UUID.fromString(json(retry).path("id").asString());
        assertThat(owner.queryForObject("SELECT count(*) FROM order_notice WHERE order_id=?",Long.class,order)).isEqualTo(251);
        assertThat(owner.queryForObject("SELECT count(*) FROM order_delivery d JOIN order_notice n ON n.id=d.notice_id WHERE n.order_id=?",Long.class,order)).isEqualTo(753);
    }

    @Test @org.junit.jupiter.api.Timeout(90)
    void readAdmissionNeverSubstitutesForCurrentLockedAuthorization() throws Exception {
        for (String country : List.of("RS", "BA")) {
            for (boolean offers : List.of(false, true)) {
                var fixture = reviewFixture(country);
                String token = offers ? fixture.offer().buyerToken() : fixture.offer().stock().token();
                String path = offers ? "/vendors/" + fixture.offer().stock().vendor() + "/offers?size=25"
                        : "/catalogue/products?size=25";
                byte[] tokenHash = java.security.MessageDigest.getInstance("SHA-256")
                        .digest(token.getBytes(java.nio.charset.StandardCharsets.US_ASCII));
                UUID actor = owner.queryForObject("SELECT account_id FROM application_session WHERE token_hash=?",
                        UUID.class, tokenHash);
                var activity = owner.queryForObject("SELECT last_qualified_activity_at FROM application_session WHERE token_hash=?",
                        Timestamp.class, tokenHash);
                CLOCK.advance(1);
                var mac = javax.crypto.Mac.getInstance("HmacSHA256");
                mac.init(new javax.crypto.spec.SecretKeySpec(Base64.getDecoder().decode(
                        app.getEnvironment().getRequiredProperty("identity.http.throttle-key")), "HmacSHA256"));
                byte[] admissionKey = mac.doFinal(("email\u0000api/" + actor)
                        .getBytes(java.nio.charset.StandardCharsets.UTF_8));
                long before = owner.queryForObject("SELECT count(*) FROM login_attempt WHERE email_key=?",
                        Long.class, admissionKey);
                try (var worker = java.util.concurrent.Executors.newSingleThreadExecutor();
                        var revocation = fixtureSource.getConnection()) {
                    revocation.setAutoCommit(false);
                    // Credential changes acquire organization before account, like real mutation paths.
                    try (var statement = revocation.prepareStatement("SELECT id FROM organization WHERE id=(SELECT organization_id FROM business_account WHERE id=?) FOR UPDATE")) {
                        statement.setObject(1, actor); statement.executeQuery().close();
                    }
                    try (var statement = revocation.prepareStatement("SELECT id FROM account_identity WHERE id=? FOR UPDATE")) {
                        statement.setObject(1, actor); statement.executeQuery().close();
                    }
                    int blocker;
                    try (var statement = revocation.createStatement(); var row = statement.executeQuery("SELECT pg_backend_pid()")) {
                        row.next(); blocker = row.getInt(1);
                    }
                    var request = worker.submit(() -> send("GET", path, null, "Authorization", "Bearer " + token));
                    try {
                        boolean admittedAndBlocked = false;
                        long deadline = System.nanoTime() + java.util.concurrent.TimeUnit.SECONDS.toNanos(1);
                        while (System.nanoTime() < deadline) {
                            long attempts = owner.queryForObject("SELECT count(*) FROM login_attempt WHERE email_key=?", Long.class, admissionKey);
                            long blocked = owner.queryForObject("SELECT count(*) FROM pg_stat_activity WHERE datname=current_database() AND ?=ANY(pg_blocking_pids(pid))", Long.class, blocker);
                            if (attempts == before + 1 && blocked > 0) { admittedAndBlocked = true; break; }
                            Thread.sleep(10);
                        }
                        assertThat(admittedAndBlocked).as("Technical admission commits before final locked authorization: %s", path).isTrue();
                        assertThat(request.isDone()).isFalse();
                        try (var statement = revocation.prepareStatement("UPDATE account_identity SET security_epoch=security_epoch+1 WHERE id=?")) {
                            statement.setObject(1, actor); assertThat(statement.executeUpdate()).isEqualTo(1);
                        }
                        revocation.commit();
                        assertProblem(request.get(10, java.util.concurrent.TimeUnit.SECONDS), 401, "INVALID_SESSION");
                        assertThat(owner.queryForObject("SELECT last_qualified_activity_at FROM application_session WHERE token_hash=?", Timestamp.class, tokenHash)).isEqualTo(activity);
                    } finally { revocation.rollback(); }
                }
            }
        }
    }

