    public static final class LocalLoad {
        private record LoadPair(ReviewFixture buyer,java.util.List<UUID> products){}
        public static void main(String[] args)throws Exception {
            if(args.length!=1||!java.util.Set.of("--check","--full").contains(args[0])||!"true".equals(System.getenv("LOCAL_SYNTHETIC_ACKNOWLEDGED"))||System.getenv().containsKey("OPERATIONS_RECOVERY_CONTAINED"))throw new IllegalArgumentException("Synthetic load only");
            localSyntheticLoad=true;
            localLoadExternalDatabase="true".equals(System.getenv("LOCAL_SYNTHETIC_EXTERNAL_DATABASE"));
            boolean full=args[0].equals("--full");int pairs=50,productsPerVendor=full?5000:100,historyPerVendor=full?2000:10;
            String run=System.getenv().getOrDefault("LOCAL_SYNTHETIC_RUN_ID",UUID.randomUUID().toString());if(UUID.fromString(run).version()!=4)throw new IllegalArgumentException("Synthetic UUIDv4 run required");var pool=java.util.concurrent.Executors.newFixedThreadPool(100);
            DATABASE.withCommand(LocalLoadPostgresProfile.command()).withSharedMemorySize(LocalLoadPostgresProfile.SHARED_MEMORY_BYTES).withLabel("com.narudzbine.synthetic-load",run);
            System.setProperty("server.address","127.0.0.1");System.setProperty("management.server.address","127.0.0.1");
            DATABASE.withCreateContainerCmdModifier(command->command.getHostConfig().withPortBindings(new com.github.dockerjava.api.model.PortBinding(com.github.dockerjava.api.model.Ports.Binding.bindIpAndPort("127.0.0.1",0),new com.github.dockerjava.api.model.ExposedPort(5432))));
            try {
                DATABASE.start();if(localLoadExternalDatabase){
                    try(var connection=java.sql.DriverManager.getConnection(DATABASE.getJdbcUrl(),DATABASE.getUsername(),DATABASE.getPassword());
                        var statement=connection.prepareStatement("SELECT current_setting('narudzbine.synthetic_run_id',true)");var rows=statement.executeQuery()){
                        if(!rows.next()||!run.equals(rows.getString(1))){throw new IllegalStateException("Synthetic external database identity mismatch; no migration permitted");}
                    }
                }CLOCK.now=Instant.now().minusSeconds(60L*86400).truncatedTo(java.time.temporal.ChronoUnit.MILLIS);AuthHttpIT.start();long loadContextStarted=System.nanoTime();owner.execute("CREATE EXTENSION pg_stat_statements");var databaseProfile=LocalLoadPostgresProfile.observe(owner);loadFixtureSessions=true;System.out.println("fixture-database-profile "+JSON.writeValueAsString(databaseProfile));
                var f=new AuthHttpIT();String admin=f.nativeToken(account());var fixtures=new java.util.ArrayList<ReviewFixture>();
                for(int n=0;n<pairs;n++){
                    var fixture=f.reviewFixture(n%2==0?"RS":"BA");fixtures.add(fixture);var stock=fixture.offer().stock();
                    assertThat(f.assignPlan(admin,stock.vendor(),f.currentPlan(admin,stock.vendor(),true),planId("PRO"),"Synthetic design-load entitlement").statusCode()).isEqualTo(200);
                    for(int member=0;member<9;member++){addMember(stock.vendor(),"STAFF");addMember(fixture.offer().buyer(),"STAFF");}
                }
                for(int batch=0;batch<(productsPerVendor-1+999)/1000;batch++){
                    if(batch==3)CLOCK.advance(3601);int selected=batch;var jobs=new java.util.ArrayList<java.util.concurrent.Future<?>>();
                    var semaphore=new java.util.concurrent.Semaphore(1);
                    for(var fixture:fixtures)jobs.add(pool.submit(()->{try{semaphore.acquire();var stock=fixture.offer().stock();UUID unit=owner.queryForObject("SELECT unit_id FROM catalogue_product_identity WHERE id=?",UUID.class,stock.product());var csv=new StringBuilder("sku,name,unitId,basePrice,activate\n");int start=1+selected*1000,end=Math.min(productsPerVendor,start+1000);for(int n=start;n<end;n++)csv.append("load-").append(n).append(",Load ").append(n).append(',').append(unit).append(",100.00,true\n");long began=System.nanoTime();var preview=f.csvSaved(stock.token(),csv.toString());assertThat(preview.path("valid").asBoolean()).isTrue();long confirmation=System.nanoTime();assertThat(f.csvConfirm(stock.token(),preview).statusCode()).isEqualTo(200);loadTimings.computeIfAbsent("fixture:csv",k->new java.util.concurrent.ConcurrentLinkedQueue<>()).add(System.nanoTime()-confirmation);System.out.println("fixture-csv rows="+(end-start)+" elapsedMs="+(System.nanoTime()-began)/1_000_000);}catch(Exception e){throw new RuntimeException(e);}finally{semaphore.release();}}));
                    for(var job:jobs)job.get(1800,java.util.concurrent.TimeUnit.SECONDS);System.out.println("fixture-csv-batch="+batch+" vendors="+pairs);
                }
                var load=new java.util.ArrayList<LoadPair>();
                for(var fixture:fixtures){var stock=fixture.offer().stock();var all=owner.queryForList("SELECT id FROM catalogue_product WHERE vendor_id=? ORDER BY id",UUID.class,stock.vendor());assertThat(all.size()).isEqualTo(productsPerVendor);load.add(new LoadPair(fixture,java.util.List.copyOf(all.subList(0,100))));}
                Instant historyStart=CLOCK.instant().plusSeconds(60);var historyJobs=new java.util.ArrayList<java.util.concurrent.Future<?>>();var historySlots=new java.util.concurrent.Semaphore(5);
                for(var pair:load)historyJobs.add(pool.submit(()->{try{historySlots.acquire();var order=lifecycle(f,pair,null);long began=System.nanoTime();SyntheticOrderHistory.seed(owner,UUID.fromString(order.path("id").asString()),historyPerVendor-1,historyStart,app.getBean(com.narudzbine.shared.api.ResourceRevisions.class),app.getBean(com.narudzbine.shared.api.UuidGenerator.class));System.out.println("fixture-history orders="+historyPerVendor+" lines="+(historyPerVendor*100)+" elapsedMs="+(System.nanoTime()-began)/1_000_000);}catch(Exception e){throw new RuntimeException(e);}finally{historySlots.release();}}));
                for(var job:historyJobs)job.get(3600,java.util.concurrent.TimeUnit.SECONDS);
                assertThat(owner.queryForObject("SELECT count(*) FROM organization",Integer.class)).isEqualTo(pairs*2);
                assertThat(owner.queryForObject("SELECT count(*) FROM business_account",Integer.class)).isEqualTo(pairs*20);
                assertThat(owner.queryForObject("SELECT count(*) FROM catalogue_product",Integer.class)).isEqualTo(pairs*productsPerVendor);
                assertThat(owner.queryForObject("SELECT count(*) FROM purchase_order_line",Long.class)).isEqualTo((long)pairs*historyPerVendor*100);
                fixtureSource.close();fixtureSource=new HikariDataSource();fixtureSource.setPoolName("load-monitor-owner");fixtureSource.setJdbcUrl(DATABASE.getJdbcUrl());fixtureSource.setUsername(DATABASE.getUsername());fixtureSource.setPassword(DATABASE.getPassword());fixtureSource.setMaximumPoolSize(2);fixtureSource.setMinimumIdle(1);fixtureSource.setConnectionInitSql("SET narudzbine.operator_change_reference='SYN-PRIVATE-HTTP'");owner=new JdbcTemplate(fixtureSource);setup=new TransactionTemplate(new DataSourceTransactionManager(fixtureSource));
                owner.execute("VACUUM (ANALYZE)");owner.execute("CHECKPOINT");loadFixtureQualified=true;owner.execute("SELECT pg_stat_statements_reset()");System.out.println("fixture-qualified vacuumAnalyzeCheckpoint=passed bulkLoaderPoolReleased=true runtimePool="+app.getBean(com.zaxxer.hikari.HikariDataSource.class).getMaximumPoolSize());
                CLOCK.now=historyStart.plusSeconds(51L*86400);var refreshed=new java.util.ArrayList<LoadPair>();
                for(var pair:load){var fixture=pair.buyer();var old=fixture.offer();var stock=old.stock();var fresh=new StockFixture(stock.email(),f.nativeToken(stock.email()),stock.vendor(),stock.product());var buyer=new ReviewFixture(new OfferFixture(fresh,old.buyerEmail(),f.nativeToken(old.buyerEmail()),old.buyer(),old.relationship()),fixture.location());refreshed.add(new LoadPair(buyer,pair.products()));assertThat(f.orderRead(buyer.offer().buyerToken(),owner.queryForObject("SELECT id FROM purchase_order WHERE vendor_id=? ORDER BY sequence_number DESC LIMIT 1",UUID.class,stock.vendor())).path("state").asString()).isEqualTo("DELIVERED");}
                CLOCK.live();System.out.println("fixture-ready organizations="+(pairs*2)+" accounts="+(pairs*20)+" products="+(pairs*productsPerVendor)+" historicalLines="+((long)pairs*historyPerVendor*100));
                String ready=System.getenv("LOCAL_LOAD_MEASURE_AFTER");if(full&&ready!=null){long wait=System.nanoTime();while(!java.nio.file.Files.isRegularFile(java.nio.file.Path.of(ready))){if(System.nanoTime()-wait>java.util.concurrent.TimeUnit.MINUTES.toNanos(40))throw new IllegalStateException("Verification marker missing; no measurement started");Thread.sleep(1000);}if(!java.nio.file.Files.readString(java.nio.file.Path.of(ready)).trim().equals("VERIFIED"))throw new IllegalStateException("Verification marker rejected");}
                for(var pair:refreshed){try{lifecycle(f,pair,null);}catch(Exception|AssertionError failure){if(!full||failure instanceof InterruptedException)throw failure;loadWarmFailures.incrementAndGet();}warmReads(f,pair,full);}System.out.println("fixture-warmup completed allMeasuredReadRoutes=true failures="+loadWarmFailures.get());
                long maintenanceDelay=app.getEnvironment().getProperty("identity.http.maintenance.initial-delay-ms",Long.class,0L);
                if(maintenanceDelay!=60000){throw new IllegalStateException("Normal load maintenance policy required");}
                while(System.nanoTime()-loadContextStarted<java.util.concurrent.TimeUnit.MILLISECONDS.toNanos(maintenanceDelay)){Thread.sleep(250);}
                long maintenanceContextAge=java.util.concurrent.TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-loadContextStarted);
                System.out.println("fixture-maintenance-eligible initialDelayMs="+maintenanceDelay+" contextAgeMs="+maintenanceContextAge);
                var databaseStatisticsBeforeMeasurement=LocalLoadPostgresProfile.statistics(owner);
                long cpuStart=((com.sun.management.OperatingSystemMXBean)java.lang.management.ManagementFactory.getOperatingSystemMXBean()).getProcessCpuTime();long wallStart=System.nanoTime();
                var phases=new java.util.ArrayList<Map<String,Object>>();phases.add(phase(f,refreshed,pool,"sustained",50,full?1800:30,full));phases.add(phase(f,refreshed,pool,"burst",100,full?300:90,full));
                var metrics=new java.util.TreeMap<String,Object>();boolean targets=true;
                for(var entry:loadTimings.entrySet()){var values=entry.getValue().stream().mapToLong(Long::longValue).sorted().toArray();double p95=values[Math.min(values.length-1,(int)Math.ceil(values.length*.95)-1)]/1_000_000.0;String kind=entry.getKey().split(":")[1];double bound=kind.equals("read")?500:kind.equals("submission")?2000:kind.equals("report")?5000:kind.equals("csv")?30000:1000;targets&=p95<bound;metrics.put(entry.getKey(),Map.of("count",values.length,"p95ms",p95,"targetMs",bound));}
                var statuses=new java.util.TreeMap<String,Long>();loadStatuses.forEach((code,count)->statuses.put(code.toString(),count.sum()));boolean success=loadWarmFailures.get()==0&&loadStatuses.keySet().stream().allMatch(code->code==200||code==201)&&phases.stream().allMatch(phase->((Number)phase.get("failedTasks")).longValue()==0);
                var result=new java.util.LinkedHashMap<String,Object>();result.put("syntheticOnly",true);result.put("runId",run);result.put("databaseProfile",databaseProfile);result.put("maintenanceInitialDelayMs",maintenanceDelay);result.put("maintenanceEligibleBeforeMeasurement",maintenanceContextAge>=maintenanceDelay);result.put("runtimeAvailableProcessors",Runtime.getRuntime().availableProcessors());result.put("databaseStatisticsBeforeMeasurement",databaseStatisticsBeforeMeasurement);result.put("databaseStatisticsAfterMeasurement",LocalLoadPostgresProfile.statistics(owner));result.put("fullScale",full);boolean achieved=phases.stream().allMatch(phase->((Number)phase.get("droppedScheduledRequests")).longValue()==0&&((Number)phase.get("achievedRps")).doubleValue()>=((Number)phase.get("targetRps")).doubleValue()*.99);result.put("designAcceptance",full&&targets&&success&&achieved&&loadSubmissionPeak.get()>=5);result.put("organizations",pairs*2);result.put("accounts",pairs*20);result.put("activeBusinessUsers",pairs*2);result.put("products",pairs*productsPerVendor);result.put("generatedHistoricalOrders",pairs*(historyPerVendor-1));result.put("actualTemplateOrders",pairs);result.put("historicalLines",(long)pairs*historyPerVendor*100);result.put("historyGeneratedWithConstraintsEnabled",true);result.put("fixtureQualified",loadFixtureQualified);result.put("actualPlatformSetupAccounts",owner.queryForObject("SELECT count(*) FROM platform_account",Integer.class));result.put("allMeasuredTrafficActualHttp",true);result.put("stockTrackingInLoad",false);result.put("providersDisabled",true);result.put("phases",phases);result.put("latencies",metrics);result.put("statuses",statuses);result.put("postgres",owner.queryForMap("SELECT current_setting('fsync') AS fsync,current_setting('synchronous_commit') AS synchronous_commit,current_setting('full_page_writes') AS full_page_writes,pg_database_size(current_database()) AS database_bytes"));result.put("queues",owner.queryForMap("SELECT count(*) FILTER(WHERE expires_at>?) AS unexpired,count(*) FILTER(WHERE expires_at<=?) AS expired FROM order_delivery WHERE state='QUEUED'",Timestamp.from(CLOCK.instant()),Timestamp.from(CLOCK.instant())));result.put("runtimePoolMaximum",app.getBean(com.zaxxer.hikari.HikariDataSource.class).getMaximumPoolSize());result.put("localDatabaseMaxConnections",owner.queryForObject("SHOW max_connections",Integer.class));result.put("runtimeHeapMaxBytes",Runtime.getRuntime().maxMemory());result.put("runtimeHeapUsedAtEndBytes",java.lang.management.ManagementFactory.getMemoryMXBean().getHeapMemoryUsage().getUsed());result.put("runtimeCpuSeconds",(((com.sun.management.OperatingSystemMXBean)java.lang.management.ManagementFactory.getOperatingSystemMXBean()).getProcessCpuTime()-cpuStart)/1_000_000_000.0);result.put("measurementWallSeconds",(System.nanoTime()-wallStart)/1_000_000_000.0);result.put("warmupOrderIntents",pairs);result.put("warmupFailures",loadWarmFailures.get());result.put("peakConcurrentSubmissions",loadSubmissionPeak.get());var routes=new java.util.TreeMap<String,Object>();loadRoutes.forEach((route,times)->{long[] values=times.stream().mapToLong(Long::longValue).sorted().toArray();routes.put(route,Map.of("count",values.length,"p95ms",values[Math.min(values.length-1,(int)Math.ceil(values.length*.95)-1)]/1_000_000.0));});result.put("routes",routes);result.put("deadlocks",owner.queryForObject("SELECT deadlocks FROM pg_stat_database WHERE datname=current_database()",Long.class));result.put("oldestUnexpiredQueueAgeSeconds",owner.queryForObject("SELECT coalesce(extract(epoch FROM(?::timestamptz-min(created_at))),0) FROM order_delivery WHERE state='QUEUED' AND expires_at>?",java.math.BigDecimal.class,Timestamp.from(CLOCK.instant()),Timestamp.from(CLOCK.instant())));
                java.nio.file.Files.writeString(java.nio.file.Path.of("target/local-load-"+run+".json"),JSON.writeValueAsString(result));System.out.println("load-result "+JSON.writeValueAsString(result));if(full&&(!targets||!achieved||loadSubmissionPeak.get()<5)||!success)throw new IllegalStateException("Local load targets failed; inspect retained measurements");
            } finally {loadPhase=null;loadFixtureSessions=false;pool.shutdownNow();pool.awaitTermination(30,java.util.concurrent.TimeUnit.SECONDS);var partialRoutes=new java.util.TreeMap<String,Object>();loadRoutes.forEach((route,times)->{long[] values=times.stream().mapToLong(Long::longValue).sorted().toArray();if(values.length>0)partialRoutes.put(route,Map.of("completed",values.length,"p95ms",values[Math.min(values.length-1,(int)Math.ceil(values.length*.95)-1)]/1_000_000.0));});var partialStatuses=new java.util.TreeMap<Integer,Long>();loadStatuses.forEach((code,count)->partialStatuses.put(code,count.sum()));var partial=new java.util.LinkedHashMap<String,Object>();partial.put("runId",run);partial.put("syntheticOnly",true);partial.put("acceptance",false);partial.put("fixtureQualified",loadFixtureQualified);partial.put("warmupFailures",loadWarmFailures.get());partial.put("routes",partialRoutes);partial.put("statuses",partialStatuses);partial.put("completedPhases",List.copyOf(loadCompletedPhases));partial.put("peakConcurrentSubmissions",loadSubmissionPeak.get());if(owner!=null){try{partial.put("runtimeStatements",owner.queryForList("SELECT calls,total_exec_time,rows AS returned_rows,left(query,300) AS query FROM pg_stat_statements s JOIN pg_roles r ON r.oid=s.userid WHERE r.rolname='http_runtime' ORDER BY total_exec_time DESC LIMIT 35"));partial.put("databaseWaits",owner.queryForList("SELECT state,wait_event_type,wait_event,count(*) FROM pg_stat_activity WHERE usename='http_runtime' GROUP BY state,wait_event_type,wait_event"));}catch(org.springframework.dao.DataAccessException unavailable){partial.put("databaseDiagnosticsUnavailable",true);}}java.nio.file.Files.writeString(java.nio.file.Path.of("target/local-load-partial-"+run+".json"),JSON.writeValueAsString(partial));try{AuthHttpIT.stop();}finally{DATABASE.stop();}}
        }
        private static JsonNode lifecycle(AuthHttpIT f,LoadPair pair,java.util.concurrent.CyclicBarrier gate)throws Exception {
            var fixture=pair.buyer();var body=f.reviewBody(fixture);var lines=body.path("intent").asObject().putArray("lines");for(UUID product:pair.products())lines.addObject().put("productId",product.toString()).put("quantity",1);
            var review=f.reviewSaved(fixture,body);if(gate!=null)gate.await(10,java.util.concurrent.TimeUnit.SECONDS);
            var response=f.orderSend(fixture,review,UUID.randomUUID().toString());assertThat(response.statusCode()).as("Synthetic order submission").isEqualTo(201);String seller=fixture.offer().stock().token();var accepted=f.orderResponse(seller,json(response),true,null,null);assertThat(accepted.statusCode()).isEqualTo(200);var delivered=f.progressed(seller,f.progressed(seller,json(accepted),false),true);assertThat(delivered.path("state").asString()).isEqualTo("DELIVERED");return delivered;
        }
        private static int finishLoadTask(java.util.concurrent.Future<?> job,boolean retainFailure)throws Exception {
            try{job.get(30,java.util.concurrent.TimeUnit.SECONDS);return 0;}catch(java.util.concurrent.ExecutionException failure){if(!retainFailure)throw failure;return 1;}
        }
        private static void warmRead(AuthHttpIT f,String token,String path,boolean retainFailure)throws Exception {
            try{var response=f.send("GET",path,null,"Authorization","Bearer "+token);if(response.statusCode()!=200){if(!retainFailure)assertThat(response.statusCode()).as("Synthetic read warmup").isEqualTo(200);loadWarmFailures.incrementAndGet();System.out.println("warmup-http-error route="+path.replaceAll("[?].*","")+" status="+response.statusCode());}}
            catch(java.io.IOException failure){if(!retainFailure)throw failure;loadWarmFailures.incrementAndGet();System.out.println("warmup-transport-error route="+path.replaceAll("[?].*",""));}
        }
        private static void warmReads(AuthHttpIT f,LoadPair pair,boolean retainFailure)throws Exception {
            var fixture=pair.buyer();String vendor=fixture.offer().stock().token(),buyer=fixture.offer().buyerToken();
            for(String path:List.of("/me","/orders?size=25","/catalogue/products?size=25","/me/notifications?size=25","/reports/summary?from="+CLOCK.instant().minusSeconds(60L*86400).atZone(ZoneId.of("Europe/Belgrade")).toLocalDate()+"&to="+CLOCK.instant().atZone(ZoneId.of("Europe/Belgrade")).toLocalDate()+"&grouping=DAY"))warmRead(f,vendor,path,retainFailure);
            for(String path:List.of("/me","/orders?size=25","/me/notifications?size=25","/vendors/"+fixture.offer().stock().vendor()+"/offers?size=25"))warmRead(f,buyer,path,retainFailure);
        }
        private static Map<String,Object> phase(AuthHttpIT f,List<LoadPair> pairs,java.util.concurrent.ExecutorService pool,String name,int rps,int seconds,boolean retainFailures)throws Exception {
            loadPhase=name;long start=System.nanoTime();int droppedSeconds=0,lateSeconds=0,failedTasks=0,scheduledOrders=0;var pending=new java.util.concurrent.ConcurrentLinkedQueue<java.util.concurrent.Future<?>>();
            for(int second=0;second<seconds;second++){
                long deadline=start+second*1_000_000_000L,pause=deadline-System.nanoTime();if(pause>0)java.util.concurrent.TimeUnit.NANOSECONDS.sleep(pause);
                for(var iterator=pending.iterator();iterator.hasNext();){var job=iterator.next();if(job.isDone()){failedTasks+=finishLoadTask(job,retainFailures);iterator.remove();}}
                boolean late=System.nanoTime()-deadline>1_000_000_000L;if(late&&!retainFailures)throw new IllegalStateException("Load scheduler behind target");if(late)lateSeconds++;
                boolean dropped=late||pending.size()>100;
                if(dropped)droppedSeconds++;
                else{
                    var gate=new java.util.concurrent.CyclicBarrier(5);for(int n=0;n<5;n++){var pair=pairs.get((second*5+n)%pairs.size());pending.add(pool.submit(()->{try{lifecycle(f,pair,gate);}catch(Exception e){throw new RuntimeException(e);}}));}scheduledOrders+=5;
                    int reads=rps-25;
                    for(int n=0;n<reads;n++){
                        int i=second*reads+n;var pair=pairs.get((i/2)%pairs.size());boolean report=n==0&&second%5==0,vendor=i%2==0||report;String token=vendor?pair.buyer().offer().stock().token():pair.buyer().offer().buyerToken();
                        String path=report?"/reports/summary?from="+CLOCK.instant().minusSeconds(60L*86400).atZone(ZoneId.of("Europe/Belgrade")).toLocalDate()+"&to="+CLOCK.instant().atZone(ZoneId.of("Europe/Belgrade")).toLocalDate()+"&grouping=DAY":switch(i%7){case 0->"/me";case 1->"/orders?size=25";case 2->"/me/notifications?size=25";default->vendor?"/catalogue/products?size=25":"/vendors/"+pair.buyer().offer().stock().vendor()+"/offers?size=25";};
                        pending.add(pool.submit(()->{try{assertThat(f.send("GET",path,null,"Authorization","Bearer "+token).statusCode()).as("Synthetic load read").isEqualTo(200);}catch(Exception e){throw new RuntimeException(e);}}));long due=deadline+(n+1)*1_000_000_000L/reads;pause=due-System.nanoTime();if(pause>0)java.util.concurrent.TimeUnit.NANOSECONDS.sleep(pause);
                    }
                }
                for(var iterator=pending.iterator();iterator.hasNext();){var job=iterator.next();if(job.isDone()){failedTasks+=finishLoadTask(job,retainFailures);iterator.remove();}}
                if(!retainFailures&&pending.size()>200)throw new IllegalStateException("Load clients saturated");
                if(second%30==0){var observed=app.getBean(javax.sql.DataSource.class).unwrap(HikariDataSource.class).getHikariPoolMXBean();System.out.println("load-progress phase="+name+" elapsedSeconds="+second+" scheduledRps="+rps+" unfinished="+pending.size()+" droppedSeconds="+droppedSeconds+" failedTasks="+failedTasks+" poolActive="+observed.getActiveConnections()+" poolWaiting="+observed.getThreadsAwaitingConnection());}
            }
            for(var job:pending)failedTasks+=finishLoadTask(job,retainFailures);double elapsed=(System.nanoTime()-start)/1_000_000_000.0;loadPhase=null;long issued=loadIssued.containsKey(name)?loadIssued.get(name).sum():0;
            var result=new java.util.LinkedHashMap<String,Object>();result.put("phase",name);result.put("targetRps",rps);result.put("targetSeconds",seconds);result.put("elapsedSeconds",elapsed);result.put("actualHttpRequests",issued);result.put("achievedRps",issued/elapsed);result.put("scheduledOrderIntents",scheduledOrders);result.put("synchronizedSubmissionGroup",5);result.put("droppedScheduledRequests",(long)droppedSeconds*rps);result.put("plannedRequests",(long)seconds*rps);result.put("lateSeconds",lateSeconds);result.put("failedTasks",failedTasks);loadCompletedPhases.add(result);return result;
        }
    }

